def custom_achievement_purchase_dispatch(
    item_id,
    purchase_succeeded,
    holiday_furniture_enabled,
    persisted_mask=0,
):
    """Pure model for the native purchase wrapper and hidden 0xA8 mask."""
    mask = int(persisted_mask)
    if not purchase_succeeded:
        return None, mask
    if item_id in CUSTOM_ACHIEVEMENT_GENERAL_PURCHASE_GOALS:
        return CUSTOM_ACHIEVEMENT_GENERAL_PURCHASE_GOALS[item_id], mask
    if not holiday_furniture_enabled:
        return None, mask
    purchase_bit = CUSTOM_ACHIEVEMENT_TATERS_PURCHASE_BITS.get(item_id)
    if purchase_bit is not None:
        old_purchase_mask = mask & CUSTOM_ACHIEVEMENT_PURCHASE_MASK_ALL
        updated_purchase_mask = old_purchase_mask | purchase_bit
        updated_mask = (
            mask & ~CUSTOM_ACHIEVEMENT_PURCHASE_MASK_ALL
        ) | updated_purchase_mask
        completed_now = (
            old_purchase_mask != CUSTOM_ACHIEVEMENT_PURCHASE_MASK_ALL
            and updated_purchase_mask == CUSTOM_ACHIEVEMENT_PURCHASE_MASK_ALL
        )
        return (0x74 if completed_now else None), updated_mask
    return CUSTOM_ACHIEVEMENT_HOLIDAY_PURCHASE_GOALS.get(item_id), mask


def custom_achievement_praise_label_dispatch(label):
    return CUSTOM_ACHIEVEMENT_PRAISE_LABEL_GOALS.get(label)


def custom_achievement_scold_label_dispatch(label, internal_age=None):
    goal_id = CUSTOM_ACHIEVEMENT_SCOLD_LABEL_GOALS.get(label)
    if label in CUSTOM_ACHIEVEMENT_CHILD_SCOLD_LABELS:
        if internal_age is None or int(internal_age) >= 0x118:
            return None
    return goal_id


def custom_achievement_props_is_satisfied(completed_ids):
    completed = {int(achievement_id) for achievement_id in completed_ids}
    return (
        CUSTOM_ACHIEVEMENT_TIGHT_SHIP_ID in completed
        and all(
            achievement_id in completed
            for achievement_id in range(
                CUSTOM_ACHIEVEMENT_DISCIPLINE_FIRST_ID,
                CUSTOM_ACHIEVEMENT_DISCIPLINE_LAST_ID + 1,
            )
        )
    )


def longevity_achievement_ids_for_internal_age(internal_age):
    """Return every sequential longevity goal satisfied by one raw age."""
    age = int(internal_age)
    rows = (
        (70 * 20, 0x85),
        (80 * 20, 0x86),
        (90 * 20, 0x87),
        (100 * 20, 0x88),
        (122 * 20 + 1, 0x89),
    )
    return [achievement_id for threshold, achievement_id in rows if age >= threshold]


def pet_achievement_ids_for_item(item_id, active=True):
    """Return the pet goals earned by one active, placed pet item."""
    item = int(item_id)
    if not active or item < 0x23B or item > 0x248:
        return []
    goals = [0x8A]
    if item <= 0x23F:
        goals.append(0x8B)
    elif item <= 0x244:
        goals.append(0x8C)
    elif item == 0x245:
        goals.append(CUSTOM_ACHIEVEMENT_TURTLE_ID)
    elif item == 0x246:
        goals.append(0x8F)
    elif item == 0x247:
        goals.append(0x8E)
    elif item == 0x248:
        goals.append(0x8D)
    return goals


