    stock_spawn_reset_relocs = [
        struct.unpack_from(
            "<IIH",
            stock_collectable_obj.buf,
            stock_spawn_reset_sec.reloc_ptr + index * 10,
        )
        for index in range(stock_spawn_reset_sec.nreloc)
    ]
