def patch_tool_tray_outfit_normalization(manifest):
    obj = CoffObject(PATCHED / "ToolTray.obj")
    helper_sym = obj.append_undefined_symbol("_VF2NormalizeOutfitToolInHand")

    def patch_getter(function_name, active_flag_offset):
        sym = obj.symbol(function_name)
        sec = obj.section(sym.section)
        raw = sec.raw_ptr + sym.value
        expected = (
            b"\x80\xB9" + struct.pack("<I", active_flag_offset) + b"\x00"
            b"\x74\x0A"
            b"\x8B\x81\xA0\x00\x00\x00"
            b"\x8B\x04\xC1"
            b"\xC3"
            b"\x33\xC0"
            b"\xC3"
        )
        if obj.buf[raw : raw + len(expected)] != expected:
            raise RuntimeError(f"Unexpected {function_name} body bytes")
        payload = (
            b"\x68" + struct.pack("<I", active_flag_offset)  # push active flag offset
            + b"\x51"                                      # push this
            + b"\xE8\x00\x00\x00\x00"                      # call helper
            + b"\x83\xC4\x08"                              # add esp,8
            + b"\xC3"                                      # ret
        )
        payload += b"\x90" * (len(expected) - len(payload))
        obj.buf[raw : raw + len(expected)] = payload
        obj.append_relocation(sym.section, sym.value + 7, helper_sym, IMAGE_REL_I386_REL32)
        return {
            "function": function_name,
            "active_flag_offset": hex(active_flag_offset),
            "helper": "_VF2NormalizeOutfitToolInHand",
            "overwritten_bytes": len(expected),
        }

    patches = [
        patch_getter("?GetToolInHand@CToolTray@@QAE?AW4EInventoryItem@@XZ", 0xA4),
        patch_getter("?GetToolInUse@CToolTray@@QAE?AW4EInventoryItem@@XZ", 0xA5),
    ]
    obj.write(PATCHED / "ToolTray.obj")
    manifest["outfit_tooltray_normalization"] = {
        "status": "synthetic outfit tray IDs normalize to stock IDs only for vanilla application checks",
        "synthetic_ranges": {gender: hex(base) for gender, base in OUTFIT_STORE_GENDER_ITEM_BASES.items()},
        "stock_mapping": {
            "male": "0x49",
            "female": "0x4a",
        },
        "patches": patches,
        "note": "ToolTray storage, save data, and icon drawing keep the independent synthetic item ID.",
    }


def patch_main_scene_outfit_body_apply(manifest):
    obj = CoffObject(PATCHED / "theMainScene.obj")
    helper_sym = obj.append_undefined_symbol("_VF2ResolveOutfitBodyForApply")
    sym = obj.symbol("?HandleMouseDown@theMainScene@@IAE?B_NUldwPoint@@@Z")
    sec = obj.section(sym.section)

    def patch_stock_getoutfit(offset, stock_item, gender_value):
        raw = sec.raw_ptr + sym.value + offset
        expected = (
            b"\x6A" + bytes([stock_item])
            + b"\xB9\x00\x00\x00\x00"
            + b"\xE8\x00\x00\x00\x00"
        )
        if obj.buf[raw : raw + len(expected)] != expected:
            raise RuntimeError(f"Unexpected outfit apply bytes at {hex(offset)}")
        payload = (
            b"\x6A" + bytes([gender_value])
            + b"\x6A" + bytes([stock_item])
            + b"\xE8\x00\x00\x00\x00"
            + b"\x83\xC4\x08"
        )
        payload += b"\x90" * (len(expected) - len(payload))
        obj.buf[raw : raw + len(expected)] = payload
        obj.append_relocation(sym.section, sym.value + offset + 5, helper_sym, IMAGE_REL_I386_REL32)
        return {
            "offset": hex(offset),
            "stock_item": hex(stock_item),
            "gender_value": gender_value,
            "helper": "_VF2ResolveOutfitBodyForApply",
        }

    patches = [
        patch_stock_getoutfit(0xCE3, 0x49, 0),
        patch_stock_getoutfit(0xD83, 0x4A, 1),
    ]

    obj.write(PATCHED / "theMainScene.obj")
    manifest["outfit_apply_body_resolver"] = {
        "status": "theMainScene outfit apply resolves selected synthetic tray item before writing villager body",
        "villager_body_offset": "0x6a84",
        "patches": patches,
        "note": "Stock outfit tools still fall back to InventoryManager male/female outfit body fields.",
    }


def patch_main_scene_random_tip_click(manifest):
    """Add the mobile random-tip click to the baked bottom-nav house image.

    The house is part of main_BG_ws.png (image 0x174), not a native control.
    HandleMouseDown therefore gets a small additive screen-coordinate test;
    all other stock mouse handling and the portrait/details control remain
    untouched.  Coordinates are relative to the native 1024x163 DrawUI strip.
    """
    obj = CoffObject(PATCHED / "theMainScene.obj")
    sym = obj.symbol("?HandleMouseDown@theMainScene@@IAE?B_NUldwPoint@@@Z")
    sec = obj.section(sym.section)
    insert_off = sym.value + 0x79
    raw = sec.raw_ptr + insert_off
    expected = b"\xE8\x00\x00\x00\x00"
    if bytes(obj.buf[raw : raw + len(expected)]) != expected:
        raise RuntimeError("theMainScene HandleMouseDown house-hit anchor drifted")

    # The stock invisible hit rectangle overlaps the authenticated tiny-house
    # target.  Patch it before either additive input insertion shifts the
    # function: +0x1132 here becomes +0x1166 in the run5 all-enabled layout.
    native_overlap_off = sym.value + 0x1132
    native_overlap_raw = sec.raw_ptr + native_overlap_off
    native_overlap_stock = b"\x3B\x8E\x98\x00\x00\x00"
    native_overlap_bypass = b"\xE9\x46\x00\x00\x00\x90"
    if bytes(obj.buf[
        native_overlap_raw : native_overlap_raw + len(native_overlap_stock)
    ]) != native_overlap_stock:
        raise RuntimeError("theMainScene native invisible house rectangle drifted")
    obj.buf[
        native_overlap_raw : native_overlap_raw + len(native_overlap_stock)
    ] = native_overlap_bypass

    helper_path = PATCHED / "vf2_special_upgrade_effects.cpp"
    if not helper_path.exists():
        raise RuntimeError("vf2_special_upgrade_effects.cpp missing before random-tip helper")
    helper_text = helper_path.read_text(encoding="ascii")
    helper_token = "VF2TryRandomTipHouseHit"
    click_sound_source = MOBILE_SOUND_ASSET_SOURCE_DIR / RANDOM_TIP_CLICK_SOUND_FILE
    if not click_sound_source.is_file():
        raise RuntimeError(f"Random-tip click sound asset is missing: {click_sound_source}")
    click_sound_sha256 = hashlib.sha256(click_sound_source.read_bytes()).hexdigest()
    if click_sound_sha256 != RANDOM_TIP_CLICK_SOUND_SHA256:
        raise RuntimeError(
            "Random-tip click sound asset identity mismatch: "
            f"expected {RANDOM_TIP_CLICK_SOUND_SHA256}, got {click_sound_sha256}"
        )
    dealer_say_call = "    DealerSay.Say((StringId)stringId, -1);"
    click_sound_call = (
        f"    Sound.Play(static_cast<ESound>(0x{RANDOM_TIP_CLICK_SOUND_ID:X}));"
    )
    if helper_token not in helper_text:
        helper_text += r'''

#ifndef VF2_RANDOM_TIP_HOUSE_HELPER_DEFINED
#define VF2_RANDOM_TIP_HOUSE_HELPER_DEFINED
class CDealerSay {
public:
    void Say(StringId stringId, int gender);
};
extern CDealerSay DealerSay;

extern "C" bool __cdecl VF2TryRandomTipHouseHit(
    void *scene,
    int screenX,
    int screenY
)
{
    if (!scene) return false;
    unsigned char *raw = reinterpret_cast<unsigned char *>(scene);
    const int stripX = *reinterpret_cast<int *>(raw + 0xA8);
    const int stripY = *reinterpret_cast<int *>(raw + 0x94)
        - *reinterpret_cast<int *>(raw + 0x8C) - 163;
    const int localX = screenX - stripX;
    const int localY = screenY - stripY;
    // Tiny house in the baked main_BG_ws.png 1024x163 bottom-navigation strip.
    if (localX < 232 || localX >= 257 || localY < 127 || localY >= 151) {
        return false;
    }
    const int stringId = ldwGameState::GetRandom(0x32) + 0x09E3;
    DealerSay.Say((StringId)stringId, -1);
    Sound.Play(static_cast<ESound>(0xBD));
    return true;
}
#endif
'''
    elif click_sound_call not in helper_text:
        if dealer_say_call not in helper_text:
            raise RuntimeError("Random-tip helper notification call drifted")
        helper_text = helper_text.replace(
            dealer_say_call,
            dealer_say_call + "\n" + click_sound_call,
            1,
        )
    if click_sound_call not in helper_text:
        raise RuntimeError("Random-tip helper sound call was not emitted")
    helper_path.write_text(helper_text.rstrip() + "\n", encoding="ascii")

    helper_sym = obj.append_undefined_symbol("_VF2TryRandomTipHouseHit")
    # The stock point arguments are already on the stack and ECX contains the
    # ToolTray singleton at this insertion point.  Preserve ECX across the
    # cdecl helper so the native ToolTray dispatch receives its original this
    # pointer on the false path.  A true result jumps to the existing stock
    # "return true" epilogue at +0xB2.
    payload = bytearray(
        b"\x51"               # preserve ToolTray this
        b"\xFF\x75\x0C"       # push [ebp+0C] (screen y)
        b"\xFF\x75\x08"       # push [ebp+08] (screen x)
        b"\x56"               # push esi (this)
        b"\xE8\x00\x00\x00\x00"
        b"\x83\xC4\x0C"
        b"\x59"               # restore ToolTray this
        b"\x84\xC0"
        b"\x74\x05"           # false: continue stock path
        b"\xE9\x00\x00\x00\x00"  # true: stock return-true epilogue
    )
    obj.insert_section_bytes(sym.section, insert_off, bytes(payload))
    obj.append_relocation(sym.section, insert_off + 9, helper_sym, IMAGE_REL_I386_REL32)
    # The insertion shifts the old +0xB2 target by len(payload), so the
    # relative displacement remains old_return - insertion_site.
    jmp_disp = sym.value + 0xB2 - insert_off
    struct.pack_into("<i", obj.buf, sec.raw_ptr + insert_off + 22, jmp_disp)
    obj.write(PATCHED / "theMainScene.obj")
    manifest["random_tip_bottom_house"] = {
        "status": "patched",
        "route": "theMainScene::HandleMouseDown additive coordinate overlay over baked main_BG_ws.png",
        "image_id": "0x174",
        "image_size": [1024, 163],
        "relative_rect": {"left": 232, "top": 127, "right": 257, "bottom": 151},
        "screen_rect_formula": "x=[this+0xA8]+relative; y=[this+0x94]-[this+0x8C]-163+relative",
        "function": "?HandleMouseDown@theMainScene@@IAE?B_NUldwPoint@@@Z",
        "insert_offset": "0x79",
        "stock_continuation": "false restores ToolTray ECX and falls through to native HandleMouseDown; true restores ECX then jumps to its existing return-true epilogue",
        "portrait_control_id1_untouched": True,
        "stock_control_id1_untouched": True,
        "string_id_first": "0x09E3",
        "string_id_last": "0x0A14",
        "string_id_count": 50,
        "selection": "GetRandom(0x32) + 0x09E3",
        "dealer_say": "CDealerSay::Say(StringId, -1) general notification channel",
        "success_sound": {
            "api": "CSound::Play(ESound)",
            "raw_id": hex(RANDOM_TIP_CLICK_SOUND_ID),
            "filename": RANDOM_TIP_CLICK_SOUND_FILE,
            "source": str(click_sound_source),
            "sha256": click_sound_sha256,
            "only_after_successful_house_hit": True,
        },
        "helper": "_VF2TryRandomTipHouseHit",
        "native_invisible_rect_bypass": {
            "source_object_offset": "0x1132",
            "run5_final_offset": "0x1166",
            "run5_target": "0x11B1",
            "patch_on": "E9 46 00 00 00 90",
            "patch_off": "3B 8E 98 00 00 00",
        },
        "evidence": (
            "authenticated run5 second-house half-open bounds over the baked "
            "bottom strip; stale native invisible rectangle bypassed"
        ),
    }


def patch_scrolling_store_scene(manifest):
    obj = CoffObject(PATCHED / "ScrollingStoreScene.obj")
    new_furniture_end = max(item_id_for(i) for i in range(len(ITEMS))) + 1
    patches = 0
    for reg in [b"\x3D", b"\x81\xFB", b"\x81\xFE", b"\x81\xF9", b"\x81\xFA"]:
        patches += patch_all_in_sections(
            obj,
            {".text$mn"},
            reg + struct.pack("<I", 0x2A9),
            reg + struct.pack("<I", new_furniture_end),
        )
    draw_sym = obj.symbol("?DrawVisibleStoreItem@CScrollingStoreScene@@AAEXHHH@Z")
    lock_helper_sym = obj.append_undefined_symbol("_VF2DrawGenerationLock")
    obj.retarget_relocation(draw_sym.section, draw_sym.value + 0x354, lock_helper_sym, IMAGE_REL_I386_REL32)

    # DrawVisibleStoreItem asks GetNumAvailable at +0x2C8 purely to decide
    # whether to draw the owned checkmark (image 0x27A) at +0x2D1; the click
    # handler asks the same method from its own separate call sites inside
    # HandleMouse. Retargeting only this one lets an armed pregnancy one-shot
    # show the checkmark while staying purchasable, so a repurchase can still
    # reach VF2ToggleOneShotUpgrade and cancel it. Verified against the stock
    # bytes first so a drifted anchor fails loudly instead of silently
    # retargeting some unrelated call.
    draw_section = obj.section(draw_sym.section)
    checkmark_call = draw_sym.value + 0x2C8
    checkmark_raw = draw_section.raw_ptr + checkmark_call
    if obj.buf[checkmark_raw] != 0xE8:
        raise RuntimeError(
            "DrawVisibleStoreItem checkmark GetNumAvailable call drifted at +0x2C8"
        )
    # test eax,eax / jne short -- the checkmark gate the returned value feeds.
    if bytes(obj.buf[checkmark_raw + 5:checkmark_raw + 8]) != bytes.fromhex("85C075"):
        raise RuntimeError(
            "DrawVisibleStoreItem checkmark gate drifted after the +0x2C8 call"
        )
    checkmark_helper_sym = obj.append_undefined_symbol("@VF2StoreDrawNumAvailable@12")
    obj.retarget_relocation(
        draw_sym.section, checkmark_call + 1, checkmark_helper_sym, IMAGE_REL_I386_REL32
    )

    scene_draw_sym = obj.symbol("?DrawScene@CScrollingStoreScene@@MAEXXZ")
    scrollbar_draw_helper = obj.append_undefined_symbol("_VF2DrawStoreScrollbar")
    draw_insert = scene_draw_sym.value + 0x154
    draw_payload = bytearray([
        0x57,                         # push edi ; this
        0xE8, 0, 0, 0, 0,             # call _VF2DrawStoreScrollbar
        0x83, 0xC4, 0x04,             # add esp, 4
    ])
    obj.insert_section_bytes(scene_draw_sym.section, draw_insert, draw_payload)
    obj.append_relocation(scene_draw_sym.section, draw_insert + 2, scrollbar_draw_helper, IMAGE_REL_I386_REL32)

    mouse_sym = obj.symbol("?HandleMouse@CScrollingStoreScene@@UAE_NHUldwPoint@@@Z")
    scrollbar_mouse_helper = obj.append_undefined_symbol("_VF2HandleStoreScrollbarMouse")
    mouse_insert = mouse_sym.value + 0x30
    mouse_payload = bytearray([
        0xFF, 0x75, 0x10,             # push [ebp+10h] ; y
        0xFF, 0x75, 0x0C,             # push [ebp+0Ch] ; x
        0xFF, 0x75, 0x08,             # push [ebp+8]   ; message
        0x57,                         # push edi       ; this
        0xE8, 0, 0, 0, 0,             # call helper
        0x83, 0xC4, 0x10,             # add esp, 10h
    ])
    obj.insert_section_bytes(mouse_sym.section, mouse_insert, mouse_payload)
    obj.append_relocation(mouse_sym.section, mouse_insert + 11, scrollbar_mouse_helper, IMAGE_REL_I386_REL32)

    purchase_sym = obj.symbol("?HandlePurchaseItem@CScrollingStoreScene@@AAEXXZ")
    purchase_insert = purchase_sym.value + 0x1AD
    purchase_sec = obj.section(purchase_sym.section)
    purchase_raw = purchase_sec.raw_ptr + purchase_insert
    expected_purchase_bytes = b"\x8B\x8E\x60\x01\x00\x00\x8B\xC1\x83\xF9\x04"
    if obj.buf[purchase_raw:purchase_raw + len(expected_purchase_bytes)] != expected_purchase_bytes:
        raise RuntimeError("Unexpected HandlePurchaseItem visible-special dispatch bytes")

    outfit_purchase_helper_sym = obj.append_undefined_symbol("_VF2PurchaseOutfitStoreItem")
    special_upgrade_helper_sym = obj.append_undefined_symbol("_VF2ApplyVisibleSpecialUpgrade")
    reversible_upgrade_helper_sym = obj.append_undefined_symbol("_VF2RemoveOwnedUpgrade")
    purchase_payload = bytearray()

    purchase_payload += b"\x8B\x86\x60\x01\x00\x00"                  # mov eax,[esi+160h]
    purchase_payload += b"\x50"                                      # push eax ; original item id
    purchase_payload += b"\xE8\x00\x00\x00\x00"                      # call _VF2RemoveOwnedUpgrade
    purchase_payload += b"\x83\xC4\x04"                              # add esp,4
    purchase_payload += b"\x84\xC0"                                  # test al,al
    purchase_payload += b"\x74\x05"                                  # jz outfit purchase test
    reversible_return_jmp_off = len(purchase_payload)
    purchase_payload += b"\xE9\x00\x00\x00\x00"                      # jmp post-save cleanup; helper saved
    if len(purchase_payload) != 0x18:
        raise RuntimeError("Unexpected reversible upgrade payload length")

    outfit_payload_start = len(purchase_payload)
    purchase_payload += b"\x8B\x86\x60\x01\x00\x00"                  # mov eax,[esi+160h]
    purchase_payload += b"\x50"                                      # push eax ; original item id
    purchase_payload += b"\xE8\x00\x00\x00\x00"                      # call _VF2PurchaseOutfitStoreItem
    purchase_payload += b"\x83\xC4\x04"                              # add esp,4
    purchase_payload += b"\x84\xC0"                                  # test al,al
    purchase_payload += b"\x74\x05"                                  # jz visible special purchase test
    outfit_return_jmp_off = len(purchase_payload)
    purchase_payload += b"\xE9\x00\x00\x00\x00"                      # jmp post-save cleanup; helper saved
    if len(purchase_payload) - outfit_payload_start != 0x18:
        raise RuntimeError("Unexpected outfit purchase payload length")

    special_payload_start = len(purchase_payload)
    purchase_payload += b"\x8B\x86\x60\x01\x00\x00"                  # mov eax,[esi+160h]
    purchase_payload += b"\x8B\xC8"                                  # mov ecx,eax
    max_visible_special_index = (
        max(item["item_id"] for item in CHEAT_UPGRADE_ITEMS)
        if ENABLE_CHEAT_UPGRADES
        else MOBILE_SPECIAL_UPGRADE_ITEM_IDS[-1]
    ) - MOBILE_SPECIAL_UPGRADE_ITEM_IDS[0]
    if ENABLE_MOBILE_RENOVATIONS or ENABLE_AI_GENERATED_BATHROOM2:
        max_visible_special_index = max(
            max_visible_special_index,
            MOBILE_RENOVATION_PC_ITEM_IDS[-1] - MOBILE_SPECIAL_UPGRADE_ITEM_IDS[0],
        )
    if ENABLE_AI_GENERATED_BATHROOM2:
        max_visible_special_index = max(
            max_visible_special_index,
            AI_BATHROOM2_PC_ITEM_IDS[-1] - MOBILE_SPECIAL_UPGRADE_ITEM_IDS[0],
        )
    purchase_payload += b"\x2D\x17\x01\x00\x00"                      # sub eax,117h
    purchase_payload += b"\x83\xF8" + bytes([max_visible_special_index])  # cmp eax,last added Special Upgrade index
    purchase_payload += b"\x77\x0E"                                  # ja normal visible purchase
    purchase_payload += b"\x51"                                      # push ecx ; original item id
    purchase_payload += b"\xE8\x00\x00\x00\x00"                      # call _VF2ApplyVisibleSpecialUpgrade
    purchase_payload += b"\x83\xC4\x04"                              # add esp,4
    special_return_jmp_off = len(purchase_payload)
    purchase_payload += b"\xE9\x00\x00\x00\x00"                      # jmp post-save cleanup; helper saved
    if len(purchase_payload) - special_payload_start != 0x20:
        raise RuntimeError("Unexpected visible Special Upgrades purchase payload length")
    return_after_purchase = purchase_sym.value + 0x31C + len(purchase_payload)
    for jmp_off in (reversible_return_jmp_off, outfit_return_jmp_off, special_return_jmp_off):
        rel_to_return = (return_after_purchase - (purchase_insert + jmp_off + 5)) & 0xFFFFFFFF
        purchase_payload[jmp_off + 1 : jmp_off + 5] = struct.pack("<I", rel_to_return)

    obj.insert_section_bytes(purchase_sym.section, purchase_insert, bytes(purchase_payload))
    obj.append_relocation(purchase_sym.section, purchase_insert + 8, reversible_upgrade_helper_sym, IMAGE_REL_I386_REL32)
    obj.append_relocation(purchase_sym.section, purchase_insert + outfit_payload_start + 8, outfit_purchase_helper_sym, IMAGE_REL_I386_REL32)
    obj.append_relocation(purchase_sym.section, purchase_insert + special_payload_start + 20, special_upgrade_helper_sym, IMAGE_REL_I386_REL32)

    price_multiplier_patches = []
    if ENABLE_CHEAT_UPGRADES:
        calc_sym = obj.symbol("?CalcPrice@CScrollingStoreScene@@AAEHW4EInventoryItem@@PA_N@Z")
        calc_sec = obj.section(calc_sym.section)
        career_tail_off = calc_sym.value + 0x79
        ordinary_tail_off = calc_sym.value + 0x83
        career_expected = b"\x0F\xAF\xC7\x5F\x5E\x5B\x5D\xC2\x08\x00"
        ordinary_expected = b"\x8B\xC7\x5F\x5E\x5B\x5D\xC2\x08\x00"
        if obj.buf[calc_sec.raw_ptr + career_tail_off : calc_sec.raw_ptr + career_tail_off + len(career_expected)] != career_expected:
            raise RuntimeError("Unexpected CalcPrice career-upgrade return path")
        if obj.buf[calc_sec.raw_ptr + ordinary_tail_off : calc_sec.raw_ptr + ordinary_tail_off + len(ordinary_expected)] != ordinary_expected:
            raise RuntimeError("Unexpected CalcPrice ordinary return path")

        multiplier_helper = obj.append_undefined_symbol("_VF2ApplyPriceMultiplier")
        calc_sec = obj.section(calc_sym.section)
        multiplier_stub_off = calc_sec.raw_size
        multiplier_stub = (
            b"\x50"                                      # push eax ; final calculated price
            b"\xE8\x00\x00\x00\x00"                  # call helper
            b"\x83\xC4\x04"                          # add esp,4
            b"\x5F\x5E\x5B\x5D"                      # restore registers/frame
            b"\xC2\x08\x00"                          # ret 8
        )
        obj.insert_section_bytes(calc_sym.section, multiplier_stub_off, multiplier_stub)
        obj.append_relocation(calc_sym.section, multiplier_stub_off + 2, multiplier_helper, IMAGE_REL_I386_REL32)
        calc_sym = obj.symbol("?CalcPrice@CScrollingStoreScene@@AAEHW4EInventoryItem@@PA_N@Z")
        calc_sec = obj.section(calc_sym.section)

        career_jump_off = calc_sym.value + 0x7C
        career_rel = multiplier_stub_off - (career_jump_off + 5)
        career_patch = b"\x0F\xAF\xC7\xE9" + struct.pack("<i", career_rel) + b"\x90\x90"
        obj.buf[calc_sec.raw_ptr + career_tail_off : calc_sec.raw_ptr + career_tail_off + len(career_patch)] = career_patch

        ordinary_jump_off = calc_sym.value + 0x85
        ordinary_rel = multiplier_stub_off - (ordinary_jump_off + 5)
        ordinary_patch = b"\x8B\xC7\xE9" + struct.pack("<i", ordinary_rel) + b"\x90\x90"
        obj.buf[calc_sec.raw_ptr + ordinary_tail_off : calc_sec.raw_ptr + ordinary_tail_off + len(ordinary_patch)] = ordinary_patch

        price_multiplier_patches = [
            {"path": "career upgrade", "offset": hex(career_tail_off)},
            {"path": "ordinary purchase", "offset": hex(ordinary_tail_off)},
        ]

