def patch_next_generation_age_gate(manifest):
    """Expose the native Next Generation flow when the oldest villager is 60+."""
    native_name = "?CanStartNextGeneration@CFamilyTree@@QAE_N_N@Z"
    expected_counts = {
        "FamilyTreeScene.obj": 2,
        "theMainScene.obj": 2,
    }
    patched_callsites = []

    for object_name, expected_count in expected_counts.items():
        path = PATCHED / object_name
        obj = CoffObject(path)
        native_symbol = obj.symbol(native_name).index
        matches = []
        for section in obj.sections:
            for index in range(section.nreloc):
                entry = section.reloc_ptr + index * 10
                vaddr, symbol_index, relocation_type = struct.unpack_from(
                    "<IIH", obj.buf, entry
                )
                if (
                    symbol_index == native_symbol
                    and relocation_type == IMAGE_REL_I386_REL32
                ):
                    matches.append((section, vaddr))

        if len(matches) != expected_count:
            raise RuntimeError(
                f"{object_name} expected {expected_count} "
                f"CanStartNextGeneration calls, found {len(matches)}"
            )

        helper_symbol = obj.append_undefined_symbol(
            NEXT_GENERATION_AGE_HELPER_SYMBOL
        )
        for section, vaddr in matches:
            if obj.buf[section.raw_ptr + vaddr - 1] != 0xE8:
                raise RuntimeError(
                    f"{object_name} CanStartNextGeneration relocation "
                    f"at {vaddr:#x} is not a call"
                )
            obj.retarget_relocation(
                section.index,
                vaddr,
                helper_symbol,
                IMAGE_REL_I386_REL32,
            )
            patched_callsites.append({
                "object": object_name,
                "section": section.index,
                "relocation_vaddr": hex(vaddr),
            })
        obj.write(path)

    manifest["NextGenerationOlderAgeGate"] = {
        "status": "dormant ABI-compatible wrapper installed in every executable",
        "offline_patcher_setting": "allow_older_pregnancies",
        "runtime_flag": {
            "symbol": OLDER_PREGNANCY_FLAG_SYMBOL,
            "source_section": OLDER_PREGNANCY_FLAG_SECTION,
            "default": "00",
            "enabled": "01",
        },
        "stock_precedence": (
            "native CFamilyTree::CanStartNextGeneration result is returned first"
        ),
        "age_threshold": {
            "displayed_years": 60,
            "internal_age": NEXT_GENERATION_INTERNAL_AGE_60,
            "controller": "oldest active living non-departed villager",
        },
        "safety_gates": {
            "surviving_child_required": True,
            "stock_make_room_rollover_retained": True,
        },
        "callsites": patched_callsites,
    }


def patch_multiple_marriage_candidates(manifest):
    """Legacy compatibility stub; native Reject/close behavior is retained."""
    # Force Marriage Email no longer arms a scene-scoped reroll mode.  Keep
    # this legacy entry point inert for old callers while the active generator
    # routes only through the normal proposal queue.
    return

    # Historical implementation retained below for source archaeology only.
    dating_path = PATCHED / "DatingScene.obj"
    dating = CoffObject(dating_path)
    handle_name = "?HandleMessage@CDatingScene@@UAE_NHJ@Z"
    generate_name = "?GeneratePeepCandidate@CDatingScene@@AAEXXZ"
    handle = dating.symbol(handle_name)
    section = dating.section(handle.section)
    reject_hook = handle.value + 0x85
    reject_raw = section.raw_ptr + reject_hook
    expected = bytes.fromhex(
        "C7 43 10 FF FF FF FF E8 00 00 00 00 5F 5E 5B "
        "8B 88 B8 5C 02 00"
    )
    if bytes(dating.buf[reject_raw:reject_raw + len(expected)]) != expected:
        raise RuntimeError("Dating Reject candidate-clear route drifted")

    generate = dating.symbol(generate_name)
    flag_symbol = dating.append_undefined_symbol("_vf2_legacy_marriage_reroll")
    # The stock call at +0x8D is CSound::Play.  Preserve its relocation and
    # move it into the stock branch of the gated cave; ordinary proposals must
    # execute these bytes unchanged.
    stock_sound_relocation = None
    for index in range(section.nreloc):
        vaddr, symbol_index, rtype = struct.unpack_from(
            "<IIH", dating.buf, section.reloc_ptr + index * 10
        )
        if vaddr == handle.value + 0x8D:
            stock_sound_relocation = (index, symbol_index, rtype)
            break
    if stock_sound_relocation is None:
        raise RuntimeError("Dating stock Reject sound relocation drifted")

    cave = section.raw_size
    # cmp [proposal-mode],0; JE stock branch; cheat-only reroll branch;
    # stock clear/sound/continuation bytes; both branches rejoin native flow.
    payload = bytearray(
        b"\x80\x3D\0\0\0\0\x01"  # mode == Female
        + b"\x74\x00"              # -> cheat branch
        + b"\x80\x3D\0\0\0\0\x02"  # mode == Male
        + b"\x75\x00"              # other values -> stock branch
        + b"\x8B\xCB"              # cheat: this = CDatingScene (EBX)
        + b"\x90" * 5
        + b"\xE8\0\0\0\0"          # GeneratePeepCandidate
        + b"\x5F\x5E\x5B"
        + b"\xB0\x01"              # handled = true
        + b"\xE9\0\0\0\0"          # cheat -> common epilogue
        + expected                  # exact stock clear/sound/tail bytes
        + b"\xE9\0\0\0\0"          # stock -> post-hook continuation
    )
    if len(payload) != 66:
        raise AssertionError("Marriage Reject mode-gated cave size drifted")
    struct.pack_into("<b", payload, 8, 0x09)  # cave+18 - (cave+9)
    struct.pack_into("<b", payload, 17, 0x16)  # cave+40 - (cave+18)
    struct.pack_into(
        "<i", payload, 36,
        (handle.value + 0xAC) - (cave + 40),
    )
    struct.pack_into(
        "<i", payload, 62,
        (handle.value + 0x9A) - (cave + 66),
    )
    dating.insert_section_bytes(section.index, cave, bytes(payload))
    dating.append_relocation(
        section.index, cave + 2, flag_symbol, IMAGE_REL_I386_DIR32
    )
    dating.append_relocation(
        section.index, cave + 11, flag_symbol, IMAGE_REL_I386_DIR32
    )
    dating.append_relocation(
        section.index, cave + 26, generate.index, IMAGE_REL_I386_REL32
    )
    # Move, rather than duplicate, the original stock sound relocation.
    section = dating.section(handle.section)
    for index in range(section.nreloc):
        record = section.reloc_ptr + index * 10
        vaddr = struct.unpack_from("<I", dating.buf, record)[0]
        if vaddr == handle.value + 0x8D:
            # The moved stock sound CALL is at cave+47; its REL32 operand is
            # the following four bytes at cave+48.
            struct.pack_into("<I", dating.buf, record, cave + 48)
            break
    else:
        raise RuntimeError("Dating stock Reject relocation move failed")
    dating._parse()
    dating.buf[reject_raw:reject_raw + len(expected)] = (
        b"\xE9" + struct.pack("<i", cave - (reject_hook + 5))
        + b"\x90" * (len(expected) - 5)
    )
    dating.write(dating_path)

    manifest["MultipleMarriageCandidates"] = {
        "status": "patched",
        "scope": "cheat upgrades only",
        "trigger": "Reject button in the active marriage-proposal scene",
        "candidate_lifecycle": (
            "mode 0 executes the exact stock candidate-clear/sound path; modes "
            "1/2 deactivate the rejected temporary villager before spawning and "
            "displaying exactly one replacement"
        ),
        "email_state": (
            "the scene remains open and the stock proposal timestamp fields "
            "at theGameState+0x25CB8/+0x25CBC are not cleared or rewritten"
        ),
        "mode_gate": (
            "mode 0 and invalid values preserve the original native Reject route; "
            "only the exact active forced-email mode (1) rerolls in place and "
            "keeps the proposal scene active"
        ),
        "same_sex_interaction": (
            "each replacement passes through the optional .vf2same candidate-"
            "gender helper, so flag-off remains opposite-sex and flag-on matches "
            "the current adult"
        ),
        "accept_path": "byte-identical stock HandleMessage parameter-1 route",
    }


def patch_marriage_candidate_reroll(manifest):
    """Gate native Reject on the dedicated, default-off reroll byte.

    CRITICAL: the byte span at HandleMessage+0x85 is NOT exclusive to
    Reject's own code. It is "mov dword ptr [ebx+0x10], -1" (reset the
    scene's candidate index) immediately followed, at +0x8C, by a shared
    tail -- "call theGameState::Get(); pop edi; pop esi; pop ebx; mov
    ecx,[eax+0x25CB8]; mov [eax+0x25CBC],ecx; mov [eax+0x25CB8],0; mov
    al,1; ..." -- that flushes a pending proposal-timestamp field and
    returns `true`. Reject reaches +0x8C by falling straight through from
    +0x85. But the Accept ("Marry") case handler, elsewhere in this same
    function, performs its own identical scene-index reset and then
    JUMPS DIRECTLY to +0x8C to reuse that exact tail (confirmed via a
    real crash dump + live IDA trace, and independently via a pristine,
    unpatched disassembly showing that jump).
    An earlier version of this hook overwrote the entire +0x85..+0x9A
    span (through the shared tail) with a trampoline jump and NOP
    padding. That destroyed the "call theGameState::Get()" Accept jumps
    into, so clicking Marry landed on NOPs instead, fell through with
    EAX never reassigned (observed live as EAX=1, a leftover boolean from
    unrelated earlier code), and crashed writing through it as a pointer.
    Fixed by hooking ONLY the 7-byte scene-index-reset instruction that
    is genuinely Reject-private, and having both the active and inactive
    cave paths rejoin execution at the untouched +0x8C shared tail --
    exactly where Accept's own jump also lands -- instead of duplicating
    or relocating any of that shared code.
    """
    dating_path = PATCHED / "DatingScene.obj"
    dating = CoffObject(dating_path)
    handle_name = "?HandleMessage@CDatingScene@@UAE_NHJ@Z"
    generate_name = "?GeneratePeepCandidate@CDatingScene@@AAEXXZ"
    handle = dating.symbol(handle_name)
    section = dating.section(handle.section)
    reject_hook = handle.value + 0x85
    reject_raw = section.raw_ptr + reject_hook
    shared_tail_offset = handle.value + 0x8C
    # +0xAC is the function epilogue (mov ecx,[ebp-4]; security cookie check;
    # mov esp,ebp; pop ebp; retn 8) -- i.e. everything the shared tail does
    # AFTER its scene-close writes at +0x9A..+0xA9. Jumping here returns
    # true without tearing the proposal scene down.
    reroll_return_offset = handle.value + 0xAC
    expected_reset = bytes.fromhex("C7 43 10 FF FF FF FF")
    if bytes(dating.buf[reject_raw:reject_raw + len(expected_reset)]) != expected_reset:
        raise RuntimeError("Dating Reject stock scene-index-reset drifted")

    generate = dating.symbol(generate_name)
    get_villager_name = "?GetVillager@CVillagerManager@@QAEAAVCVillager@@H@Z"
    villager_manager_name = "?VillagerManager@@3VCVillagerManager@@A"
    get_villager = dating.symbol(get_villager_name)
    villager_manager = dating.symbol(villager_manager_name)
    # Reads the flag through InventoryManager + itemId + 0x2A3 (the same
    # proven persisted-byte convention as mobile renovations/Bathroom 2)
    # instead of the old free-standing .vf2rero custom section, so the
    # toggle survives a process relaunch/save reload instead of silently
    # resetting to 0.
    inventory_manager_symbol = dating.append_undefined_symbol(INVENTORY_MANAGER_SYMBOL)
    reroll_flag_addend = MARRIAGE_CANDIDATE_REROLL_ITEM_ID + CHEAT_TOGGLE_PERSISTED_BYTE_OFFSET

    cave = section.raw_size
    payload = bytearray(
        b"\x80\x3D\0\0\0\0\x00"  # compare InventoryManager+0x152+0x2A3 byte with zero
        + b"\x74\x00"              # inactive -> stock reset branch
        # GeneratePeepCandidate's authenticated native prologue deactivates
        # the old temporary villager through this exact manager lookup and
        # CVillager+0x1BB84 write.  Perform it before resetting the scene
        # index so the generator cannot lose the old candidate identity.
        + b"\x8B\x43\x10"          # active: old candidate index
        + b"\x83\xF8\xFF"          # no old candidate?
        + b"\x74\x00"              # -> reset scene index (skip deactivation)
        + b"\x50"                  # push old candidate index
        + b"\xB9\0\0\0\0"       # this = VillagerManager
        + b"\xE8\0\0\0\0"       # GetVillager(old index)
        + b"\x85\xC0"              # invalid old pointer?
        + b"\x74\x00"              # -> reset scene index (fail closed, same as inactive)
        + b"\xC6\x80\x84\xBB\x01\x00\x00"  # old active byte = 0
        # reset: (both the active and no-old-candidate/fail-closed paths land here)
        + b"\xC7\x43\x10\xFF\xFF\xFF\xFF"  # scene index = -1 (same as stock)
        + b"\x8B\xCB"              # this = CDatingScene (EBX)
        + b"\xE8\0\0\0\0"          # GeneratePeepCandidate
        # The active path must NOT rejoin the +0x8C shared tail: that tail
        # ends with "mov dword ptr [eax+0x25CB8], 0", which sets the current
        # scene back to 0 and closes the whole proposal. Rejoining it threw
        # the freshly-generated candidate away one instruction after making
        # it -- observed live as "the proposal closed" and, because the
        # rejection reaction at +0x6C has already run by then, as ordinary
        # stock rejection behavior. Instead reproduce the tail's register
        # restores, return true, and jump straight to the +0xAC epilogue,
        # skipping only the scene-close writes so the proposal stays open
        # showing the new candidate.
        + b"\x5F"                  # pop edi
        + b"\x5E"                  # pop esi
        + b"\x5B"                  # pop ebx
        + b"\xB0\x01"              # mov al, 1 (return true: message handled)
        + b"\xE9\0\0\0\0"          # active -> HandleMessage +0xAC epilogue
        # inactive: exact stock scene-index reset, then the stock shared tail
        + b"\xC7\x43\x10\xFF\xFF\xFF\xFF"
        + b"\xE9\0\0\0\0"          # stock -> HandleMessage +0x8C shared tail
    )
    if len(payload) != 75:
        raise AssertionError("Marriage Reject reroll cave size drifted")
    struct.pack_into("<b", payload, 8, 63 - 9)   # je inactive (offset 63)
    struct.pack_into("<b", payload, 16, 39 - 17)  # je reset (offset 39, skip deactivation)
    struct.pack_into("<b", payload, 31, 39 - 32)  # je reset (offset 39, fail closed)
    struct.pack_into("<i", payload, 59, reroll_return_offset - (cave + 63))
    struct.pack_into("<i", payload, 71, shared_tail_offset - (cave + 75))
    struct.pack_into("<I", payload, 2, reroll_flag_addend)

    dating.insert_section_bytes(section.index, cave, bytes(payload))
    dating.append_relocation(
        section.index, cave + 2, inventory_manager_symbol, IMAGE_REL_I386_DIR32
    )
    dating.append_relocation(
        section.index, cave + 19, villager_manager.index, IMAGE_REL_I386_DIR32
    )
    dating.append_relocation(
        section.index, cave + 24, get_villager.index, IMAGE_REL_I386_REL32
    )
    dating.append_relocation(
        section.index, cave + 49, generate.index, IMAGE_REL_I386_REL32
    )
    dating._parse()
    section = dating.section(handle.section)
    reject_raw = section.raw_ptr + reject_hook
    dating.buf[reject_raw:reject_raw + len(expected_reset)] = (
        b"\xE9" + struct.pack("<i", cave - (reject_hook + 5))
        + b"\x90" * (len(expected_reset) - 5)
    )
    dating.write(dating_path)

    manifest["MarriageCandidateReroll"] = {
        "status": "dormant native hook installed",
        "cheat_upgrade": {
            "item_id": hex(MARRIAGE_CANDIDATE_REROLL_ITEM_ID),
            "catalog_price": MARRIAGE_CANDIDATE_REROLL_CATALOG_PRICE,
            "icon_file": "cheat_marriage_email.png",
            "active_state": "persisted InventoryManager+0x152+0x2A3 byte; store icon stays cheat_marriage_email.png",
            "inactive_state": "free Cheat Upgrade row; explicit catalog price 0",
            "buy_again": "clears the persisted byte",
        },
        "runtime_flag": {
            "storage": "InventoryManager + 0x152 + 0x2A3 (same persisted-byte convention as mobile renovations/Bathroom 2)",
            "size": 1,
            "default": "00",
            "enabled": "01",
            "persistence": "part of the native save payload (CInventoryManager); survives process relaunch/save reload, unlike the prior free-standing .vf2rero custom section",
        },
        "reject": {
            "function": handle_name,
            "hook_offset": "+0x85",
            "hook_span": "7 bytes (scene-index reset only; the +0x8C shared "
                "tail Accept also jumps into is never touched)",
            "trampoline": hex(cave),
            "active_lifecycle": (
                "resolve the old scene candidate through native "
                "CVillagerManager::GetVillager, clear CVillager+0x1BB84, set "
                "CDatingScene+0x10 to -1, then call GeneratePeepCandidate"
            ),
            "active_call": generate_name,
            "rejoin": "both active and inactive paths jump to HandleMessage "
                "+0x8C, the untouched native shared tail also used directly "
                "by Accept",
        },
        "accept": "byte-identical stock code path; no longer touched or "
            "duplicated by this hook",
    }


def patch_vf3_style_child_adoption_chooser(manifest):
    """Choose a random newborn or a random age-2-through-8 adoptee."""
    path = PATCHED / "ScrollingStoreScene.obj"
    obj = CoffObject(path)
    function_name = "?HandleUpgrade@CScrollingStoreScene@@AAEXXZ"
    function = obj.symbol(function_name)
    section = obj.section(function.section)
    hook = function.value + 0x57A
    raw = section.raw_ptr + hook
    expected = bytes.fromhex("6A 3C 6A FF 6A")
    if bytes(obj.buf[raw:raw + len(expected)]) != expected:
        raise RuntimeError("Adoption Services spawn route drifted")

    helper = obj.append_undefined_symbol(ADOPTION_CHOOSER_HELPER_SYMBOL)
    section = obj.section(function.section)
    cave = section.raw_size
    failure_target = function.value + 0x83B
    success_target = function.value + 0x5BC
    payload = bytearray(
        b"\x53"                  # push ebx: CScrollingStoreScene/ldwScene
        b"\xE8\0\0\0\0"         # call chooser and complete adoption
        b"\x83\xC4\x04"          # caller cleanup
        b"\x84\xC0"              # test success
        b"\x0F\x84\0\0\0\0"     # failure: skip completion message
        b"\xE9\0\0\0\0"         # success: stock completion message
    )
    struct.pack_into("<i", payload, 13, failure_target - (cave + 17))
    struct.pack_into("<i", payload, 18, success_target - (cave + 22))
    obj.insert_section_bytes(section.index, cave, bytes(payload))
    obj.append_relocation(
        section.index,
        cave + 2,
        helper,
        IMAGE_REL_I386_REL32,
    )

    section = obj.section(function.section)
    raw = section.raw_ptr + hook
    obj.buf[raw:raw + 5] = (
        b"\xE9" + struct.pack("<i", cave - (hook + 5))
    )
    obj.write(path)

    manifest["VF3StyleChildAdoptionChooser"] = {
        "status": "patched",
        "scope": "core Adoption Services purchase",
        "choices": {
            "baby": "internal age 0",
            "older_child": (
                "uniform displayed age 2-8; internal age "
                "(GetRandom(7)+2)*20"
            ),
        },
        "gender": "native GetRandom(2), female or male",
        "traits": (
            "native three-argument SpawnSpecificPeep initializer retained; "
            "names, appearance, likes, dislikes, career and personality state "
            "continue through CVillager::Init"
        ),
        "singleton": "exactly one SpawnSpecificPeep call per purchase",
        "capacity": (
            "requires EmptyOffspringSlots()>0; failed spawn or AddOffspring "
            "returns without dereferencing an invalid villager index"
        ),
        "family_tree": "native CFamilyTree::AddOffspring retained",
        "achievements": "native adoption achievements 0x0C and 0x0D retained",
    }


def patch_ldwscene_setactive_null_guard(manifest):
    """Guard ldwScene::SetActive against an unbound (null) active-flag pointer.

    Confirmed root cause of a real crash (Windows crash dump + independent
    disassembly, not a guess): ldwScene::SetActive(bool) unconditionally
    writes its bool argument through this->field_4 -- an externally-bound
    flag pointer -- before doing anything else. That field_4 binding is
    never set up for at least one scene slot reachable through the native
    scene-activation dispatch used by theGame's scene-management helpers
    (a 16-case switch keyed by a queued scene id; case 2 is the affected
    slot). Calling SetActive on that slot dereferences a null field_4 and
    crashes with an access violation. Observed in practice the moment a
    family reaches its native six-child capacity, which is exactly when
    that scene id gets queued.

    This patches the one shared setter all 59+ call sites funnel through,
    rather than each call site individually: for every scene whose
    binding *is* set up (effectively all of them except this one slot),
    behavior is byte-identical to stock. Only the crashing null case now
    returns instead of dereferencing a null pointer.
    """
    obj = CoffObject(PATCHED / "ldwScene.obj")
    sym = obj.symbol("?SetActive@ldwScene@@QAEX_N@Z")
    sec = obj.section(sym.section)
    hook_offset = sym.value + 0xA
    raw = sec.raw_ptr + hook_offset
    expected = bytes.fromhex("8B4604 8818".replace(" ", ""))
    if bytes(obj.buf[raw:raw + len(expected)]) != expected:
        raise RuntimeError("ldwScene::SetActive field_4 write site drifted")
    epilogue_offset = sym.value + 0x4F
    epilogue_raw = sec.raw_ptr + epilogue_offset
    expected_epilogue = bytes.fromhex("5E5B5DC20400")
    if bytes(obj.buf[epilogue_raw:epilogue_raw + len(expected_epilogue)]) != expected_epilogue:
        raise RuntimeError("ldwScene::SetActive epilogue drifted")

    cave = sec.raw_size
    resume_offset = sym.value + 0xF
    payload = bytearray(
        b"\x8B\x46\x04"            # mov eax, [esi+4]     (identical to replaced code)
        b"\x85\xC0"                # test eax, eax        (new: is the binding set up?)
        b"\x74\x07"                # jz early_return       (new: skip the write if not)
        b"\x88\x18"                # mov [eax], bl        (identical to replaced code)
        b"\xE9\0\0\0\0"            # jmp resume            (continue the original function body)
        b"\x5E\x5B\x5D\xC2\x04\x00"  # early_return: pop esi; pop ebx; pop ebp; ret 4
                                      # (exact copy of this function's own epilogue, so the
                                      # early-return path unwinds the stack identically)
    )
    if len(payload) != 20:
        raise AssertionError("ldwScene::SetActive null-guard trampoline size drifted")
    struct.pack_into("<i", payload, 10, (resume_offset) - (cave + 14))
    obj.insert_section_bytes(sym.section, cave, bytes(payload))

    sym = obj.symbol("?SetActive@ldwScene@@QAEX_N@Z")
    sec = obj.section(sym.section)
    hook_offset = sym.value + 0xA
    raw = sec.raw_ptr + hook_offset
    obj.buf[raw:raw + 5] = b"\xE9" + struct.pack("<i", cave - (hook_offset + 5))
    obj.write(PATCHED / "ldwScene.obj")

    manifest["ldwSceneSetActiveNullGuard"] = {
        "status": "installed",
        "function": "?SetActive@ldwScene@@QAEX_N@Z",
        "hook_offset": hex(0xA),
        "trampoline": hex(cave),
        "trampoline_size": len(payload),
        "reason": "field_4 (bound active-flag pointer) is unset for at least one native scene slot reachable once a family reaches six children; every other caller is unaffected",
        "stock_off_state": "byte-identical to stock for every properly-bound scene",
    }


def patch_same_sex_marriage(manifest):
    """Set the marriage candidate's gender to match the current adult's.

    Deliberately narrow: this patches exactly one native decision point --
    the candidate-gender computation inside GeneratePeepCandidate -- and
    touches no other native handler.

    Disassembly of clean GeneratePeepCandidate confirms +0x56 already reads
    the current single adult's gender (CVillager+0x6A58) into EDI, and at
    +0x7D that same EDI is consumed by exactly two native instructions,
    `cmp edi,1` then `setne al` (6 bytes total): stock always computes the
    *opposite* of the adult's gender (al=1, i.e. spawn a female candidate,
    precisely when the adult is not female, and vice versa) as the
    argument later passed into the native candidate-spawn call. Nothing
    else reads or writes EDI between +0x56 and +0x7D (confirmed by
    disassembly, and independently guaranteed by EDI being callee-saved
    across the two native calls in between), so it still holds the exact
    adult-gender value the native scan produced.

    This hook replaces only that 6-byte cmp+setne span with a flag-gated
    choice: when disabled, an exact byte-for-byte replica of the native
    "opposite" computation; when enabled, `mov eax,edi; and eax,1` --
    a direct copy of the already-scanned adult gender (no new/duplicate
    scan is added; the native read is reused as-is). Both paths rejoin
    immediately after the replaced span, before the native spawn call
    that consumes the result, so spawning, naming, appearance, and
    proposal-control refresh all remain completely stock.

    A previous version of this patch instead flipped the candidate's OWN
    gender field after spawning it, and did so at a drifted field offset
    ([edi+0x58] instead of the confirmed [edi+0x6A58]) -- corrupting an
    unrelated candidate field whenever the flag was active. That version
    also separately hooked HandleDropOnVillager (to route same-sex spouse
    pairs into the native private-time sequence) and TryToMakeBaby (to
    force 0% same-sex pregnancy). Neither is needed for gender-matching
    and neither is touched here: this patch changes nothing about
    romantic actions, pregnancy, or any other native handler.
    """
    dating_path = PATCHED / "DatingScene.obj"
    dating = CoffObject(dating_path)
    generate_name = "?GeneratePeepCandidate@CDatingScene@@AAEXXZ"
    generate = dating.symbol(generate_name)
    generate_sec = dating.section(generate.section)
    gender_hook = generate.value + 0x7D
    gender_raw = generate_sec.raw_ptr + gender_hook
    expected_gender_decision = bytes.fromhex("83FF010F95C0")
    if bytes(dating.buf[gender_raw:gender_raw + len(expected_gender_decision)]) != expected_gender_decision:
        raise RuntimeError("Dating candidate gender-decision anchor drifted")

    # Reads the flag through InventoryManager + itemId + 0x2A3 (the same
    # proven persisted-byte convention as mobile renovations/Bathroom 2)
    # instead of the old free-standing .vf2same custom section, so the
    # toggle survives a process relaunch/save reload instead of silently
    # resetting to 0.
    inventory_manager_symbol = dating.append_undefined_symbol(INVENTORY_MANAGER_SYMBOL)
    same_sex_flag_addend = SAME_SEX_MARRIAGE_ITEM_ID + CHEAT_TOGGLE_PERSISTED_BYTE_OFFSET
    gender_cave = generate_sec.raw_size
    rejoin = gender_hook + len(expected_gender_decision)
    gender_trampoline = bytearray(
        b"\x80\x3D\0\0\0\0\x00"  # cmp byte ptr [InventoryManager+0x14C+0x2A3],0
        b"\x75\x00"                # nonzero (enabled) -> same-gender path
        # disabled: exact replica of the overwritten native computation
        b"\x83\xFF\x01"            # cmp edi,1
        b"\x0F\x95\xC0"            # setne al   (al = adult is not female)
        b"\xE9\0\0\0\0"          # -> rejoin
        # enabled: candidate gender = adult gender (edi, already scanned by
        # the native code above; reused, not rescanned)
        b"\x8B\xC7"                # mov eax,edi
        b"\x83\xE0\x01"            # and eax,1
        b"\xE9\0\0\0\0"          # -> rejoin
    )
    if len(gender_trampoline) != 30:
        raise AssertionError("Same-sex candidate gender trampoline size drifted")
    struct.pack_into("<b", gender_trampoline, 8, 20 - 9)  # jne enabled (offset 20)
    struct.pack_into("<i", gender_trampoline, 16, rejoin - (gender_cave + 20))
    struct.pack_into("<i", gender_trampoline, 26, rejoin - (gender_cave + 30))
    struct.pack_into("<I", gender_trampoline, 2, same_sex_flag_addend)
    dating.insert_section_bytes(generate_sec.index, gender_cave, bytes(gender_trampoline))
    dating.append_relocation(
        generate_sec.index, gender_cave + 2, inventory_manager_symbol, IMAGE_REL_I386_DIR32
    )
    generate = dating.symbol(generate_name)
    generate_sec = dating.section(generate.section)
    gender_raw = generate_sec.raw_ptr + gender_hook
    dating.buf[gender_raw:gender_raw + len(expected_gender_decision)] = (
        b"\xE9" + struct.pack("<i", gender_cave - (gender_hook + 5)) + b"\x90"
    )
    dating.write(dating_path)

    manifest["SameSexMarriage"] = {
        "status": "candidate gender-decision hook installed; no other native handler touched",
        "offline_patcher_setting": "same_sex_marriage",
        "category": "optional",
        "default": False,
        "runtime_hooks_installed": True,
        "cheat_upgrade": {
            "item_id": hex(SAME_SEX_MARRIAGE_ITEM_ID),
            "inactive_price": SAME_SEX_MARRIAGE_CATALOG_PRICE,
            # No price_source_item_id: the row is free, so it no longer derives
            # its price from Health Plan and pointing at 0x119 would invite a
            # consumer to read a relationship that no longer exists.
            "price_source": "free Cheat Upgrade row; the Health Plan price it once matched is unchanged",
            "active_price": 0,
            "active_state": "persisted InventoryManager+0x14C+0x2A3 byte; store icon stays cheat_marriage_email.png",
            "inactive_state": "free Cheat Upgrade row; explicit catalog price 0",
            "inactive_icon": "cheat_marriage_email.png",
            "active_icon": "cheat_marriage_email.png",
        },
        "runtime_flag": {
            "storage": "InventoryManager + 0x14C + 0x2A3 (same persisted-byte convention as mobile renovations/Bathroom 2)",
            "size": 1,
            "default": "00",
            "enabled": "01",
            "persistence": "part of the native save payload (CInventoryManager); survives process relaunch/save reload, unlike the prior free-standing .vf2same custom section",
        },
        "candidate_gender": {
            "status": "native gender-decision computation replaced, gated by the flag",
            "scan": "reuses the native adult-gender read already in EDI at this point (CVillager+0x6A58); no separate scan is added",
            "disabled": "stock computation: setne al (candidate gender = opposite of the current adult)",
            "enabled": "candidate gender = current adult gender (direct copy of the scanned value, masked to bit 0)",
            "hook_offset": "+0x7D in clean DatingScene.obj (6-byte cmp+setne span only)",
            "rejoin": "immediately after the replaced span, before the native spawn call that consumes this value; every later step (spawn, naming, appearance, proposal controls) is stock",
        },
        "not_touched": (
            "HandleDropOnVillager (romantic/private-time routing), TryToMakeBaby "
            "(pregnancy), and every other native handler are untouched by this "
            "patch. A prior version hooked both in addition to gender; that "
            "version's post-spawn gender write also used a drifted field offset "
            "([edi+0x58] instead of [edi+0x6A58]) that corrupted an unrelated "
            "candidate field whenever this flag was active. Both are removed."
        ),
        "stock_off_state": "byte-identical native candidate-gender computation when the flag is zero",
    }
    return


def patch_villager_same_sex_embrace(manifest):
    """Let a married same-sex couple past StartEmbrace's gender refusal.

    Dropping one villager on another for romance runs
    CVillager::StartEmbrace, NOT theMainScene::HandleDropOnVillager's
    romantic block -- which is why tracing that block never explained the
    reported refusal. StartEmbrace tests the two gender fields early and,
    when they match, loads refusal message 1850 ("These villagers are both
    the same gender.") and jumps to its shared say-and-return tail, long
    before reaching the couch/bed search that ends in behavior 358, the
    private-time sequence.

    Confirmed layout in clean Villager.obj:

        +0xC5  8B 83 58 6A 00 00   mov eax, [ebx+6A58h]   ; gender
        +0xCB  3B 87 58 6A 00 00   cmp eax, [edi+6A58h]
        +0xD1  75 0A               jnz +0xDD              ; differ -> proceed
        +0xD3  BE 3A 07 00 00      mov esi, 1850
        +0xD8  E9 CD 01 00 00      jmp +0x2AA             ; say refusal
        +0xDD  8D 8B F4 6A 00 00   lea ecx, [ebx+6AF4h]   ; continue

    The trampoline replaces the 2-byte jnz, which means it necessarily also
    consumes three bytes of the following "mov esi, 1850" -- exactly the
    over-write that caused arbitrary memory corruption in the romantic-drop
    trampoline. The cave therefore reproduces that instruction and the jump
    after it rather than re-entering the overwritten region.

    Only the gender test is bypassed, and only for the resolved married
    same-sex pair with the toggle active. Every other refusal in
    StartEmbrace (age, pregnancy state, the random-chance checks) still
    applies, and an opposite-sex drop is byte-identical to stock because the
    helper returns false and the reproduced native jnz runs unchanged.
    """
    path = PATCHED / "Villager.obj"
    obj = CoffObject(path)
    function_name = "?StartEmbrace@CVillager@@IAEXXZ"
    function = obj.symbol(function_name)
    section = obj.section(function.section)
    hook = function.value + 0xD1
    raw = section.raw_ptr + hook
    expected = bytes.fromhex("750ABE3A070000")
    if bytes(obj.buf[raw:raw + len(expected)]) != expected:
        raise RuntimeError(
            "CVillager::StartEmbrace same-gender refusal branch drifted"
        )
    continue_target = function.value + 0xDD
    # +0xD8 is "jmp rel32" to the shared say-and-return tail.
    refusal_target = function.value + 0xD8 + 5 + struct.unpack_from(
        "<i", bytes(obj.buf[raw + 7 + 1:raw + 7 + 5]), 0
    )[0]

    helper = obj.append_undefined_symbol(SAME_SEX_EMBRACE_HELPER_SYMBOL)
    cave = section.raw_size
    payload = bytearray(
        b"\x9C"                  # pushf: preserve the native gender compare
        b"\x53"                  # push ebx  (second argument)
        b"\x57"                  # push edi  (first argument)
        b"\xE8\0\0\0\0"        # call VF2AllowSameSexEmbrace(edi, ebx)
        b"\x83\xC4\x08"          # cdecl cleanup
        b"\x84\xC0"              # test al, al
        b"\x74\x06"              # not allowed -> reproduce stock behavior
        b"\x9D"                  # restore native flags
        b"\xE9\0\0\0\0"        # allowed -> +0xDD, skipping the refusal
        b"\x9D"                  # not allowed: restore native flags
        b"\x0F\x85\0\0\0\0"    # the native jnz, widened to rel32
        b"\xBE\x3A\x07\x00\x00"  # mov esi, 1850   (reproduced)
        b"\xE9\0\0\0\0"        # jmp shared say-and-return (reproduced)
    )
    if len(payload) != 38:
        raise AssertionError("Same-sex embrace cave size drifted")
    struct.pack_into("<i", payload, 17, continue_target - (cave + 21))
    struct.pack_into("<i", payload, 24, continue_target - (cave + 28))
    struct.pack_into("<i", payload, 34, refusal_target - (cave + 38))

    obj.insert_section_bytes(section.index, cave, bytes(payload))
    obj.append_relocation(section.index, cave + 4, helper, IMAGE_REL_I386_REL32)
    obj._parse()
    section = obj.section(function.section)
    raw = section.raw_ptr + hook
    obj.buf[raw:raw + 5] = b"\xE9" + struct.pack("<i", cave - (hook + 5))

    # StartEmbrace's random-chance refusals at +0x171 and +0x19D are left
    # completely stock. An earlier version jumped past them so a same-sex
    # couple never refused, which meant a refusal it had genuinely rolled
    # carried on into the rest of the sequence instead of ending the
    # attempt. Base-game refusal behaviour, wording included, is correct.
    refusal_sites = []

    # StartEmbrace's success path gives both partners behavior 358
    # ("Trying to Make A Baby") and that is deliberately LEFT ALONE. An
    # earlier version swapped it for the 357/356 pair to get a different
    # label, which routed the couple into a side sequence and caused a
    # string of problems. The label is a presentation concern, so it is
    # handled as a behaviour variation on 358 itself -- see
    # patch_private_romantic_time_variation -- and the couple keeps the
    # ordinary, well-tested baby-making path.
    behavior_sites = []

    obj.write(path)

    manifest["SameSexEmbrace"] = {
        "status": "installed",
        "function": function_name,
        "hook_offset": hex(0xD1),
        "stock_bytes": expected.hex(" "),
        "helper": SAME_SEX_EMBRACE_HELPER_SYMBOL,
        "trampoline": hex(cave),
        "trampoline_size": len(payload),
        "continue_target": hex(0xDD),
        "refusal_message": 1850,
        "reproduced_instructions": "mov esi, 1850; jmp shared say-and-return",
        "native_registers": {"dropped": "EDI", "target": "EBX"},
        "scope": (
            "only the equal-gender test, and only for the resolved married "
            "same-sex pair while the toggle is active; every later "
            "StartEmbrace eligibility check still applies and an "
            "opposite-sex drop is byte-identical to stock"
        ),
        "reason": (
            "the romantic drop runs CVillager::StartEmbrace, not "
            "theMainScene::HandleDropOnVillager's romantic block, and bailed "
            "on this test long before reaching behavior 358"
        ),
        "behavior_swap": {
            "status": "removed; behaviour 358 is kept for every couple",
            "stock": 358,
            "same_sex": 358,
            "note": (
                "an earlier version replaced each 'push 166h' with a thunk "
                "that pushed 357/356 instead, to obtain a different label. "
                "That routed the couple into a side sequence and caused a "
                "run of failures. The label is a presentation concern and is "
                "now a behaviour variation on 358 itself -- see "
                "EmbraceRoleSplit and the CBehavior constructor retarget in "
                "patch_behavior_label_variants -- so the couple keeps the "
                "ordinary baby-making behaviour"
            ),
            "sites": behavior_sites,
        },
        "random_refusals": {
            "status": "stock; not patched",
            "reason": (
                "every refusal in StartEmbrace, random or not, is left as "
                "base-game code. An earlier version jumped past the two "
                "random rolls so a same-sex couple never refused, which "
                "meant a refusal it had genuinely rolled carried on into "
                "the rest of the sequence instead of ending the attempt"
            ),
            "sites": refusal_sites,
        },
    }


def patch_force_pregnancy_skips_refusals(manifest):
    """While Force Successful Pregnancy is armed, don't let a mood roll refuse.

    The upgrade is a one-shot: the player arms it expecting the next attempt
    to work. StartEmbrace can still refuse for reasons that have nothing to do
    with whether a pregnancy would succeed, so the armed shot gets spent
    re-dropping the couple until the dice cooperate.

    Exactly two refusals are skipped while armed -- the two random rolls,
    and nothing else. Both share one shape: a 5-byte "mov esi, <StringId>"
    followed by a jump to the shared say-and-return tail, each reached from
    exactly one gate, so each has a single unambiguous resume point:

        +0x171  1846 "not in the mood"  gate +0x16F je  -> resume +0x17B
        +0x19D  1851 "can't agree"      gate +0x19B jge -> resume +0x1A7

    These two are pure dice. The gate above each one calls GetRandom and
    refuses on an unlucky result, so skipping it takes the very branch a
    luckier roll would have taken -- no state is skipped, because the native
    code had not yet done anything different.

    Each mov becomes a jump to a cave that asks the helper and either
    continues at that gate's own success target or reproduces the mov and the
    jump verbatim. Nothing structural is bypassed: the couple takes the exact
    branch a luckier roll would have taken, so there is no state the native
    code has not already set up.

    Every other refusal stays byte-for-byte base-game:

      1857 too hungry -- a real need, not a mood.
      1853 under-age  -- would put a child into the routine.
      1849 pregnant/busy -- risks a second impregnation.
      1847 illness    -- also reached from two different gates converging on
                         one target, so a cave there would have no single
                         resume point to return to.
      1850 same gender -- the same-sex toggle's business, not this one's.
      "they need a couch or a bed" -- the sequence genuinely needs furniture
                         to link to.

    When the upgrade is not armed every one of these paths is byte-for-byte
    stock, because the cave falls through to the reproduced instructions.
    """
    path = PATCHED / "Villager.obj"
    obj = CoffObject(path)
    function_name = "?StartEmbrace@CVillager@@IAEXXZ"
    function = obj.symbol(function_name)

    sites = []
    for refusal_offset, message_id, resume_offset in (
        (0x171, 1846, 0x17B),
        (0x19D, 1851, 0x1A7),
    ):
        section = obj.section(function.section)
        site = section.raw_ptr + function.value + refusal_offset
        stock_mov = b"\xBE" + struct.pack("<I", message_id)
        if bytes(obj.buf[site:site + 5]) != stock_mov:
            raise RuntimeError(
                f"StartEmbrace refusal {message_id} drifted at +{refusal_offset:#x}"
            )
        if obj.buf[site + 5] != 0xE9:
            raise RuntimeError(
                f"StartEmbrace refusal {message_id} is not followed by a jmp "
                f"at +{refusal_offset:#x}"
            )
        jmp_rel = struct.unpack_from("<i", bytes(obj.buf[site + 6:site + 10]), 0)[0]
        say_target = function.value + refusal_offset + 10 + jmp_rel

        armed = obj.append_undefined_symbol(FORCE_PREGNANCY_ACTIVE_SYMBOL)
        cave = section.raw_size
        payload = bytearray(
            b"\x51"                # push ecx ) caller-saved across the cdecl
            b"\x52"                # push edx ) helper call
            b"\xE8\0\0\0\0"        # call VF2ForceSuccessfulPregnancyArmed
            b"\x5A"                # pop edx
            b"\x59"                # pop ecx
            b"\x84\xC0"            # test al, al
            b"\x74\x05"            # not armed -> stock refusal
            b"\xE9\0\0\0\0"        # armed -> this gate's own success target
            + stock_mov            # mov esi, <StringId>   (reproduced)
            + b"\xE9\0\0\0\0"      # jmp say-and-return    (reproduced)
        )
        if len(payload) != 28:
            raise AssertionError("Force-pregnancy refusal cave size drifted")
        struct.pack_into(
            "<i", payload, 14,
            (function.value + resume_offset) - (cave + 18),
        )
        struct.pack_into("<i", payload, 24, say_target - (cave + 28))

        obj.insert_section_bytes(section.index, cave, bytes(payload))
        obj.append_relocation(section.index, cave + 3, armed, IMAGE_REL_I386_REL32)
        obj._parse()
        section = obj.section(function.section)
        site = section.raw_ptr + function.value + refusal_offset
        obj.buf[site:site + 5] = (
            b"\xE9"
            + struct.pack("<i", cave - (function.value + refusal_offset + 5))
        )
        sites.append({
            "offset": hex(refusal_offset),
            "message": message_id,
            "resume": hex(resume_offset),
            "trampoline": hex(cave),
        })

    obj.write(path)
    manifest["ForcePregnancySkipsRefusals"] = {
        "status": "installed",
        "function": function_name,
        "armed_by": "persistent cheat mask bit 0x4 (Force Successful Pregnancy)",
        "sites": sites,
        "skipped": "1846 not in the mood, 1851 can't agree -- the two random rolls only",
        "not_skipped": (
            "everything else is base-game: 1857 too hungry, 1853 under-age, "
            "1849 pregnant/busy, 1847 illness, 1850 same gender, and the "
            "couch/bed furniture check"
        ),
        "when_disarmed": "every path is byte-for-byte stock",
    }


def patch_embrace_role_split(manifest):
    """Give a same-sex pair the two different halves of the 358 sequence.

    CBehavior::GoInHouse picks which half a villager performs -- the spin or
    the roses -- from one test at +0x081:

        +0x081  83 BF 58 6A 00 00 01   cmp dword ptr [edi+6A58h], 1
        +0x088  0F 85 ...              jne -> +0x1FD

    Both partners run the same behaviour and rely on having different
    genders to take opposite branches, so a same-sex couple takes the same
    branch twice and both perform the identical half.

    The 7-byte cmp is replaced with a jump to a cave that asks
    VF2EmbraceRoleIsFemale instead and leaves ZF set the way the native cmp
    would have, so the native jne immediately after is untouched and still
    does the branching. The helper returns the stock gender answer for every
    couple except a same-sex pair, where it hands the halves out by partner
    slot.

    The cave restores the flags AFTER popping the caller-saved registers,
    because pops do not affect flags but the call does -- the cmp is
    therefore the last thing executed before rejoining.
    """
    path = PATCHED / "Behavior.obj"
    obj = CoffObject(path)
    function_name = "?GoInHouse@CBehavior@@CAXAAVCVillager@@@Z"
    function = obj.symbol(function_name)
    section = obj.section(function.section)

    hook = function.value + 0x081
    raw = section.raw_ptr + hook
    expected = bytes.fromhex("83 BF 58 6A 00 00 01")
    if bytes(obj.buf[raw:raw + 7]) != expected:
        raise RuntimeError(
            "CBehavior::GoInHouse gender role test drifted at +0x081: "
            + bytes(obj.buf[raw:raw + 7]).hex(" ")
        )
    if bytes(obj.buf[raw + 7:raw + 9]) != bytes.fromhex("0F85"):
        raise RuntimeError("CBehavior::GoInHouse role branch drifted at +0x088")

    helper = obj.append_undefined_symbol(EMBRACE_ROLE_HELPER_SYMBOL)
    cave = section.raw_size
    payload = bytearray(
        b"\x51"              # push ecx ) caller-saved across the cdecl call
        b"\x52"              # push edx )
        b"\x57"             # push edi   (the villager, the helper's argument)
        b"\xE8\0\0\0\0"      # call VF2EmbraceRoleIsFemale
        b"\x83\xC4\x04"      # cdecl cleanup
        b"\x5A"              # pop edx ) pops do not disturb flags, and the
        b"\x59"              # pop ecx ) cmp below is what sets them
        b"\x83\xF8\x01"      # cmp eax, 1   -> ZF exactly as the native cmp
        b"\xE9\0\0\0\0"      # jmp +0x088, the untouched native jne
    )
    if len(payload) != 21:
        raise AssertionError("Embrace role cave size drifted")
    struct.pack_into("<i", payload, 17, (function.value + 0x088) - (cave + 21))

    obj.insert_section_bytes(section.index, cave, bytes(payload))
    obj.append_relocation(section.index, cave + 4, helper, IMAGE_REL_I386_REL32)
    obj._parse()
    section = obj.section(function.section)
    raw = section.raw_ptr + hook
    obj.buf[raw:raw + 7] = (
        b"\xE9" + struct.pack("<i", cave - (hook + 5)) + b"\x90\x90"
    )
    obj.write(path)

    manifest["EmbraceRoleSplit"] = {
        "status": "installed",
        "function": function_name,
        "hook_offset": "+0x081",
        "stock_bytes": expected.hex(" "),
        "trampoline": hex(cave),
        "trampoline_size": len(payload),
        "resume": "+0x088 (the native jne, untouched)",
        "helper": EMBRACE_ROLE_HELPER_SYMBOL,
        "scope": (
            "same-sex pair only; every other couple gets the stock gender "
            "answer, so their two halves are unchanged"
        ),
        "reason": (
            "both partners run behaviour 358 and rely on differing genders "
            "to take opposite branches, so a same-sex pair performed the "
            "same half twice"
        ),
    }


def patch_six_child_private_time(manifest):
    """Send a couple at six children down the ordinary romantic path.

    theMainScene::HandleDropOnVillager gates the drop like this:

        +0x1EB  call IsRoomToPopulate
        +0x1F2  jne  -> +0x256      room available
        +0x1F4  cmp/jl -> +0x256    age
        +0x200  cmp/jl -> +0x256    age
        +0x218  je   -> +0x256      same gender
        +0x21A  push -1 / push 72Dh  <- the refusal, 7 dead bytes once
                                        jumped over
        +0x256  cooldown, then the romantic sequence

    Every gate that lets the drop proceed jumps to +0x256, so the refusal
    is replaced with a jump to that same target. The family being full is
    then treated exactly like there being room, and everything downstream
    -- the cooldown included -- runs stock.

    An earlier version jumped to +0x26E instead, past the cooldown and
    directly into the sequence. Landing mid-sequence skipped a gate the
    native code always applies; +0x256 is the target the game itself uses.

    No cave, helper or reproduced instructions: the seven bytes are
    unreachable once jumped over, and +0x218's two-byte branch above it is
    left completely alone.
    """
    path = PATCHED / "theMainScene.obj"
    obj = CoffObject(path)
    function_name = "?HandleDropOnVillager@theMainScene@@IAEXAAVCVillager@@@Z"
    function = obj.symbol(function_name)
    section = obj.section(function.section)

    hook = function.value + 0x21A
    raw = section.raw_ptr + hook
    expected = bytes.fromhex("6AFF682D070000")
    if bytes(obj.buf[raw:raw + len(expected)]) != expected:
        raise RuntimeError(
            "theMainScene::HandleDropOnVillager six-child refusal drifted at +0x21A"
        )
    gate = bytes(obj.buf[section.raw_ptr + function.value + 0x218:
                         section.raw_ptr + function.value + 0x21A])
    if gate != bytes.fromhex("743C"):
        raise RuntimeError(
            "theMainScene::HandleDropOnVillager same-gender gate drifted at +0x218"
        )

    target = function.value + 0x256
    obj.buf[raw:raw + 5] = b"\xE9" + struct.pack("<i", target - (hook + 5))

    # 0% pregnancy. TryToMakeBaby keeps its native stack frame and every
    # other route, but returns before ChanceOfPregnancy/Impregnate for a
    # qualifying pair -- a same-sex marriage, or an opposite-sex couple
    # already at six children. Both cases are couples that cannot be trying
    # for a baby, which is the whole point of the relabelling.
    try_name = "?TryToMakeBaby@theMainScene@@IAEXXZ"
    try_func = obj.symbol(try_name)
    try_sec = obj.section(try_func.section)
    try_hook = try_func.value
    expected_try_prefix = bytes.fromhex("55 8B EC 83 EC 08 53 56 89 4D FC")
    if bytes(obj.buf[try_sec.raw_ptr + try_hook:
                     try_sec.raw_ptr + try_hook + len(expected_try_prefix)]) != expected_try_prefix:
        raise RuntimeError("TryToMakeBaby entry anchor drifted")
    try_helper = obj.append_undefined_symbol(SAME_SEX_TRY_TO_MAKE_BABY_SKIP_HELPER_SYMBOL)
    try_cave = try_sec.raw_size
    try_trampoline = bytearray(
        expected_try_prefix      # execute the native frame setup first
        + b"\xE8\0\0\0\0"        # call VF2SkipSameSexTryToMakeBaby
        b"\x84\xC0"              # eligible pair?
        b"\x74\x02"              # no -> continue into the native body
        b"\xC9\xC3"              # yes -> leave; return without pregnancy
        b"\xE9\0\0\0\0"          # native body, after the reproduced prologue
    )
    if len(try_trampoline) != 27:
        raise AssertionError("Private-time TryToMakeBaby trampoline size drifted")
    struct.pack_into("<i", try_trampoline, 12, 0)
    struct.pack_into(
        "<i", try_trampoline, 23,
        (try_hook + 0x0B) - (try_cave + len(try_trampoline)),
    )
    obj.insert_section_bytes(try_sec.index, try_cave, bytes(try_trampoline))
    obj.append_relocation(try_sec.index, try_cave + 12, try_helper, IMAGE_REL_I386_REL32)
    try_func = obj.symbol(try_name)
    try_sec = obj.section(try_func.section)
    obj.buf[try_sec.raw_ptr + try_hook:try_sec.raw_ptr + try_hook + 5] = (
        b"\xE9" + struct.pack("<i", try_cave - (try_hook + 5))
    )

    obj.write(path)

    manifest["SixChildPrivateTime"] = {
        "status": "installed",
        "function": function_name,
        "hook_offset": "+0x21A",
        "stock_bytes": expected.hex(" "),
        "target": "+0x256",
        "target_rationale": (
            "the same target every native gate uses to let the drop proceed, "
            "so the cooldown and the rest of the sequence still run"
        ),
        "same_gender_gate": "+0x218 left stock (74 3c)",
        "label": (
            "behaviour 358 is relabelled 'Having private adult romantic time' "
            "by patch_behavior_label_variants"
        ),
        "pregnancy": "0%; TryToMakeBaby returns before ChanceOfPregnancy/Impregnate",
    }


def patch_villager_manager_spouse_accessors(manifest):
    """Back-fill the missing half of a couple in GetMatriarch/GetPatriarch.

    CVillagerManager::GetMatriarch and GetPatriarch are byte-identical
    scans except for one instruction -- "cmp dword ptr [esi-1512Ch], 1"
    (gender==1, female) vs the same compare against 0 (male) -- over the
    current generation's resident, employed, living adults. A couple whose
    two spouses share a gender can only ever satisfy one of them, so the
    other returns null and every native consumer of "the couple" quietly
    does nothing.

    A COFF relocation census over the pristine objects found 66 call sites
    in 19 functions across 10 objects going through these two accessors,
    including CVillager::Impregnate, theMainScene::TryToMakeBaby,
    CVillagerState::UpdateHappinessState, CVillagerPlans::ProcessCurrentPlan,
    CBankingDlg's constructor, CTutorialTip::IsWorldReadyForTip, and the
    CanFire considerers of four island events. Hooking each of those
    individually is unmaintainable; fixing the two accessors fixes all of
    them at once.

    The hook is deliberately placed on the NULL-RETURN path (+0x48,
    "pop edi; pop esi; xor eax,eax; pop ebx; ret") rather than at the
    function entry, so the native scan is never skipped -- only its failure
    is back-filled. When the scan succeeds the function is byte-identical
    to stock, which is every opposite-sex household. The cave reproduces
    the same three pops (so the stack is restored exactly as stock did),
    calls the resolver, and returns whatever it produced -- which is null
    unless a genuine second spouse exists, in which case the accessor's
    stock null result is returned unchanged.
    """
    path = PATCHED / "VillagerManager.obj"
    obj = CoffObject(path)
    stock_null_return = bytes.fromhex("5F5E33C05BC3")
    accessors = (
        (
            "?GetMatriarch@CVillagerManager@@QAEPAVCVillager@@XZ",
            SPOUSE_ACCESSOR_MATRIARCH_HELPER_SYMBOL,
            "matriarch",
        ),
        (
            "?GetPatriarch@CVillagerManager@@QAEPAVCVillager@@XZ",
            SPOUSE_ACCESSOR_PATRIARCH_HELPER_SYMBOL,
            "patriarch",
        ),
    )
    records = {}
    for name, helper_symbol, label in accessors:
        function = obj.symbol(name)
        section = obj.section(function.section)
        hook = function.value + 0x48
        raw = section.raw_ptr + hook
        if bytes(obj.buf[raw:raw + len(stock_null_return)]) != stock_null_return:
            raise RuntimeError(
                f"CVillagerManager::Get{label.title()} null-return path drifted"
            )
        helper = obj.append_undefined_symbol(helper_symbol)
        cave = section.raw_size
        payload = bytearray(
            b"\x5F"          # pop edi   ) restore exactly what the stock
            b"\x5E"          # pop esi   ) null-return path popped, so the
            b"\x5B"          # pop ebx   ) stack is identical either way
            b"\xE8\0\0\0\0"  # call the resolver (cdecl, no arguments)
            b"\xC3"          # ret with EAX = spouse, or 0 for stock behavior
        )
        if len(payload) != 9:
            raise AssertionError("Spouse accessor cave size drifted")
        obj.insert_section_bytes(section.index, cave, bytes(payload))
        obj.append_relocation(section.index, cave + 4, helper, IMAGE_REL_I386_REL32)
        # Appending to one COMDAT section shifts every later section's raw
        # pointer, so re-resolve before writing the trampoline.
        obj._parse()
        section = obj.section(function.section)
        raw = section.raw_ptr + hook
        obj.buf[raw:raw + len(stock_null_return)] = (
            b"\xE9" + struct.pack("<i", cave - (hook + 5)) + b"\x90"
        )
        records[label] = {
            "function": name,
            "hook_offset": hex(0x48),
            "stock_bytes": stock_null_return.hex(" "),
            "replacement": f"jmp cave; cave = pop edi/esi/ebx; call {helper_symbol}; ret",
            "helper": helper_symbol,
            "trampoline": hex(cave),
            "hooked_path": "null-return only; the native gender scan is untouched",
        }
    obj.write(path)

    manifest["SpouseAccessorBackfill"] = {
        "status": "installed",
        "reason": (
            "GetMatriarch/GetPatriarch are hard gender filters, so a "
            "same-gender couple can only ever fill one of the two roles and "
            "every native consumer of 'the couple' no-ops for them"
        ),
        "census": {
            "method": "COFF relocation scan over the pristine objects",
            "call_sites": 66,
            "functions": 19,
            "objects": 10,
        },
        "native_scan_preserved": True,
        "opposite_sex_behavior": "byte-identical to stock (scan succeeds, hook unreached)",
        "distinctness_guarantee": (
            "each resolver excludes whichever villager the other accessor's "
            "native scan will return, so the two can never resolve to the "
            "same person"
        ),
        "accessors": records,
    }


def patch_marriage_finalization_for_same_sex(manifest):
    """Let a same-sex marriage actually finalize when Accept is pressed.

    patch_same_sex_marriage() deliberately leaves CDatingScene::HandleMessage
    untouched -- Accept, Reject, and the shared tail all remain stock. That is
    correct for candidate *generation*, but Accept's own finalization gate
    (money, achievements, CFamilyTree::UpdateParents, and the marriage
    life-event announcement) only runs when CVillagerManager::GetMatriarch()
    AND GetPatriarch() both return non-null. Disassembly of both confirms
    they are byte-identical except for one gender-equality check (Matriarch
    requires gender==1, Patriarch requires gender==0) over the current
    generation's adults, so once a same-sex marriage lets two adults share a
    gender, one of these two accessors always comes back null and Accept
    silently skips the whole block: no announcement, and the couple is never
    recorded as married in the family tree (which is also why
    VF2ClassifyRomanticSpouseDrop treats them as strangers afterward,
    dropping them into the native argue instead of Private Romantic Time).

    Confirmed via decompiled disassembly of the real HandleMessage: the
    Accept path's `if (Matriarch && Patriarch)` guard compiles to
    "test esi,esi / jz +0x220 / test edi,edi / jz +0x220" at +0x142 (ESI =
    Matriarch, EDI = Patriarch), immediately followed by the finalization
    call chain at +0x152 (theGameState::Get(), the achievement/money/
    UpdateParents/QueueLifeEventPending sequence). +0x220 is the shared
    "skip finalization" landing point Reject's own path already uses.

    Hook only that 16-byte guard: when both non-null, behavior is
    byte-identical to stock. When either is null, additionally try
    VF2ResolveSameSexMarriagePairForFinalization() (only succeeds when Same-
    Sex Marriage is active) to find the real pair via VF2MarriagePair()'s
    existing fallback, and substitute it into ESI/EDI before falling into
    the same untouched finalization call chain. If that also fails (Same-Sex
    Marriage off, or no valid pair), take the exact same stock skip path as
    before -- opposite-sex behavior, and any edge case this hook doesn't
    recognize, is unchanged.
    """
    dating_path = PATCHED / "DatingScene.obj"
    dating = CoffObject(dating_path)
    handle_name = "?HandleMessage@CDatingScene@@UAE_NHJ@Z"
    handle = dating.symbol(handle_name)
    section = dating.section(handle.section)
    guard_hook = handle.value + 0x142
    guard_raw = section.raw_ptr + guard_hook
    expected_guard = bytes.fromhex("85F60F84D800000085FF0F84D0000000")
    if bytes(dating.buf[guard_raw:guard_raw + len(expected_guard)]) != expected_guard:
        raise RuntimeError("Dating Accept Matriarch/Patriarch guard drifted")

    finalize_target = handle.value + 0x152
    skip_target = handle.value + 0x222

    pair_helper = dating.append_undefined_symbol(
        MARRIAGE_FINALIZATION_PAIR_HELPER_SYMBOL
    )
    first_symbol = dating.append_undefined_symbol(
        MARRIAGE_FINALIZATION_FIRST_SYMBOL
    )
    second_symbol = dating.append_undefined_symbol(
        MARRIAGE_FINALIZATION_SECOND_SYMBOL
    )

    cave = section.raw_size
    payload = bytearray(
        b"\x85\xF6"          # test esi, esi
        b"\x74\x00"          # jz check_fallback (offset 13)
        b"\x85\xFF"          # test edi, edi
        b"\x74\x00"          # jz check_fallback (offset 13)
        b"\xE9\0\0\0\0"    # both non-null: jmp finalize (stock path)
        # check_fallback (offset 13):
        b"\xE8\0\0\0\0"    # call VF2ResolveSameSexMarriagePairForFinalization
        b"\x84\xC0"          # test al, al
        b"\x74\x00"          # jz fallback_failed (offset 39)
        b"\x8B\x35\0\0\0\0"  # mov esi, [gVF2MarriageFinalizationFirst]
        b"\x8B\x3D\0\0\0\0"  # mov edi, [gVF2MarriageFinalizationSecond]
        b"\xE9\0\0\0\0"    # jmp finalize
        # fallback_failed (offset 39):
        b"\xE9\0\0\0\0"    # jmp skip (stock null-guard path)
    )
    if len(payload) != 44:
        raise AssertionError("Marriage finalization pair cave size drifted")
    struct.pack_into("<b", payload, 3, 13 - 4)
    struct.pack_into("<b", payload, 7, 13 - 8)
    struct.pack_into("<i", payload, 9, finalize_target - (cave + 13))
    struct.pack_into("<b", payload, 21, 39 - 22)
    struct.pack_into("<i", payload, 35, finalize_target - (cave + 39))
    struct.pack_into("<i", payload, 40, skip_target - (cave + 44))

    dating.insert_section_bytes(section.index, cave, bytes(payload))
    dating.append_relocation(section.index, cave + 14, pair_helper, IMAGE_REL_I386_REL32)
    dating.append_relocation(section.index, cave + 24, first_symbol, IMAGE_REL_I386_DIR32)
    dating.append_relocation(section.index, cave + 30, second_symbol, IMAGE_REL_I386_DIR32)

    dating._parse()
    section = dating.section(handle.section)
    guard_raw = section.raw_ptr + guard_hook
    dating.buf[guard_raw:guard_raw + len(expected_guard)] = (
        b"\xE9" + struct.pack("<i", cave - (guard_hook + 5))
        + b"\x90" * (len(expected_guard) - 5)
    )
    dating.write(dating_path)

    manifest["MarriageFinalizationSameSex"] = {
        "status": "installed",
        "function": handle_name,
        "hook_offset": "+0x142",
        "hook_span": "16 bytes (the Matriarch/Patriarch null-check guard only; "
            "the finalization call chain at +0x152 and the shared skip path "
            "at +0x222 are never touched)",
        "trampoline": hex(cave),
        "helper": MARRIAGE_FINALIZATION_PAIR_HELPER_SYMBOL,
        "fallback_source": "VF2MarriagePair() via VF2ResolveSameSexMarriagePairForFinalization(), "
            "gated on VF2SameSexMarriageToggleActive()",
        "stock_off_state": "byte-identical native Matriarch/Patriarch guard when Same-Sex "
            "Marriage is inactive or VF2MarriagePair() finds no valid pair",
        "reason": (
            "Accept silently skipped money, achievements, "
            "CFamilyTree::UpdateParents, and the marriage announcement for any "
            "same-sex marriage, because GetMatriarch()/GetPatriarch() are hard "
            "gender filters that can never both return non-null for a "
            "same-gender pair. Reported live: no marriage announcement, the "
            "adult not shown as married, and dropping the pair on each other "
            "argues instead of starting Private Romantic Time (all downstream "
            "of the family tree never being updated)."
        ),
    }
    return


def patch_villager_details_same_sex_married_status(manifest):
    """Show "Married" on the details screen for a same-sex couple too.

    theVillagerScene::UpdateScene decides which status string to show for
    the currently-viewed adult with the exact same hard gender-blind check
    patch_marriage_finalization_for_same_sex already fixed for Accept:
    CVillagerManager::GetMatriarch() AND GetPatriarch() must both return a
    villager. A same-sex couple always leaves one of those two null (there
    is no opposite-gender adult in the current generation to find), so this
    is a second, independent site with the identical bug -- reported live
    as the same-sex adult's details screen never showing "Married".

    Disassembly of clean theVillagerScene.obj confirms the exact span:
    +0x225 is "cmp [ebp+var_20C],0 / jz +0x0E / cmp [ebp+var_210],0 / mov
    eax,75Eh / jnz +5 / mov eax,75Fh" (28 bytes) -- var_20C/var_210 hold
    Patriarch/Matriarch, computed just above; 0x75E/0x75F are the
    "Married"/blank StringIds; var_208 holds the raw CVillager* being
    viewed, computed even earlier and untouched by this span.

    Hook only that 28-byte span: when both non-null, behavior is
    byte-identical to stock (eax=0x75E). When either is null, additionally
    try VF2SameSexMarriedStatusForVillager(viewed) (only succeeds when Same-
    Sex Marriage is active and the viewed adult is one half of a resolvable
    same-sex pair via VF2MarriagePair()) before falling back to the exact
    same stock "not married" result (eax=0x75F) -- opposite-sex couples and
    any case this hook doesn't recognize are unchanged.
    """
    scene_path = PATCHED / "theVillagerScene.obj"
    scene = CoffObject(scene_path)
    update_name = "?UpdateScene@theVillagerScene@@MAEXXZ"
    update = scene.symbol(update_name)
    section = scene.section(update.section)
    guard_hook = update.value + 0x225
    guard_raw = section.raw_ptr + guard_hook
    expected_guard = bytes.fromhex(
        "83BDF4FDFFFF00" "740E" "83BDF0FDFFFF00" "B85E070000" "7505" "B85F070000"
    )
    if bytes(scene.buf[guard_raw:guard_raw + len(expected_guard)]) != expected_guard:
        raise RuntimeError("Villager details Matriarch/Patriarch married-status guard drifted")

    rejoin_target = update.value + 0x241
    helper = scene.append_undefined_symbol(VILLAGER_DETAILS_MARRIED_STATUS_HELPER_SYMBOL)

    cave = section.raw_size
    payload = bytearray(
        b"\x83\xBD\xF4\xFD\xFF\xFF\x00"  # cmp [ebp+var_20C],0 (Patriarch)
        b"\x74\x00"                        # jz fallback (offset 28)
        b"\x83\xBD\xF0\xFD\xFF\xFF\x00"  # cmp [ebp+var_210],0 (Matriarch)
        b"\x74\x00"                        # jz fallback (offset 28)
        b"\xB8\x5E\x07\x00\x00"            # mov eax, 0x75E (native married)
        b"\xE9\0\0\0\0"                  # -> rejoin
        # fallback (offset 28): native check failed; try the same-sex pair
        b"\xFF\xB5\xF8\xFD\xFF\xFF"        # push [ebp+var_208] (viewed villager)
        b"\xE8\0\0\0\0"                  # call VF2SameSexMarriedStatusForVillager
        b"\x83\xC4\x04"                    # caller cleanup
        b"\x84\xC0"                        # test al,al
        b"\x74\x00"                        # jz not_married (offset 56)
        b"\xB8\x5E\x07\x00\x00"            # mov eax, 0x75E (same-sex fallback married)
        b"\xE9\0\0\0\0"                  # -> rejoin
        # not_married (offset 56):
        b"\xB8\x5F\x07\x00\x00"            # mov eax, 0x75F (not married)
        b"\xE9\0\0\0\0"                  # -> rejoin
    )
    if len(payload) != 66:
        raise AssertionError("Villager details married-status cave size drifted")
    struct.pack_into("<b", payload, 8, 28 - 9)      # jz@7 -> fallback(28)
    struct.pack_into("<b", payload, 17, 28 - 18)    # jz@16 -> fallback(28)
    struct.pack_into("<i", payload, 24, rejoin_target - (cave + 28))    # jmp@23 -> rejoin
    struct.pack_into("<i", payload, 35, 0)          # call@34 rel32 filled by relocation below
    struct.pack_into("<b", payload, 45, 56 - 46)    # jz@44 -> not_married(56)
    struct.pack_into("<i", payload, 52, rejoin_target - (cave + 56))    # jmp@51 -> rejoin
    struct.pack_into("<i", payload, 62, rejoin_target - (cave + 66))    # jmp@61 -> rejoin

    scene.insert_section_bytes(section.index, cave, bytes(payload))
    scene.append_relocation(section.index, cave + 35, helper, IMAGE_REL_I386_REL32)

    scene._parse()
    section = scene.section(update.section)
    guard_raw = section.raw_ptr + guard_hook
    scene.buf[guard_raw:guard_raw + len(expected_guard)] = (
        b"\xE9" + struct.pack("<i", cave - (guard_hook + 5))
        + b"\x90" * (len(expected_guard) - 5)
    )
    scene.write(scene_path)

    manifest["VillagerDetailsSameSexMarriedStatus"] = {
        "status": "installed",
        "function": update_name,
        "hook_offset": "+0x225",
        "hook_span": "28 bytes (the Matriarch/Patriarch null-check guard only)",
        "trampoline": hex(cave),
        "helper": VILLAGER_DETAILS_MARRIED_STATUS_HELPER_SYMBOL,
        "fallback_source": "VF2MarriagePair() via VF2SameSexMarriedStatusForVillager(), "
            "gated on VF2SameSexMarriageToggleActive() and scoped to the specific "
            "villager currently being viewed",
        "stock_off_state": "byte-identical native Matriarch/Patriarch guard when Same-Sex "
            "Marriage is inactive, the viewed adult isn't part of a resolvable pair, "
            "or the pair is opposite-sex",
        "reason": (
            "theVillagerScene's details screen never showed \"Married\" for a "
            "same-sex adult, because it runs the exact same hard gender-filtered "
            "GetMatriarch()/GetPatriarch() check as Accept's finalization gate, "
            "independently of whether the family tree record itself is correct."
        ),
    }
    return


def patch_force_successful_pregnancy_callsites(manifest):
    """Install the persisted success, gender, and multiplicity pregnancy one-shots."""
    obj_path = PATCHED / "VillagerPlans.obj"
    obj = CoffObject(obj_path)
    process_name = "?ProcessCurrentPlan@CVillagerPlans@@QAEXAAVCVillager@@@Z"
    process = obj.symbol(process_name)
    section = obj.section(process.section)

    callsites = (
        (
            0x955,
            0x956,
            "?ChanceOfPregnancy@CVillagerState@@QAE_NHHH@Z",
            FORCE_PREGNANCY_CHANCE_HELPER_SYMBOL,
        ),
        (
            0x979,
            0x97A,
            "?Impregnate@CVillager@@QAE_NHPBDHH_N@Z",
            FORCE_PREGNANCY_BIRTH_HELPER_SYMBOL,
        ),
    )
    patched = []
    for call_relative, relocation_relative, native, helper_name in callsites:
        call = process.value + call_relative
        relocation = process.value + relocation_relative
        raw = section.raw_ptr + call
        if bytes(obj.buf[raw : raw + 5]) != b"\xE8\0\0\0\0":
            raise RuntimeError(
                f"Force-pregnancy callsite drifted: {process_name}+{call_relative:#x}"
            )

        matches = []
        for index in range(section.nreloc):
            vaddr, symbol_index, relocation_type = struct.unpack_from(
                "<IIH", obj.buf, section.reloc_ptr + index * 10
            )
            if vaddr == relocation:
                matches.append((
                    obj.symbol_by_index[symbol_index].name,
                    relocation_type,
                ))
        expected = [(native, IMAGE_REL_I386_REL32)]
        if matches != expected:
            raise RuntimeError(
                f"Force-pregnancy relocation drifted at "
                f"{process_name}+{relocation_relative:#x}: {matches}"
            )

        helper = obj.append_undefined_symbol(helper_name)
        obj.retarget_relocation(
            section.index,
            relocation,
            helper,
            IMAGE_REL_I386_REL32,
        )
        patched.append({
            "call_offset": hex(call_relative),
            "relocation_offset": hex(relocation_relative),
            "original_target": native,
            "replacement": helper_name,
        })

    obj.write(obj_path)

    villager_path = PATCHED / "Villager.obj"
    villager = CoffObject(villager_path)
    impregnate_name = "?Impregnate@CVillager@@QAE_NHPBDHH_N@Z"
    impregnate = villager.symbol(impregnate_name)
    impregnate_section = villager.section(impregnate.section)
    if impregnate.value != 0 or impregnate_section.raw_size != 0x2D7:
        raise RuntimeError("Native CVillager::Impregnate layout drifted")

    count_hook = impregnate.value + 0xE3
    count_hook_raw = impregnate_section.raw_ptr + count_hook
    if bytes(villager.buf[count_hook_raw : count_hook_raw + 5]) != b"\xE8\0\0\0\0":
        raise RuntimeError("Forced birth-count hook callsite drifted")
    original_get_relocation = impregnate.value + 0xE4
    original_get_matches = []
    for index in range(impregnate_section.nreloc):
        vaddr, symbol_index, relocation_type = struct.unpack_from(
            "<IIH",
            villager.buf,
            impregnate_section.reloc_ptr + index * 10,
        )
        if vaddr == original_get_relocation:
            original_get_matches.append((
                villager.symbol_by_index[symbol_index].name,
                relocation_type,
            ))
    if original_get_matches != [
        ("?Get@theGameState@@SAPAV1@XZ", IMAGE_REL_I386_REL32)
    ]:
        raise RuntimeError(
            f"Forced birth-count native Get relocation drifted: "
            f"{original_get_matches}"
        )

    count_cave = impregnate_section.raw_size
    count_cave_code = bytearray(
        b"\x53"                              # push ebx: available slots
        b"\x57"                              # push edi: mother
        b"\xE8\0\0\0\0"                    # call count helper
        b"\x83\xC4\x08"                    # add esp,8
        b"\xE8\0\0\0\0"                    # original theGameState::Get
        b"\xE9\0\0\0\0"                    # resume at Impregnate+0xE8
    )
    struct.pack_into(
        "<i",
        count_cave_code,
        16,
        (impregnate.value + 0xE8) - (count_cave + len(count_cave_code)),
    )
    villager.insert_section_bytes(
        impregnate_section.index,
        count_cave,
        bytes(count_cave_code),
    )
    count_helper = villager.append_undefined_symbol(
        FORCED_BIRTH_COUNT_HELPER_SYMBOL
    )
    move_relocation(
        villager,
        impregnate_section.index,
        original_get_relocation,
        count_cave + 11,
        rtype=IMAGE_REL_I386_REL32,
    )
    villager.append_relocation(
        impregnate_section.index,
        count_cave + 3,
        count_helper,
        IMAGE_REL_I386_REL32,
    )
    impregnate = villager.symbol(impregnate_name)
    impregnate_section = villager.section(impregnate.section)
    count_hook_raw = impregnate_section.raw_ptr + count_hook
    villager.buf[count_hook_raw : count_hook_raw + 5] = (
        b"\xE9"
        + struct.pack("<i", count_cave - (count_hook + 5))
    )

    gender_call = impregnate.value + 0x14D
    gender_relocation = impregnate.value + 0x14E
    gender_call_raw = impregnate_section.raw_ptr + gender_call
    if bytes(villager.buf[gender_call_raw : gender_call_raw + 5]) != b"\xE8\0\0\0\0":
        raise RuntimeError("Forced baby-gender spawn callsite drifted")
    gender_native = (
        "?SpawnSpecificPeep@CVillagerManager@@QAE?B"
        "HHW4EGender@@HPBD1HHHHHH_N@Z"
    )
    gender_matches = []
    for index in range(impregnate_section.nreloc):
        vaddr, symbol_index, relocation_type = struct.unpack_from(
            "<IIH",
            villager.buf,
            impregnate_section.reloc_ptr + index * 10,
        )
        if vaddr == gender_relocation:
            gender_matches.append((
                villager.symbol_by_index[symbol_index].name,
                relocation_type,
            ))
    if gender_matches != [(gender_native, IMAGE_REL_I386_REL32)]:
        raise RuntimeError(
            f"Forced baby-gender native spawn relocation drifted: "
            f"{gender_matches}"
        )
    gender_helper = villager.append_undefined_symbol(
        FORCED_BABY_GENDER_HELPER_SYMBOL
    )
    villager.retarget_relocation(
        impregnate_section.index,
        gender_relocation,
        gender_helper,
        IMAGE_REL_I386_REL32,
    )
    villager.write(villager_path)

    manifest["ForceSuccessfulPregnancy"] = {
        "status": "implemented with persisted success, gender, and multiplicity one-shots",
        "store_item_id": "0x136",
        "persistent_record_id": hex(CUSTOM_ACHIEVEMENT_PURCHASE_MASK_RECORD_ID),
        "persistent_mask": hex(FORCE_SUCCESSFUL_PREGNANCY_MASK),
        "callsites": patched,
        "eligibility": "native ProcessCurrentPlan partner and gender checks remain unchanged",
        "chance": "armed flag bypasses only CVillagerState::ChanceOfPregnancy",
        "capacity": "native CVillager::Impregnate empty-offspring-slot check remains unchanged",
        "clear_condition": "flag clears only when native CVillager::Impregnate returns true",
        "failed_birth": "flag remains armed when native CVillager::Impregnate returns false",
        "multiples": "stock count roll remains the fallback; an armed count one-shot replaces only its result before native spawning",
        "native_birth_routes": "naming, spawning, InitTwin, family-tree, achievement, statistics, and birth logic remain native",
        "machine_code": "the two ProcessCurrentPlan calls and first-baby spawn call remain byte-identical with REL32 retargets; the count-result hook uses one guarded near-jump trampoline",
        "gender_controls": {
            "store_item_ids": {"male": "0x137", "female": "0x138"},
            "persistent_masks": {"male": "0x8", "female": "0x10"},
            "mutually_exclusive_mask": "0x18",
            "first_baby_spawn_relocation": "CVillager::Impregnate+0x14E",
            "twins_and_triplets": "native InitTwin clones the forced first baby, including gender",
        },
        "multiplicity_controls": {
            "store_item_ids": {
                "singleton": "0x139",
                "twins": "0x13a",
                "triplets": "0x13b",
            },
            "persistent_masks": {
                "singleton": "0x20",
                "twins": "0x40",
                "triplets": "0x80",
            },
            "mutually_exclusive_mask": "0xe0",
            "count_field": "CVillager+0x6B1C",
            "count_hook": "CVillager::Impregnate+0xE3",
            "count_trampoline": hex(count_cave),
            "capacity_rule": "requested 1/2/3 clamped to native EmptyOffspringSlots result",
        },
        "one_shot_clear_mask": "0xfc",
    }


def patch_older_villager_mortality(manifest):
    """Install a dormant optional replacement for only stock old-age death."""
    obj = CoffObject(PATCHED / "VillagerManager.obj")
    stock = CoffObject(SRC_OBJS / "VillagerManager.obj")
    function_name = (
        "?AllVillagersRealtimePhysiologyAndProductivityUpkeep@"
        "CVillagerManager@@QAEXXZ"
    )
    sym = obj.symbol(function_name)
    stock_sym = stock.symbol(function_name)
    sec = obj.section(sym.section)
    stock_sec = stock.section(stock_sym.section)
    if sym.value != 0 or stock_sym.value != 0:
        raise RuntimeError("Unexpected VillagerManager upkeep symbol offset")
    if stock_sec.raw_size != 0x7E2:
        raise RuntimeError("Unexpected stock VillagerManager upkeep span")

    hook = sym.value + 0x353
    stock_continue = sym.value + 0x35C
    mortality_done = sym.value + 0x3C8
    expected = b"\x6A\x00\x8B\xCB\xE8\x00\x00\x00\x00\x8D\x34\x80"
    raw = sec.raw_ptr + hook
    if bytes(obj.buf[raw : raw + len(expected)]) != expected:
        raise RuntimeError("Unexpected VillagerManager mortality hook bytes")

    cave = sec.raw_size
    trampoline = bytearray([
        0x6A, 0x00,                         # push 0
        0x8B, 0xCB,                         # mov ecx,ebx
        0xE8, 0, 0, 0, 0,                  # call FoodGroupsActive observer
        0x80, 0x3D, 0, 0, 0, 0, 0x00,     # cmp byte ptr [flag],0
        0x74, 0x20,                         # je stock continuation
        0x50,                               # push eax ; food groups
        0xFF, 0x73, 0x08,                   # push [ebx+8] ; internal age
        0xE8, 0, 0, 0, 0,                  # call mortality helper
        0x83, 0xC4, 0x08,                   # add esp,8
        0x85, 0xC0,                         # test eax,eax
        0x74, 0x0B,                         # je mortality done jump
        0x6A, 0x02,                         # push OldAge
        0x6A, 0x00,                         # push zero health
        0x8B, 0xCB,                         # mov ecx,ebx
        0xE8, 0, 0, 0, 0,                  # call SetHealth
        0xE9, 0, 0, 0, 0,                  # jmp mortality done
        0xE9, 0, 0, 0, 0,                  # stock: jmp original+35C
    ])
    if len(trampoline) != 55:
        raise AssertionError("Older-mortality trampoline size drifted")
    struct.pack_into("<i", trampoline, 46, mortality_done - (cave + 50))
    struct.pack_into("<i", trampoline, 51, stock_continue - (cave + 55))
    obj.insert_section_bytes(sec.index, cave, bytes(trampoline))

    set_health_symbol = obj.symbol(
        "?SetHealth@CVillagerState@@QAEXHW4ECauseOfDeath@@@Z"
    ).index
    food_observer_symbol = obj.append_undefined_symbol(
        LONGEVITY_FOOD_GROUPS_HELPER_SYMBOL
    )
    obj.retarget_relocation(
        sec.index,
        hook + 5,
        food_observer_symbol,
        IMAGE_REL_I386_REL32,
    )
    move_relocation(
        obj,
        sec.index,
        hook + 5,
        cave + 5,
        food_observer_symbol,
        IMAGE_REL_I386_REL32,
    )
    flag_symbol = obj.append_undefined_symbol(OLDER_MORTALITY_FLAG_SYMBOL)
    helper_symbol = obj.append_undefined_symbol(OLDER_MORTALITY_HELPER_SYMBOL)
    obj.append_relocation(sec.index, cave + 11, flag_symbol, IMAGE_REL_I386_DIR32)
    obj.append_relocation(sec.index, cave + 23, helper_symbol, IMAGE_REL_I386_REL32)
    obj.append_relocation(sec.index, cave + 41, set_health_symbol, IMAGE_REL_I386_REL32)

    sec = obj.section(sym.section)
    raw = sec.raw_ptr + hook
    detour = b"\xE9" + struct.pack("<i", cave - (hook + 5)) + b"\x90" * 4
    obj.buf[raw : raw + len(detour)] = detour
    obj.write(PATCHED / "VillagerManager.obj")

    manifest["OlderVillagerMortality"] = {
        "status": "dormant native hook installed in every executable",
        "offline_patcher_setting": "older_villager_mortality",
        "category": "optional",
        "default": False,
        "function": function_name,
        "hook_offset": hex(hook),
        "stock_path": (
            "flag zero calls native FoodGroupsActive and rejoins at +0x35C; "
            "stock mortality instructions +0x35C..+0x3C7 remain unchanged"
        ),
        "enabled_path": (
            "one millionth-resolution roll on exact 20-tick birthdays, then rejoin at +0x3C8"
        ),
        "runtime_flag": {
            "symbol": OLDER_MORTALITY_FLAG_SYMBOL,
            "source_section": OLDER_MORTALITY_FLAG_SECTION,
            "size": 1,
            "default": "00",
            "enabled": "01",
            "linked_location_status": "pending_link_metadata",
        },
        "curve": {
            "main_distribution": (
                "annual intensity 0.00365*n + 0.06*max(0,n-55), where "
                "n=max(0, displayed age-(55+active food groups))"
            ),
            "nutrition": (
                "stock threshold T=55+active food groups, clamped to 0-4 groups"
            ),
            "rare_tail": (
                "additional intensity begins after effective age 110; the "
                "999999/1000000 cap retains one non-death outcome"
            ),
            "hard_maximum": None,
            "annual_hazard_cap_millionths": OLDER_MORTALITY_HAZARD_CAP_MILLIONTHS,
            "source": "B155.5 full-game calibrated monotonic curve",
            "random_limit": OLDER_MORTALITY_RANDOM_LIMIT,
            "table_first_age": OLDER_MORTALITY_TABLE_FIRST_AGE,
            "table_last_age": OLDER_MORTALITY_TABLE_LAST_AGE,
        },
        "unchanged": [
            "CVillagerBio::IsOld remains age 55",
            "all sickness, healing, productivity, and non-old-age physiology paths",
            "stock mortality when the option is disabled",
        ],
        "longevity_goal_observer": {
            "helper": LONGEVITY_FOOD_GROUPS_HELPER_SYMBOL,
            "internal_age_source": "CVillagerState+0x8",
            "runs_after": "native FoodGroupsActive",
            "runs_before": "old-age mortality roll",
            "mortality_flag_independent": True,
        },
    }


def patch_longevity_achievement_load_reconciliation(manifest):
    obj_path = PATCHED / "VillagerManager.obj"
    obj = CoffObject(obj_path)
    load_name = (
        "?LoadState@CVillagerManager@@QAE?B_N"
        "AAUSSaveState@CVillager@@@Z"
    )
    load = obj.symbol(load_name)
    sec = obj.section(load.section)
    call_offset = load.value + 0x33
    relocation_offset = load.value + 0x34
    raw = sec.raw_ptr + call_offset
    if bytes(obj.buf[raw : raw + 5]) != b"\xE8\0\0\0\0":
        raise RuntimeError("VillagerManager longevity load callsite drifted")

    relocation = None
    for index in range(sec.nreloc):
        vaddr, symbol_index, rtype = struct.unpack_from(
            "<IIH", obj.buf, sec.reloc_ptr + index * 10
        )
        if vaddr == relocation_offset:
            relocation = (
                obj.symbol_by_index[symbol_index].name,
                rtype,
            )
            break
    original = "?LoadState@CVillager@@QAE?B_NAAUSSaveState@1@@Z"
    if relocation != (original, IMAGE_REL_I386_REL32):
        raise RuntimeError(
            f"VillagerManager longevity load relocation drifted: {relocation}"
        )

    helper = obj.append_undefined_symbol(LONGEVITY_LOAD_HELPER_SYMBOL)
    obj.retarget_relocation(
        sec.index,
        relocation_offset,
        helper,
        IMAGE_REL_I386_REL32,
    )
    obj.write(obj_path)
    manifest["LongevityAchievementHooks"] = {
        "status": "birthday observer plus load reconciliation",
        "achievement_ids": [hex(value) for value in range(0x85, 0x8A)],
        "internal_age_thresholds": [1400, 1600, 1800, 2000, 2441],
        "displayed_age_requirements": [70, 80, 90, 100, ">122"],
        "birthday_hook": {
            "function": (
                "CVillagerManager::"
                "AllVillagersRealtimePhysiologyAndProductivityUpkeep"
            ),
            "observer": LONGEVITY_AGE_HELPER_SYMBOL,
            "before_old_age_death_roll": True,
            "optional_mortality_independent": True,
        },
        "load_reconciliation": {
            "caller": "CVillagerManager::LoadState",
            "call_offset": hex(call_offset - load.value),
            "original_target": original,
            "replacement": LONGEVITY_LOAD_HELPER_SYMBOL,
            "native_load_result_preserved": True,
        },
    }


