def patch_pet_achievement_callsites(manifest):
    """Award pet goals only for successful placement and active loaded pets."""
    def target_at(obj, section, vaddr):
        matches = []
        for index in range(section.nreloc):
            relocation = struct.unpack_from(
                "<IIH", obj.buf, section.reloc_ptr + index * 10
            )
            if relocation[0] == vaddr:
                matches.append((
                    obj.symbol_by_index[relocation[1]].name,
                    relocation[2],
                ))
        if len(matches) != 1:
            raise RuntimeError(
                f"Expected one relocation at {vaddr:#x}, got {matches}"
            )
        return matches[0]

    spawn_native = "?SpawnPet@CPetManager@@QAE?BHHHH@Z"
    load_native = (
        "?LoadState@CPetManager@@QAE?B_N"
        "AAUSSaveState@CPet@@@Z"
    )

    furniture_path = PATCHED / "FurnitureManager.obj"
    furniture = CoffObject(furniture_path)
    drop_name = "?DropFurniture@CFurnitureManager@@QAEX_N@Z"
    drop = furniture.symbol(drop_name)
    drop_sec = furniture.section(drop.section)
    spawn_call = drop.value + 0x21D
    spawn_relocation = drop.value + 0x21E
    if bytes(
        furniture.buf[
            drop_sec.raw_ptr + spawn_call :
            drop_sec.raw_ptr + spawn_call + 5
        ]
    ) != b"\xE8\0\0\0\0":
        raise RuntimeError("Pet achievement placement callsite drifted")
    spawn_target = target_at(furniture, drop_sec, spawn_relocation)
    if spawn_target != (spawn_native, IMAGE_REL_I386_REL32):
        raise RuntimeError(
            f"Pet achievement placement relocation drifted: {spawn_target}"
        )
    spawn_helper = furniture.append_undefined_symbol(PET_SPAWN_HELPER_SYMBOL)
    furniture.retarget_relocation(
        drop_sec.index,
        spawn_relocation,
        spawn_helper,
        IMAGE_REL_I386_REL32,
    )
    furniture.write(furniture_path)

    game_state_path = PATCHED / "theGameState.obj"
    game_state = CoffObject(game_state_path)
    load_name = "?Load@theGameState@@UAE_NH@Z"
    load = game_state.symbol(load_name)
    load_sec = game_state.section(load.section)
    load_call = load.value + 0x250
    load_relocation = load.value + 0x251
    if bytes(
        game_state.buf[
            load_sec.raw_ptr + load_call :
            load_sec.raw_ptr + load_call + 5
        ]
    ) != b"\xE8\0\0\0\0":
        raise RuntimeError("Pet achievement load callsite drifted")
    load_target = target_at(game_state, load_sec, load_relocation)
    if load_target != (load_native, IMAGE_REL_I386_REL32):
        raise RuntimeError(
            f"Pet achievement load relocation drifted: {load_target}"
        )
    load_helper = game_state.append_undefined_symbol(PET_LOAD_HELPER_SYMBOL)
    game_state.retarget_relocation(
        load_sec.index,
        load_relocation,
        load_helper,
        IMAGE_REL_I386_REL32,
    )
    game_state.write(game_state_path)

    manifest["PetAchievementHooks"] = {
        "status": "successful placement observer plus active-pet load reconciliation",
        "achievement_ids": [hex(value) for value in range(0x8A, 0x90)] + [hex(CUSTOM_ACHIEVEMENT_TURTLE_ID)],
        "placed_pet_item_range": ["0x23b", "0x248"],
        "placement": {
            "caller": "CFurnitureManager::DropFurniture",
            "call_offset": hex(spawn_call - drop.value),
            "original_target": spawn_native,
            "replacement": PET_SPAWN_HELPER_SYMBOL,
            "award_condition": "native SpawnPet return >= 0",
            "native_return_preserved": True,
        },
        "load_reconciliation": {
            "caller": "theGameState::Load(int)",
            "call_offset": hex(load_call - load.value),
            "original_target": load_native,
            "replacement": PET_LOAD_HELPER_SYMBOL,
            "active_slots_scanned": 30,
            "native_load_result_preserved": True,
        },
    }


def patch_family_tree_appearance_achievement_callsites(manifest):
    """Observe persistent family-tree writes and reconcile existing records."""
    def target_at(obj, section, vaddr):
        matches = []
        for index in range(section.nreloc):
            relocation = struct.unpack_from(
                "<IIH", obj.buf, section.reloc_ptr + index * 10
            )
            if relocation[0] == vaddr:
                matches.append((
                    obj.symbol_by_index[relocation[1]].name,
                    relocation[2],
                ))
        if len(matches) != 1:
            raise RuntimeError(
                f"Expected one relocation at {vaddr:#x}, got {matches}"
            )
        return matches[0]

    update_native = (
        "?UpdatePeepRecord@CFamilyTree@@QAEX"
        "PAUSPeepRecord@1@@Z"
    )
    update_calls = (
        ("?AddOffspring@CFamilyTree@@QAE_NABVCVillager@@@Z", 0x7B),
        ("?StartNextGeneration@CFamilyTree@@QAE_NAAVCVillager@@H@Z", 0xD0),
        ("?UpdateCurrentFamilyRecord@CFamilyTree@@QAEXXZ", 0x16),
        ("?UpdateCurrentFamilyRecord@CFamilyTree@@QAEXXZ", 0x24),
        ("?UpdateCurrentFamilyRecord@CFamilyTree@@QAEXXZ", 0x37),
        ("?UpdateParents@CFamilyTree@@QAE_NAAVCVillager@@0@Z", 0xDC),
    )
    family_path = PATCHED / "FamilyTree.obj"
    family = CoffObject(family_path)
    update_helper = family.append_undefined_symbol(
        APPEARANCE_UPDATE_HELPER_SYMBOL
    )
    update_manifest = []
    for function_name, call_relative in update_calls:
        function = family.symbol(function_name)
        section = family.section(function.section)
        call = function.value + call_relative
        relocation = call + 1
        if bytes(
            family.buf[
                section.raw_ptr + call :
                section.raw_ptr + call + 5
            ]
        ) != b"\xE8\0\0\0\0":
            raise RuntimeError(
                f"Family-tree appearance callsite drifted: "
                f"{function_name}+{call_relative:#x}"
            )
        target = target_at(family, section, relocation)
        if target != (update_native, IMAGE_REL_I386_REL32):
            raise RuntimeError(
                f"Family-tree appearance relocation drifted: "
                f"{function_name}+{call_relative:#x}: {target}"
            )
        family.retarget_relocation(
            section.index,
            relocation,
            update_helper,
            IMAGE_REL_I386_REL32,
        )
        update_manifest.append({
            "function": function_name,
            "call_offset": hex(call_relative),
            "relocation_offset": hex(call_relative + 1),
        })
    family.write(family_path)

    load_native = "?LoadState@CFamilyTree@@QAE?B_NABUSSaveState@1@@Z"
    game_state_path = PATCHED / "theGameState.obj"
    game_state = CoffObject(game_state_path)
    load_name = "?Load@theGameState@@UAE_NH@Z"
    load = game_state.symbol(load_name)
    section = game_state.section(load.section)
    call = load.value + 0x16F
    relocation = load.value + 0x170
    if bytes(
        game_state.buf[
            section.raw_ptr + call :
            section.raw_ptr + call + 5
        ]
    ) != b"\xE8\0\0\0\0":
        raise RuntimeError("Family-tree appearance load callsite drifted")
    target = target_at(game_state, section, relocation)
    if target != (load_native, IMAGE_REL_I386_REL32):
        raise RuntimeError(
            f"Family-tree appearance load relocation drifted: {target}"
        )
    load_helper = game_state.append_undefined_symbol(
        APPEARANCE_LOAD_HELPER_SYMBOL
    )
    game_state.retarget_relocation(
        section.index,
        relocation,
        load_helper,
        IMAGE_REL_I386_REL32,
    )
    game_state.write(game_state_path)

    manifest["FamilyTreeAppearanceAchievementHooks"] = {
        "status": "persistent-record updates plus load reconciliation",
        "achievement_ids": ["0x90", "0x91"],
        "requirements": {
            "Return of the Rainbow": {"gender": 1, "head": 48},
            "Spiky!": {"gender": 0, "head": 48},
        },
        "record_layout": {
            "present_byte": "0x1a",
            "gender_dword": "0x1c",
            "head_dword": "0x20",
        },
        "update_observers": {
            "original_target": update_native,
            "replacement": APPEARANCE_UPDATE_HELPER_SYMBOL,
            "callsites": update_manifest,
            "native_first": True,
            "relocation_only": True,
        },
        "load_reconciliation": {
            "caller": "theGameState::Load(int)",
            "call_offset": "0x16f",
            "original_target": load_native,
            "replacement": APPEARANCE_LOAD_HELPER_SYMBOL,
            "generation_cap": 30,
            "children_per_generation_cap": 6,
            "includes_dead_and_departed": True,
            "native_load_result_preserved": True,
        },
    }


def patch_lifetime_generation_counter(manifest):
    native_name = "?StartNextGeneration@CFamilyTree@@QAE_NAAVCVillager@@H@Z"
    helper_name = "@VF2StartNextGenerationAndCount@16"
    callsites = []
    for object_name in ("FamilyTree.obj", "AdoptionScene.obj"):
        obj = CoffObject(PATCHED / object_name)
        native_symbol = obj.symbol(native_name).index
        helper_symbol = obj.append_undefined_symbol(helper_name)
        matches = []
        for section in obj.sections:
            for index in range(section.nreloc):
                entry = section.reloc_ptr + index * 10
                vaddr, symbol_index, relocation_type = struct.unpack_from(
                    "<IIH", obj.buf, entry
                )
                if (
                    symbol_index == native_symbol
                    and relocation_type == IMAGE_REL_I386_REL32
                ):
                    matches.append((section, vaddr))
        if len(matches) != 1:
            raise RuntimeError(
                f"{object_name} expected one StartNextGeneration call, "
                f"found {len(matches)}"
            )
        section, vaddr = matches[0]
        if obj.buf[section.raw_ptr + vaddr - 1] != 0xE8:
            raise RuntimeError(
                f"{object_name} StartNextGeneration relocation is not a call"
            )
        obj.retarget_relocation(
            section.index,
            vaddr,
            helper_symbol,
            IMAGE_REL_I386_REL32,
        )
        obj.write(PATCHED / object_name)
        callsites.append({
            "object": object_name,
            "section": section.index,
            "relocation_vaddr": hex(vaddr),
        })

    scene = CoffObject(PATCHED / "AchievementsScene.obj")
    draw = scene.symbol("?DrawScene@CAchievementsScene@@MAEXXZ")
    draw_section = scene.section(draw.section)
    draw_raw = draw_section.raw_ptr + draw.value
    hook_offset = 0x105
    overwritten = b"\x6A\x64\x51\x8B\x4D\xF8"
    if (
        scene.buf[
            draw_raw + hook_offset :
            draw_raw + hook_offset + len(overwritten)
        ]
        != overwritten
    ):
        raise RuntimeError("Unexpected Goals-screen post-clipping draw bytes")
    draw_helper = scene.append_undefined_symbol(
        "_VF2DrawLifetimeGenerationCounter"
    )
    draw = scene.symbol("?DrawScene@CAchievementsScene@@MAEXXZ")
    draw_section = scene.section(draw.section)
    cave = draw_section.raw_size
    return_offset = draw.value + hook_offset + len(overwritten)
    cave_payload = (
        b"\x60"
        b"\xE8\x00\x00\x00\x00"
        b"\x61"
        + overwritten
        + b"\xE9"
        + section_rel32(cave + 13, 5, return_offset)
    )
    scene.insert_section_bytes(draw.section, cave, cave_payload)
    scene.append_relocation(
        draw.section,
        cave + 2,
        draw_helper,
        IMAGE_REL_I386_REL32,
    )
    patch_section_near_jump(
        scene,
        draw.section,
        draw.value + hook_offset,
        cave,
        len(overwritten),
        overwritten,
    )
    scene.write(PATCHED / "AchievementsScene.obj")

    manifest["LifetimeGenerationCounter"] = {
        "status": "patched",
        "storage": "CAchievement hidden record 0xA8 record+4 bits 8-31",
        "maximum": 0xFFFFFF,
        "migration": (
            "when the saved lifetime field is zero, seed from the current "
            "stock FamilyTree generation count"
        ),
        "increment": (
            "only after native StartNextGeneration returns success; the "
            "stock 30-record rollover remains unchanged"
        ),
        "reset_achievements": "preserves lifetime-generation bits",
        "goals_screen": {
            "label": "Generation: N",
            "helper": "_VF2DrawLifetimeGenerationCounter",
            "position": [760, 42],
            "widescreen_x_offset": True,
        },
        "callsites": callsites,
    }
    manifest["OldestPersonCounter"] = {
        "status": "patched",
        "storage": "CAchievement hidden record 0xA8 record+8 bits 16-31",
        "maximum_internal_age": 0xFFFF,
        "age_units_per_displayed_year": 20,
        "native_age_fields": [
            "CVillager+0x6A54 bio age",
            "CVillagerState+0x08 processed raw-age cursor",
        ],
        "update": "records the highest raw age observed by longevity award and load reconciliation routes",
        "legacy_migration": "existing saves seed from the oldest currently loaded qualifying villager; deceased history before this build cannot be reconstructed",
        "goals_screen": {
            "label": "Oldest Villager: N",
            "helper": "_VF2DrawLifetimeGenerationCounter",
            "position": [100, 42],
            "opposite": "Generation: N at x=760",
            "widescreen_x_offset": True,
        },
    }


def patch_collectable_item_holiday_ornaments(manifest):
    obj = CoffObject(PATCHED / "CollectableItem.obj")
    patches = []

    reset_sym = obj.symbol("?Reset@CCollectableItem@@QAEXXZ")
    reset_insert = reset_sym.value + 0x1ED
    reset_sec = obj.section(reset_sym.section)
    expected_reset = b"\xC7\x83\xAC\x08\x00\x00\x00\x00\x00\x00"
    if obj.buf[reset_sec.raw_ptr + reset_insert : reset_sec.raw_ptr + reset_insert + len(expected_reset)] != expected_reset:
        raise RuntimeError("Unexpected CCollectableItem::Reset insertion site")

    add_spawn_sym = obj.symbol("?AddSpawnArea@CCollectableItem@@QAEXUldwRect@@W4ECarrying@@@Z").index
    reset_payload = bytearray()
    reset_relocs = []
    for rect_symbol, _rect in HOLIDAY_ORNAMENT_SPAWN_RECTS:
        start = len(reset_payload)
        reset_payload += b"\x0F\x28\x05\x00\x00\x00\x00"  # movaps xmm0,[rect]
        reset_payload += b"\x8B\xCB"                      # mov ecx,ebx
        reset_payload += b"\x68" + struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTABLE_START)
        reset_payload += b"\x83\xEC\x10"                  # sub esp,10h
        reset_payload += b"\x8B\xC4"                      # mov eax,esp
        reset_payload += b"\x0F\x11\x00"                  # movups [eax],xmm0
        reset_payload += b"\xE8\x00\x00\x00\x00"          # call AddSpawnArea
        reset_relocs.append((start + 3, obj.symbol(rect_symbol).index, None))
        reset_relocs.append((start + len(reset_payload[start:]) - 4, add_spawn_sym, IMAGE_REL_I386_REL32))
    obj.insert_section_bytes(reset_sym.section, reset_insert, bytes(reset_payload))
    for local_off, symidx, rtype in reset_relocs:
        if rtype is None:
            obj.append_relocation(reset_sym.section, reset_insert + local_off, symidx)
        else:
            obj.append_relocation(reset_sym.section, reset_insert + local_off, symidx, rtype)
    patches.append({
        "function": "?Reset@CCollectableItem@@QAEXXZ",
        "insert_offset": "0x1ed",
        "spawn_area_count": len(HOLIDAY_ORNAMENT_SPAWN_RECTS),
        "base_collectable": hex(HOLIDAY_ORNAMENT_COLLECTABLE_START),
        "mobile_spawn_rects": [
            [hex(value) for value in rect]
            for _symbol, rect in HOLIDAY_ORNAMENT_SPAWN_RECTS
        ],
    })

    def insert_range_true(function_name, start_item, end_item):
        sym = obj.symbol(function_name)
        insert_off = sym.value + 0x06
        sec = obj.section(sym.section)
        expected = b"\x83\xF8"
        if obj.buf[sec.raw_ptr + insert_off : sec.raw_ptr + insert_off + len(expected)] != expected:
            raise RuntimeError(f"Unexpected {function_name} range insertion site")
        payload = bytearray()
        payload += b"\x3D" + struct.pack("<I", start_item)
        payload += b"\x7C\x0D"
        payload += b"\x3D" + struct.pack("<I", end_item)
        payload += b"\x7F\x06"
        payload += b"\xB0\x01"
        payload += b"\x5D"
        payload += b"\xC2\x04\x00"
        obj.insert_section_bytes(sym.section, insert_off, bytes(payload))
        return {
            "function": function_name,
            "insert_offset": "0x6",
            "range": f"{hex(start_item)}-{hex(end_item)}",
        }

    patches.append(insert_range_true(
        "?IsCommonCollectable@CCollectableItem@@QBE?B_NW4ECarrying@@@Z",
        HOLIDAY_ORNAMENT_COLLECTABLE_START,
        HOLIDAY_ORNAMENT_COLLECTABLE_START + 3,
    ))
    patches.append(insert_range_true(
        "?IsUncommonCollectable@CCollectableItem@@QBE?B_NW4ECarrying@@@Z",
        HOLIDAY_ORNAMENT_COLLECTABLE_START + 4,
        HOLIDAY_ORNAMENT_COLLECTABLE_START + 7,
    ))
    patches.append(insert_range_true(
        "?IsRareCollectable@CCollectableItem@@QBE?B_NW4ECarrying@@@Z",
        HOLIDAY_ORNAMENT_COLLECTABLE_START + 8,
        HOLIDAY_ORNAMENT_COLLECTABLE_END,
    ))

    count_sym = obj.symbol("?CollectionCount@CCollectableItem@@QBE?BHW4ECarrying@@_N11@Z")
    count_insert = count_sym.value + 0x0B
    count_sec = obj.section(count_sym.section)
    expected_count = b"\x8D\x42\x99"
    if obj.buf[count_sec.raw_ptr + count_insert : count_sec.raw_ptr + count_insert + len(expected_count)] != expected_count:
        raise RuntimeError("Unexpected CCollectableItem::CollectionCount insertion site")
    count_payload_len = 34
    count_continue = count_insert + count_payload_len
    count_target = count_sym.value + 0x5A + count_payload_len
    count_payload = bytearray()
    count_payload += b"\x81\xFA" + struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTABLE_START)
    count_payload += b"\x0F\x8C" + struct.pack("<i", count_continue - (count_insert + len(count_payload) + 6))
    count_payload += b"\x81\xFA" + struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTABLE_END)
    count_payload += b"\x0F\x8F" + struct.pack("<i", count_continue - (count_insert + len(count_payload) + 6))
    count_payload += b"\xBE" + struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTABLE_START)
    count_payload += b"\xE9" + struct.pack("<i", count_target - (count_insert + len(count_payload) + 5))
    if len(count_payload) != count_payload_len:
        raise RuntimeError("Unexpected CollectionCount payload length")
    obj.insert_section_bytes(count_sym.section, count_insert, bytes(count_payload))
    patches.append({
        "function": "?CollectionCount@CCollectableItem@@QBE?BHW4ECarrying@@_N11@Z",
        "insert_offset": "0xb",
        "range": f"{hex(HOLIDAY_ORNAMENT_COLLECTABLE_START)}-{hex(HOLIDAY_ORNAMENT_COLLECTABLE_END)}",
        "collection_base": hex(HOLIDAY_ORNAMENT_COLLECTABLE_START),
    })

    drop_sym = obj.symbol("?Drop@CCollectableItem@@UAEXAAVCVillager@@W4ECarrying@@@Z")
    drop_insert = drop_sym.value + 0x1D4
    drop_sec = obj.section(drop_sym.section)
    expected_drop = b"\x5F\x5E\x8B\xE5"
    if obj.buf[drop_sec.raw_ptr + drop_insert : drop_sec.raw_ptr + drop_insert + len(expected_drop)] != expected_drop:
        raise RuntimeError("Unexpected CCollectableItem::Drop insertion site")
    achievement_sym = obj.symbol("?Achievement@@3VCAchievement@@A").index
    increment_sym = obj.symbol("?IncrementProgress@CAchievement@@QAEXW4EAchievement@@H@Z").index
    drop_payload = bytearray()
    drop_payload += b"\x8D\x87" + struct.pack("<i", -HOLIDAY_ORNAMENT_COLLECTABLE_START)
    drop_payload += b"\x83\xF8\x0B"
    drop_payload += b"\x77\x00"
    drop_skip_rel_off = len(drop_payload) - 1
    drop_payload += b"\x6A\x01"
    drop_payload += b"\x6A" + bytes([HOLIDAY_ORNAMENT_ACHIEVEMENT_ID])
    drop_payload += b"\xB9\x00\x00\x00\x00"
    achievement_reloc_off = len(drop_payload) - 4
    drop_payload += b"\xE8\x00\x00\x00\x00"
    increment_reloc_off = len(drop_payload) - 4
    drop_payload += b"\x68" + struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTABLE_START)
    # If the family is not complete, the native JE returns to this hook.
    # Zeroing EDI makes that second pass fail the ornament-range test and exit.
    drop_payload += b"\x31\xFF"
    drop_payload += b"\xE9" + struct.pack("<i", (drop_sym.value + 0x168) - (drop_insert + len(drop_payload) + 5))
    drop_payload[drop_skip_rel_off] = len(drop_payload) - (drop_skip_rel_off + 1)
    obj.insert_section_bytes(drop_sym.section, drop_insert, bytes(drop_payload))
    obj.append_relocation(drop_sym.section, drop_insert + achievement_reloc_off, achievement_sym)
    obj.append_relocation(drop_sym.section, drop_insert + increment_reloc_off, increment_sym, IMAGE_REL_I386_REL32)
    patches.append({
        "function": "?Drop@CCollectableItem@@UAEXAAVCVillager@@W4ECarrying@@@Z",
        "insert_offset": "0x1d4",
        "first_copy_range": f"{hex(HOLIDAY_ORNAMENT_COLLECTABLE_START)}-{hex(HOLIDAY_ORNAMENT_COLLECTABLE_END)}",
        "complete_check_base": hex(HOLIDAY_ORNAMENT_COLLECTABLE_START),
        "specific_goal_row": hex(HOLIDAY_ORNAMENT_ACHIEVEMENT_ID),
        "incomplete_reentry_sentinel": "xor edi,edi",
        "duplicate_route": (
            "Duplicate ornaments retain the stock coin-only path; only a "
            "first copy increments Ornamentologist 0x5F"
        ),
    })

    obj.write(PATCHED / "CollectableItem.obj")
    manifest["CollectableItemHolidayOrnaments"] = {
        "status": "patched",
        "collectable_range": f"{hex(HOLIDAY_ORNAMENT_COLLECTABLE_START)}-{hex(HOLIDAY_ORNAMENT_COLLECTABLE_END)}",
        "spawn_model": "registered as three exact mobile AddSpawnArea regions; CCollectableItem::Update/Add and Lucky Rock odds remain stock",
        "spawn_area_count": len(HOLIDAY_ORNAMENT_SPAWN_RECTS),
        "mobile_spawn_rects": [
            [hex(value) for value in rect]
            for _symbol, rect in HOLIDAY_ORNAMENT_SPAWN_RECTS
        ],
        "exact_item_matching": {
            "find": "stock exact ECarrying equality retained",
            "was_item_spawned": "stock exact ECarrying equality retained",
            "reason": "mobile 1.7.16 Add selects a concrete 0x9E-0xA9 variant before duplicate checking",
        },
        "patches": patches,
    }


def patch_collectable_holiday_ornament_observers(manifest):
    obj = CoffObject(PATCHED / "Collectable.obj")

    ctor_sym = obj.symbol("??0CCollectable@@QAE@XZ")
    ctor_sec = obj.section(ctor_sym.section)
    insert_off = ctor_sym.value + 0x4C8
    expected_tail = b"\x8B\xC6\x5E\xC3"
    if obj.buf[ctor_sec.raw_ptr + insert_off : ctor_sec.raw_ptr + insert_off + len(expected_tail)] != expected_tail:
        raise RuntimeError("Unexpected CCollectable constructor ornament observer insertion site")

    collectable_item_sym = obj.symbol("?CollectableItem@@3VCCollectableItem@@A").index
    register_observer_sym = obj.symbol("?RegisterObserver@CCollectable@@QAEXW4ECarrying@@PAVICollectable@@@Z").index
    payload = bytearray()
    relocs = []
    for carrying in range(HOLIDAY_ORNAMENT_COLLECTABLE_START, HOLIDAY_ORNAMENT_COLLECTABLE_END + 1):
        start = len(payload)
        payload += b"\x68\x00\x00\x00\x00"              # push offset CollectableItem
        payload += b"\x68" + struct.pack("<I", carrying)
        payload += b"\x8B\xCE"                          # mov ecx,esi
        payload += b"\xE8\x00\x00\x00\x00"              # call RegisterObserver
        relocs.append((start + 1, collectable_item_sym, None))
        relocs.append((start + 13, register_observer_sym, IMAGE_REL_I386_REL32))

    obj.insert_section_bytes(ctor_sym.section, insert_off, bytes(payload))
    for local_off, symidx, rtype in relocs:
        if rtype is None:
            obj.append_relocation(ctor_sym.section, insert_off + local_off, symidx)
        else:
            obj.append_relocation(ctor_sym.section, insert_off + local_off, symidx, rtype)

    obj.write(PATCHED / "Collectable.obj")
    manifest["CollectableHolidayOrnamentObservers"] = {
        "status": "patched",
        "function": "??0CCollectable@@QAE@XZ",
        "insert_offset": hex(insert_off),
        "registered_collectables": [
            hex(item)
            for item in range(HOLIDAY_ORNAMENT_COLLECTABLE_START, HOLIDAY_ORNAMENT_COLLECTABLE_END + 1)
        ],
        "note": "Registers Holiday Ornaments with CCollectable so villager carry/drop calls reach CCollectableItem.",
    }


def patch_collection_scene_holiday_ornaments(manifest):
    obj = CoffObject(PATCHED / "CollectionScene.obj")
    holiday_desc_count = holiday_body_descriptor_count() if ENABLE_HOLIDAY_BODY_TYPES else 0
    page_entries = [
        (
            holiday_ornament_collection_item_image_id(index, holiday_desc_count),
            x,
            y,
        )
        for index, (x, y) in enumerate(HOLIDAY_ORNAMENT_COLLECTION_SLOT_POSITIONS)
    ]

    sm_sym_name = "?sm_sCollectable@CCollectionScene@@0PAUSCollectable@1@A"
    frame_sym_name = "?gCollectionFrame@@3PAUSCollectable@CCollectionScene@@A"
    label_sym_name = "?gCollectionLabel@@3PAUSCollectable@CCollectionScene@@A"
    label_info_sym_name = "?gLabelInfo@@3PAUsCollectionLabelInfo@@A"
    collectable_sym_name = "?gCollectable@@3PAW4ECarrying@@A"

    sm_sym = obj.symbol(sm_sym_name)
    obj.insert_section_bytes(
        sm_sym.section,
        sm_sym.value + 5 * HOLIDAY_ORNAMENT_COLLECTION_ITEM_COUNT * 12,
        b"".join(struct.pack("<III", *entry) for entry in page_entries),
    )

    frame_sym = obj.symbol(frame_sym_name)
    obj.insert_section_bytes(
        frame_sym.section,
        frame_sym.value + 5 * 12,
        struct.pack("<III", holiday_ornament_collection_background_image_id(holiday_desc_count), 0, 0),
    )

    label_sym = obj.symbol(label_sym_name)
    obj.insert_section_bytes(
        label_sym.section,
        label_sym.value + 5 * 12,
        struct.pack("<III", 0x198, 0x154, 0x5F),
    )

    label_info_sym = obj.symbol(label_info_sym_name)
    obj.insert_section_bytes(
        label_info_sym.section,
        label_info_sym.value + 5 * 20,
        struct.pack("<IIIII", holiday_ornament_collection_title_string_id(), 0xC3, 0x0C, 0xCE, 0x0C),
    )

    collectable_sym = obj.symbol(collectable_sym_name)
    obj.insert_section_bytes(
        collectable_sym.section,
        collectable_sym.value + 5 * HOLIDAY_ORNAMENT_COLLECTION_ITEM_COUNT * 4,
        struct.pack("<" + "I" * HOLIDAY_ORNAMENT_COLLECTION_ITEM_COUNT, *range(HOLIDAY_ORNAMENT_COLLECTABLE_START, HOLIDAY_ORNAMENT_COLLECTABLE_END + 1)),
    )

    mouse_sym = obj.symbol("?HandleMouse@CCollectionScene@@UAE_NHUldwPoint@@@Z")
    mouse_sec = obj.section(mouse_sym.section)
    mouse_raw = mouse_sec.raw_ptr + mouse_sym.value
    if obj.buf[mouse_raw + 0x4B : mouse_raw + 0x52] != b"\xC7\x43\x14\x04\x00\x00\x00":
        raise RuntimeError("Unexpected CCollectionScene::HandleMouse decrement wrap bytes")
    obj.buf[mouse_raw + 0x4E : mouse_raw + 0x52] = struct.pack("<I", HOLIDAY_ORNAMENT_COLLECTION_PAGE)
    if obj.buf[mouse_raw + 0x79 : mouse_raw + 0x7C] != b"\x83\xF8\x05":
        raise RuntimeError("Unexpected CCollectionScene::HandleMouse increment wrap bytes")
    obj.buf[mouse_raw + 0x7B] = HOLIDAY_ORNAMENT_COLLECTION_PAGE + 1

    draw_sym = obj.symbol("?DrawScene@CCollectionScene@@MAEXXZ")
    draw_sec = obj.section(draw_sym.section)
    draw_count_off = draw_sym.value + 0x17D
    draw_expected = b"\x8B\x47\x14\xFF\x74\x87\x18"
    draw_continue = draw_sym.value + 0x184
    draw_cave = draw_sec.raw_size
    draw_payload = bytearray()
    draw_payload += b"\xFF\x77\x14"                  # push [edi+14h] (page)
    draw_payload += b"\xE8\x00\x00\x00\x00"       # call page-count helper
    draw_payload += b"\x50"                           # push returned count
    draw_payload += b"\xE9" + section_rel32(
        draw_cave + len(draw_payload),
        5,
        draw_continue,
    )
    obj.insert_section_bytes(draw_sym.section, draw_cave, bytes(draw_payload))
    helper_sym = obj.append_undefined_symbol("_VF2CollectionPageCount@4")
    obj.append_relocation(
        draw_sym.section,
        draw_cave + 4,
        helper_sym,
        IMAGE_REL_I386_REL32,
    )
    patch_section_near_jump(
        obj,
        draw_sym.section,
        draw_count_off,
        draw_cave,
        len(draw_expected),
        draw_expected,
    )

    # Append the tooltip extension only after every in-function insertion in
    # this section, so its detour target cannot move afterward.
    mouse_sym = obj.symbol("?HandleMouse@CCollectionScene@@UAE_NHUldwPoint@@@Z")
    mouse_sec = obj.section(mouse_sym.section)
    tooltip_detour = mouse_sym.value + 0x1EB
    tooltip_expected = b"\x8B\x9C\x85\xC0\xFE\xFF\xFF"
    tooltip_continue = mouse_sym.value + 0x1F2
    tooltip_cave = mouse_sec.raw_size
    tooltip_payload = bytearray()
    tooltip_payload += b"\x83\xF8\x0F"
    tooltip_payload += b"\x72\x00"
    tooltip_stock_rel = len(tooltip_payload) - 1
    tooltip_payload += b"\x83\xF8\x12"
    tooltip_payload += b"\x73\x00"
    tooltip_high_rel = len(tooltip_payload) - 1
    tooltip_label_disp = holiday_ornament_collection_footer_string_ids()[0] - 0x0F
    tooltip_payload += b"\x8D\x98" + struct.pack("<I", tooltip_label_disp)
    tooltip_payload += b"\xE9" + section_rel32(
        tooltip_cave + len(tooltip_payload),
        5,
        tooltip_continue,
    )
    tooltip_stock = len(tooltip_payload)
    tooltip_payload[tooltip_stock_rel] = tooltip_stock - (tooltip_stock_rel + 1)
    tooltip_payload[tooltip_high_rel] = tooltip_stock - (tooltip_high_rel + 1)
    tooltip_payload += tooltip_expected
    tooltip_payload += b"\xE9" + section_rel32(
        tooltip_cave + len(tooltip_payload),
        5,
        tooltip_continue,
    )
    obj.insert_section_bytes(mouse_sym.section, tooltip_cave, bytes(tooltip_payload))
    patch_section_near_jump(
        obj,
        mouse_sym.section,
        tooltip_detour,
        tooltip_cave,
        len(tooltip_expected),
        tooltip_expected,
    )

    obj.write(PATCHED / "CollectionScene.obj")

    main_obj = CoffObject(PATCHED / "theMainScene.obj")
    map_sym = main_obj.symbol("?MapClickFeedback@theMainScene@@IAEXUldwPoint@@@Z")
    map_sec = main_obj.section(map_sym.section)
    final_count_call = map_sym.value + 0x66A
    expected_final_count_call = b"\xE8\x00\x00\x00\x00"
    if main_obj.buf[map_sec.raw_ptr + final_count_call : map_sec.raw_ptr + final_count_call + 5] != expected_final_count_call:
        raise RuntimeError("Unexpected theMainScene::MapClickFeedback final collection-count call")
    aggregate_helper_name = (
        "?CollectionCountWithHolidayOrnaments@CCollectableItem@@"
        "QBE?BHW4ECarrying@@_N11@Z"
    )
    aggregate_helper = main_obj.append_undefined_symbol(aggregate_helper_name)
    main_obj.retarget_relocation(
        map_sym.section,
        map_sym.value + 0x66B,
        aggregate_helper,
        IMAGE_REL_I386_REL32,
    )

    total_suffix_name = "??_C@_05FFJCODFA@?5?1?560?$AA@"
    total_suffix = main_obj.symbol(total_suffix_name)
    total_suffix_sec = main_obj.section(total_suffix.section)
    total_suffix_raw = total_suffix_sec.raw_ptr + total_suffix.value
    if main_obj.buf[total_suffix_raw : total_suffix_raw + 6] != b" / 60\x00":
        raise RuntimeError("Unexpected theMainScene collection-total suffix")
    main_obj.buf[total_suffix_raw : total_suffix_raw + 6] = b" / 72\x00"
    main_obj.write(PATCHED / "theMainScene.obj")

    manifest["CollectionSceneHolidayOrnaments"] = {
        "status": "patched",
        "page": HOLIDAY_ORNAMENT_COLLECTION_PAGE,
        "page_starts": [hex(value) for value in HOLIDAY_ORNAMENT_COLLECTION_PAGE_STARTS],
        "collectable_range": f"{hex(HOLIDAY_ORNAMENT_COLLECTABLE_START)}-{hex(HOLIDAY_ORNAMENT_COLLECTABLE_END)}",
        "title_string": hex(holiday_ornament_collection_title_string_id()),
        "background_image_id": hex(holiday_ornament_collection_background_image_id(holiday_desc_count)),
        "item_images": [
            {
                "collectable": hex(HOLIDAY_ORNAMENT_COLLECTABLE_START + index),
                "image_id": hex(image_id),
                "position": [x, y],
            }
            for index, (image_id, x, y) in enumerate(page_entries)
        ],
        "page_count_helper": "_VF2CollectionPageCount@4",
        "page_count_route": "fixed-size DrawScene detour calls the stdcall page-count helper instead of reading the five-entry stock count cache.",
        "page_count_detour_offset": "0x17d",
        "page_count_code_cave_offset": hex(draw_cave),
        "main_scene_total": {
            "function": "theMainScene::MapClickFeedback",
            "family_starts": [hex(value) for value in HOLIDAY_ORNAMENT_COLLECTION_PAGE_STARTS],
            "total": HOLIDAY_ORNAMENT_COLLECTION_TOTAL,
            "helper": aggregate_helper_name,
        },
        "tooltip_rarity_label_ids": [
            hex(label_id)
            for label_id in holiday_ornament_collection_footer_string_ids()
        ],
        "tooltip_rarity_note": "A fixed-size detour reaches an end-of-section code cave for common, uncommon, and rare ornament labels without shifting native HandleMouse branches.",
        "tooltip_detour_offset": "0x1eb",
        "tooltip_code_cave_offset": hex(tooltip_cave),
        "object_size_note": "CCollectionScene stays 0x30 bytes; DrawScene asks helper for page counts instead of adding a sixth cached field.",
    }


def patch_the_collector_holiday_ornaments(manifest):
    obj = CoffObject(PATCHED / "IslandEvents.obj")

    canfire_sym = obj.symbol("?CanFire@CEventTheCollector@@UAE_NXZ")
    canfire_sec = obj.section(canfire_sym.section)
    aggregate_helper_name = (
        "?CollectionCountWithHolidayOrnaments@CCollectableItem@@"
        "QBE?BHW4ECarrying@@_N11@Z"
    )
    aggregate_helper = obj.append_undefined_symbol(aggregate_helper_name)
    offer_count_relocations = []
    for operand_off, rarity in (
        (0x088, "common"),
        (0x0FB, "uncommon"),
        (0x171, "rare"),
    ):
        call_off = canfire_sym.value + operand_off - 1
        canfire_sec = obj.section(canfire_sym.section)
        if (
            obj.buf[
                canfire_sec.raw_ptr + call_off : canfire_sec.raw_ptr + call_off + 5
            ]
            != b"\xE8\x00\x00\x00\x00"
        ):
            raise RuntimeError(
                "Unexpected CEventTheCollector::CanFire collection-count call "
                f"at {operand_off:#x}"
            )
        obj.retarget_relocation(
            canfire_sym.section,
            canfire_sym.value + operand_off,
            aggregate_helper,
            IMAGE_REL_I386_REL32,
        )
        offer_count_relocations.append({
            "operand_offset": hex(operand_off),
            "rarity": rarity,
            "route": aggregate_helper_name,
        })

    impact_sym = obj.symbol("?ImpactGame@CEventTheCollector@@UAEXH@Z")
    impact_sec = obj.section(impact_sym.section)
    reset_tail = impact_sym.value + 0x5D
    expected_tail = (
        b"\xC7\x45\x08\x5E\x00\x00\x00"
        b"\xB9\x00\x00\x00\x00"
        b"\x5D\xE9\x00\x00\x00\x00"
    )
    if (
        obj.buf[
            impact_sec.raw_ptr + reset_tail :
            impact_sec.raw_ptr + reset_tail + len(expected_tail)
        ]
        != expected_tail
    ):
        raise RuntimeError("Unexpected CEventTheCollector::ImpactGame achievement-reset tail")
    keep_branch_raw = impact_sec.raw_ptr + impact_sym.value + 0x07
    if obj.buf[keep_branch_raw : keep_branch_raw + 2] != b"\x75\x66":
        raise RuntimeError("Unexpected CEventTheCollector::ImpactGame keep-choice branch")

    reset_helper_name = (
        "?ResetHolidayOrnamentCollectorProgress@CAchievement@@"
        "QAEXW4EAchievement@@@Z"
    )
    reset_helper = obj.append_undefined_symbol(reset_helper_name)
    obj.retarget_relocation(
        impact_sym.section,
        impact_sym.value + 0x6B,
        reset_helper,
        IMAGE_REL_I386_REL32,
    )
    obj.write(PATCHED / "IslandEvents.obj")

    manifest["TheCollectorHolidayOrnaments"] = {
        "status": "patched",
        "can_fire_function": "?CanFire@CEventTheCollector@@UAE_NXZ",
        "offer_count_relocations": offer_count_relocations,
        "availability_route": (
            "mobile-parity stock eligibility retained; Holiday counts join all "
            "three offer pools after the event fires"
        ),
        "impact_function": "?ImpactGame@CEventTheCollector@@UAEXH@Z",
        "achievement_reset_route": {
            "tail_relocation_operand": "0x6b",
            "helper": reset_helper_name,
            "stock_tail_argument": "0x5e",
            "holiday_progress": hex(HOLIDAY_ORNAMENT_ACHIEVEMENT_ID),
        },
        "keep_choice_branch": {
            "offset": "0x7",
            "bytes": "75 66",
            "unchanged": True,
        },
        "sell_choice": 0,
        "collection_reset": "stock CCollectableItem::ResetCollection() clears the collection state table, including added 0x9E-0xA9 entries",
        "achievement_reset": hex(HOLIDAY_ORNAMENT_ACHIEVEMENT_ID),
        "note": "Adds ornament base 0x9E to all three offer counts and resets unfinished Ornamentologist progress on Sell without inserting or shifting native branches.",
    }


def generation_lock_source_paths(source_dir=GENERATION_LOCK_ART_DIR):
    return {
        generation: source_dir / f"lock_{generation:02d}.png"
        for generation in range(2, LOCKED_GENERATION_FRAME_COUNT + 2)
    }


def sync_generation_lock_art(manifest):
    dst = OUT / "Images" / "locked.png"
    source_strip_width = LOCKED_GENERATION_FRAME_COUNT * LOCKED_GENERATION_CELL_WIDTH
    icon_dir = OUT / "Images" / "GenerationLocks"
    source_paths = generation_lock_source_paths()
    missing = [str(path) for path in source_paths.values() if not path.is_file()]
    status = {
        "source_mode": "individual_generation_lock_frames",
        "source_dir": str(GENERATION_LOCK_ART_DIR),
        "destination": str(dst),
        "expected_frames": LOCKED_GENERATION_FRAME_COUNT,
        "strip_size": [source_strip_width, LOCKED_GENERATION_CELL_HEIGHT],
        "standalone_icon_dir": str(icon_dir),
        "missing_sources": missing,
    }
    if missing:
        manifest["generation_lock_art_asset"] = status
        raise FileNotFoundError(
            "Missing bundled generation lock art: " + ", ".join(missing[:5])
            + ("..." if len(missing) > 5 else "")
        )

    dst.parent.mkdir(parents=True, exist_ok=True)
    icon_dir.mkdir(parents=True, exist_ok=True)
    from PIL import Image

    strip = Image.new("RGBA", (source_strip_width, LOCKED_GENERATION_CELL_HEIGHT), (0, 0, 0, 0))
    icons = []
    normalized = []
    for frame, generation in enumerate(range(2, LOCKED_GENERATION_FRAME_COUNT + 2)):
        source = source_paths[generation]
        image = Image.open(source).convert("RGBA")
        source_size = list(image.size)
        if image.size != (LOCKED_GENERATION_CELL_WIDTH, LOCKED_GENERATION_CELL_HEIGHT):
            image = image.resize((LOCKED_GENERATION_CELL_WIDTH, LOCKED_GENERATION_CELL_HEIGHT), Image.Resampling.LANCZOS)
            normalized.append(generation)
        icon_path = icon_dir / f"lock_{generation:02d}.png"
        image.save(icon_path)
        strip.paste(image, (frame * LOCKED_GENERATION_CELL_WIDTH, 0))
        icons.append({
            "generation": generation,
            "source": str(source),
            "source_size": source_size,
            "path": str(icon_path),
            "bytes": icon_path.stat().st_size,
        })
    strip.save(dst)
    status.update({
        "copied": True,
        "normalized_generations": normalized,
        "output_size": [source_strip_width, LOCKED_GENERATION_CELL_HEIGHT],
        "standalone_icons": icons,
        "bytes": dst.stat().st_size,
    })
    manifest["generation_lock_art_asset"] = status


def write_internal_workings_summary(manifest):
    text = """Virtual Families 2 - Internal Furniture/Store Notes
====================================================

Core model
----------
Most store-placeable things are EInventoryItem values. Furniture, pets,
decorations, rugs, and similar objects are backed by a central furniture/item
record, then exposed to store tabs through CInventoryManager category lists.

A valid item generally needs:

1. A CFurnitureManager item record.
2. A valid EImage descriptor/path.
3. Store category/list membership.
4. Valid short and long string IDs.
5. A price and generation lock value.
6. A compatible item type / behavior type.
7. A matching .fmap asset when the item is placeable.

Furniture records
-----------------
The furniture info table is:

    ?itemInfo@@3PAUsFurnitureInfo@@A

Each record is 0x6C bytes. The fields we rely on most are:

    +0x00  EInventoryItem item id
    +0x04  EImage image id
    +0x08  store price
    +0x0C  generation lock
    +0x10  item type / behavior category
    +0x14  short description string id
    +0x18  long description string id
    +0x58  extra/mobile field, zeroed for added furniture safety

Images
------
Images are managed by theGraphicsManager through:

    ?ImageList@@3PAUImageDescriptor@@A

Important descriptor fields are:

    +0x00  EImage id
    +0x04  path string pointer
    +0x08  columns / strip count
    +0x0C  rows / grid rows

Normal furniture uses paths such as:

    Furniture/CouchBlue.png
    Furniture/Chaise_red.png

The game commonly calls:

    theGraphicsManager::GetImageGrid(EImage)
    theGraphicsManager::Draw(...)
    theGraphicsManager::DrawCell(...)

Store categories
----------------
Items do not appear in store tabs just because a furniture record exists. Their
item IDs must also be inserted into CInventoryManager category arrays.

Important lists include:

    gFurniture2List      Living Room
    gFurniture3List      Dining/Office style categories
    gFurniture4List      Bedroom
    gFurniture5List      Outdoors
    gFurniture6List      Additional furniture category
    gAccessoriesList     Accessories
    gPetList             Pets

When extending a list, both the array contents and the store/category count
logic must be extended. If the counts are not patched, new items can appear to
replace base-game entries.

Store draw flow
---------------
The store render path is approximately:

    CScrollingStoreScene::DrawVisibleStoreItem(...)
      -> CInventoryManager::GetCategoryItem(category, index)
      -> CInventoryManager::DrawItem(...)
      -> CInventoryManager::IsLocked(item)
      -> CInventoryManager::GetLockGenerationLevel(item)
      -> draw generation-lock icon if locked
      -> CInventoryManager::GetShortDesc(item)
      -> CInventoryManager::GetLongDesc(item)
      -> CalcPrice(item)
      -> DrawMoney(...)

Furniture previews eventually delegate into CFurnitureManager drawing paths for
furniture-range items.

Strings
-------
Names and descriptions come from theStringManager. Each furniture record points
to a short and long string id. If either id has no valid string table row, the
game displays:

    Unknown String Id!!!!

Generation locks
----------------
Generation lock is the integer at furniture record +0x0C.

The desktop store originally only sorted/considered generation-locked items up
to generation 9. The additive build raises that visible lock window to 30.

The original desktop lock art was one small locked.png strip for generations
2-9. For generations 2-30, this build generates standalone images:

    Images/GenerationLocks/lock_02.png
    ...
    Images/GenerationLocks/lock_30.png

The store's lock draw call is retargeted to _VF2DrawGenerationLock, which maps
frame generation-2 to the corresponding standalone image. This avoids the old
DrawCell strip wrapping/slicing behavior.

Fmaps and behavior
------------------
Placeable furniture uses .fmap files in Assets. These appear to define collision
and interaction regions/hotspots. If an added mobile item has an unsupported
desktop behavior hotspot, dropping a villager on it can crash.

For safety:

    - Vibrant couches keep couch-compatible behavior and couch-style fmaps.
    - Most non-couch mobile-only added decor has its behavior grid sanitized.
    - Risky mobile item types are overridden to safer desktop donor types where
      needed.

Item type matters
-----------------
The item type field at record +0x10 affects how villagers and game systems treat
the item. Matching base-game couch item type/behavior is what made custom
couches sittable. Inert/decor types prevent unsupported interaction dispatch.

Common failure symptoms
-----------------------
Missing store item:
    Item is not in a category list, or category count/list capacity was not
    patched.

Replaces an existing item:
    Category array/count extension is wrong.

Unknown String Id!!!!:
    Bad string IDs or missing string table rows.

Wrong or missing sprite:
    Bad image id, descriptor, path, or missing PNG.

Crash when dropping a person:
    Bad item type, unsafe .fmap behavior grid, or unsupported behavior callback.

Wrong lock art:
    Bad generation value or lock draw path.

Wrong store section:
    Item was inserted into the wrong CInventoryManager category list.
"""
    path = OUT / "VF2_INTERNAL_WORKINGS_SUMMARY.txt"
    path.write_text(text, encoding="utf-8")
    manifest["internal_workings_summary"] = {
        "path": str(path),
        "status": "written",
    }


def sync_behavior_assets(manifest):
    assets = OUT / "Assets"
    assets.mkdir(parents=True, exist_ok=True)
    copied = []
    invisible_outdoor_copied = []
    invisible_transparent_copied = []
    vf3_tv_copied = []
    missing = []
    sanitized = []

    def find_fmap_source(filename):
        # Checked-in and base-game sources are consulted BEFORE OUT/Assets.
        # OUT/Assets is not neutral: when VF2_PREVIOUS_BUILD_DIR is set --
        # which is how the matrix, and therefore every release, builds --
        # seed_from_previous_build has already copied the previous release's
        # Assets into it. Looking there first means a build reuses whatever
        # the last release shipped and never consults the real source, which
        # is exactly the carry-forward that let the VF3 TV sources go missing
        # unnoticed from B164 to B168. All 35 donors resolve from the vanilla
        # payload, so preferring it costs nothing and makes donor resolution
        # identical in seeded and unseeded builds.
        # Payload first, then the mobile OBB: these donors are desktop
        # base-game assets, and the OBB's same-named fmap is not always the
        # same file (work/assets/TextAsset's TVFlatScreenStd.png.fmap differs
        # from the payload's, and it is the payload's that every shipped build
        # has used). The OBB stays as the fallback for mobile-only fmaps the
        # desktop payload does not carry.
        for source_dir in vanilla_payload_fmap_source_dirs() + FMAP_SOURCE_DIRS:
            candidate = source_dir / filename
            if candidate.exists():
                return candidate
        local = assets / filename
        if local.exists():
            return local
        return None

    def copy_donor_fmap(target, donor, bucket):
        src = find_fmap_source(donor)
        if src is None:
            missing.append({"target": target, "donor": donor})
            return
        donor_dst = assets / donor
        if src.resolve() != donor_dst.resolve():
            shutil.copy2(src, donor_dst)
        dst = assets / target
        shutil.copy2(src, dst)
        bucket.append({
            "target": target,
            "donor": donor,
            "source": str(src),
            "bytes": dst.stat().st_size,
        })

    for target, donor in COUCH_FMAP_DONORS.items():
        copy_donor_fmap(target, donor, copied)
    for target, donor in NEW_FURNITURE_FMAP_DONORS.items():
        copy_donor_fmap(target, donor, copied)
    for target, donor in INVISIBLE_OUTDOOR_FMAP_DONORS.items():
        copy_donor_fmap(target, donor, invisible_outdoor_copied)
    for target, donor in INVISIBLE_TRANSPARENT_FMAP_DONORS.items():
        copy_donor_fmap(target, donor, invisible_transparent_copied)
    for target, donor in VF3_TV_FMAP_DONORS.items():
        copy_donor_fmap(target, donor, vf3_tv_copied)
    for item in manifest["items"]:
        reason = safety_fmap_reason(item)
        if not reason:
            continue
        target = Path(item["path"]).name + ".fmap"
        dst = assets / target
        if not dst.exists():
            missing.append({"target": target, "reason": "small_decor_safety_fmap_missing"})
            continue
        data = bytearray(dst.read_bytes())
        if len(data) < 0x30 or data[:4] != b"QAMF":
            missing.append({"target": target, "reason": "small_decor_safety_fmap_unrecognized"})
            continue
        content_start = 0x20
        content_end = len(data) - 0x10
        if content_end <= content_start:
            missing.append({"target": target, "reason": "small_decor_safety_fmap_has_no_grid"})
            continue
        before_cells = sum(
            1
            for offset in range(content_start, content_end, 4)
            if data[offset:offset + 4] != b"\x00\x00\x00\x00"
        )
        for offset in range(content_start, content_end):
            data[offset] = 0
        dst.write_bytes(data)
        sanitized.append({
            "target": target,
            "item_id": item["item_id"],
            "name": item["name"],
            "reason": reason,
            "bytes": len(data),
            "zeroed_range": [hex(content_start), hex(content_end)],
            "nonzero_grid_cells_before": before_cells,
        })
    manifest["behavior_assets"] = {
        "couch_fmap_donors": copied,
        "invisible_outdoor_fmap_donors": invisible_outdoor_copied,
        "invisible_transparent_fmap_donors": invisible_transparent_copied,
        "vf3_tv_fmap_donors": vf3_tv_copied,
        "small_decor_sanitized_fmaps": sanitized,
        "missing": missing,
    }


def seed_mobile_furniture_behavior_evidence(manifest):
    """Preserve the APK furniture maps locally before making desktop-safe copies."""
    mobile_items = [
        item
        for item in manifest["items"]
        if item["mobile_data"].get("mobile_row") is not None
    ]
    mobile_ids = [int(item["item_id"], 16) for item in mobile_items]
    expected_ids = list(range(0x2AA, 0x2E9))
    if mobile_ids != expected_ids:
        raise RuntimeError(
            "Mobile furniture behavior evidence must cover exact IDs 0x2AA-0x2E8"
        )

    assets = OUT / "Assets"
    assets.mkdir(parents=True, exist_ok=True)
    records = []
    copied = 0
    for item in mobile_items:
        filename = Path(item["path"]).name + ".fmap"
        source = MOBILE_FURNITURE_BEHAVIOR_SOURCE_DIR / filename
        record = {
            "item_id": item["item_id"],
            "name": item["name"],
            "filename": filename,
            "source_status": "missing from supplied mobile OBB",
            "runtime_status": "rendered-only pending a proven desktop behavior route",
        }
        if source.is_file():
            data = source.read_bytes()
            if len(data) < 0x30 or data[:4] != b"QAMF":
                raise RuntimeError(f"Unrecognized mobile furniture map: {source}")
            destination = assets / filename
            shutil.copy2(source, destination)
            source_sha = hashlib.sha256(data).hexdigest()
            if hashlib.sha256(destination.read_bytes()).hexdigest() != source_sha:
                raise RuntimeError(f"Mobile furniture map copy mismatch: {filename}")
            record.update({
                "source_status": "preserved from supplied mobile OBB",
                "source_sha256": source_sha,
                "source_bytes": len(data),
            })
            copied += 1
        records.append(record)

    if copied != 41:
        raise RuntimeError(
            f"Expected 41 preserved mobile furniture maps, found {copied}"
        )
    manifest["MobileFurnitureBehaviorEvidence"] = {
        "status": "source evidence preserved; runtime behavior routes remain gated until proven",
        "mobile_item_range": "0x2aa-0x2e8",
        "mobile_item_count": len(records),
        "source_fmap_count": copied,
        "missing_fmap_count": len(records) - copied,
        "excluded_scope": [
            "patcher-created Invisible furniture",
            "custom colorful couches",
            "LDW posters",
            "VF3 imports",
        ],
        "items": records,
    }


def validate_mobile_chaise_pc_fmaps(manifest):
    records = []
    filenames = (
        "Chaise_blue.png.fmap",
        "Chaise_brown.png.fmap",
        "Chaise_green.png.fmap",
        "Chaise_red.png.fmap",
    )
    for item_id, filename in zip(MOBILE_CHAISE_ITEM_IDS, filenames):
        mobile_path = MOBILE_FURNITURE_BEHAVIOR_SOURCE_DIR / filename
        pc_path = MOBILE_FURNITURE_BEHAVIOR_PC_FMAP_DIR / filename
        mobile = mobile_path.read_bytes()
        pc = pc_path.read_bytes()
        if len(pc) != len(mobile) or pc[:4] != b"QAMF":
            raise RuntimeError(f"Invalid PC chaise furniture map: {pc_path}")
        width, height = struct.unpack_from("<ii", pc, 24)
        if (width, height) != (19, 14):
            raise RuntimeError(f"Unexpected PC chaise grid: {filename}")
        grid_end = 32 + width * height * 4
        if pc[:32] != mobile[:32] or pc[grid_end:] != mobile[grid_end:]:
            raise RuntimeError(f"PC chaise header/trailer drifted: {filename}")
        expected_object_offsets = {
            32 + (y * width + x) * 4 for x, y in MOBILE_CHAISE_PC_CELLS
        }
        expected_slot_offset = 32 + (
            MOBILE_CHAISE_PC_SLOT_CELL[1] * width + MOBILE_CHAISE_PC_SLOT_CELL[0]
        ) * 4
        actual_object_offsets = set()
        actual_slot_offsets = set()
        for offset in range(32, grid_end, 4):
            value = struct.unpack_from("<I", pc, offset)[0]
            if value == MOBILE_CHAISE_PC_CELL_VALUE:
                actual_object_offsets.add(offset)
            elif value == MOBILE_CHAISE_PC_SLOT_CELL_VALUE:
                actual_slot_offsets.add(offset)
            elif value:
                raise RuntimeError(
                    f"PC chaise contains unsupported cell {value:#x}: {filename}"
                )
        if actual_object_offsets != expected_object_offsets:
            raise RuntimeError(f"PC chaise EObject cells drifted: {filename}")
        if actual_slot_offsets != {expected_slot_offset}:
            raise RuntimeError(f"PC chaise peep-slot anchor drifted: {filename}")
        records.append({
            "item_id": hex(item_id),
            "filename": filename,
            "source_sha256": hashlib.sha256(pc).hexdigest(),
            "source_bytes": len(pc),
            "object": hex(MOBILE_CHAISE_OBJECT),
            "cell_value": hex(MOBILE_CHAISE_PC_CELL_VALUE),
            "cell_count": len(actual_object_offsets),
            "peep_slot_cell_value": hex(MOBILE_CHAISE_PC_SLOT_CELL_VALUE),
            "peep_slot_cell": list(MOBILE_CHAISE_PC_SLOT_CELL),
        })
    manifest["MobileChaisePCFmaps"] = {
        "status": "validated minimal EObject plus required peep-slot optional payloads",
        "records": records,
        "translated_mobile_peep_slot_marker": {
            "mobile": "0x01b09800",
            "desktop": hex(MOBILE_CHAISE_PC_SLOT_CELL_VALUE),
            "object": "0x13",
        },
    }


def validate_mobile_patio_umbrella_pc_fmap(manifest):
    filename = "Patio_umbrella.png.fmap"
    mobile_path = MOBILE_FURNITURE_BEHAVIOR_SOURCE_DIR / filename
    pc_path = MOBILE_FURNITURE_BEHAVIOR_PC_FMAP_DIR / filename
    mobile = mobile_path.read_bytes()
    pc = pc_path.read_bytes()
    if len(pc) != len(mobile) or pc[:4] != b"QAMF":
        raise RuntimeError(f"Invalid PC patio umbrella furniture map: {pc_path}")
    width, height = struct.unpack_from("<ii", pc, 24)
    if (width, height) != (15, 17):
        raise RuntimeError(f"Unexpected PC patio umbrella grid: {filename}")
    grid_end = 32 + width * height * 4
    if pc[:32] != mobile[:32] or pc[grid_end:] != mobile[grid_end:]:
        raise RuntimeError(f"PC patio umbrella header/trailer drifted: {filename}")
    expected_offsets = {
        32 + (y * width + x) * 4
        for x, y in MOBILE_PATIO_UMBRELLA_PC_CELLS
    }
    actual_offsets = set()
    for offset in range(32, grid_end, 4):
        value = struct.unpack_from("<I", pc, offset)[0]
