def validate_native_north_bathroom_malfunction_selection(manifest):
    obj = CoffObject(PATCHED / "theMainScene.obj")
    update = obj.symbol("?UpdateScene@theMainScene@@MAEXXZ")
    section = obj.section(update.section)
    data = bytes(obj.buf[section.raw_ptr + update.value : section.raw_ptr + section.raw_size])
    cases = [
        {
            "name": "north shower leak",
            "case_offset": 0x459,
            "permanent_fix_offset": 0x11C,
            "upgrade_check_offset": 0x469,
            "prop_offset": 0x480,
            "prop": 0x49,
        },
        {
            "name": "north toilet leak",
            "case_offset": 0x487,
            "permanent_fix_offset": 0x10C,
            "upgrade_check_offset": 0x497,
            "prop_offset": 0x4AA,
            "prop": 0x48,
        },
        {
            "name": "north sink leak",
            "case_offset": 0x4AE,
            "permanent_fix_offset": 0x12C,
            "upgrade_check_offset": 0x4BA,
            "prop_offset": 0x4CD,
            "prop": 0x4A,
        },
    ]
    for row in cases:
        case_off = row["case_offset"]
        state_pattern = b"\x8B\x43\x14\x80\xB8" + struct.pack(
            "<I",
            row["permanent_fix_offset"],
        ) + b"\x00"
        if data[case_off : case_off + len(state_pattern)] != state_pattern:
            raise RuntimeError(f"Native {row['name']} permanent-fix gate drifted")
        upgrade_off = row["upgrade_check_offset"]
        if data[upgrade_off : upgrade_off + 5] != b"\x68\xE6\x00\x00\x00":
            raise RuntimeError(f"Native {row['name']} renovation gate drifted")
        prop_off = row["prop_offset"]
        if data[prop_off : prop_off + 2] != b"\x6A" + bytes([row["prop"]]):
            raise RuntimeError(f"Native {row['name']} SetProp selection drifted")

    manifest["native_north_bathroom_malfunctions"] = {
        "status": "validated and preserved",
        "function": "?UpdateScene@theMainScene@@MAEXXZ",
        "selection": "stock standalone random-malfunction jump-table cases",
        "second_bathroom_upgrade": "0xE6",
        "cases": [
            {
                "name": row["name"],
                "prop": hex(row["prop"]),
                "permanent_fix_world_state_byte": hex(row["permanent_fix_offset"]),
            }
            for row in cases
        ],
    }


def validate_native_dryer_lint_fire_contract(manifest):
    """Keep the stock Dryer-gated lint fire and its Handyman repair path intact."""

    def relocation_target(obj, section, vaddr):
        for index in range(section.nreloc):
            reloc_off = section.reloc_ptr + index * 10
            reloc_vaddr, symbol_index, _rtype = struct.unpack_from("<IIH", obj.buf, reloc_off)
            if reloc_vaddr == vaddr:
                return obj.symbol_by_index[symbol_index]
        raise RuntimeError(f"Missing relocation at section offset {vaddr:#x}")

    main_obj = CoffObject(PATCHED / "theMainScene.obj")
    update = main_obj.symbol("?UpdateScene@theMainScene@@MAEXXZ")
    update_sec = main_obj.section(update.section)
    update_data = bytes(
        main_obj.buf[
            update_sec.raw_ptr + update.value :
            update_sec.raw_ptr + update_sec.raw_size
        ]
    )
    if update_data[0x41D : 0x427] != b"\x8B\x43\x14\x80\xB8\xCC\x00\x00\x00\x00":
        raise RuntimeError("Native Dryer lint-fire permanent-fix gate drifted")
    if update_data[0x443 : 0x445] != b"\x6A\x48":
        raise RuntimeError("Native Dryer lint-fire furniture gate drifted")
    if update_data[0x452 : 0x454] != b"\x6A\x21":
        raise RuntimeError("Native Dryer lint-fire SetProp selection drifted")
    find_target = relocation_target(main_obj, update_sec, update.value + 0x446)
    if find_target.name != "?FindFurniture@CFurnitureManager@@QAE_NW4EObject@CContentMap@@UldwPoint@@AAUsFurnitureInfo2@@_NH3@Z":
        raise RuntimeError("Native Dryer lint-fire furniture lookup no longer calls FindFurniture")
    dryer_case = relocation_target(main_obj, update_sec, update.value + 0x1094)
    if dryer_case.section != update.section or dryer_case.value != update.value + 0x41D:
        raise RuntimeError("Native random-malfunction jump table no longer reaches the Dryer case")

    behavior_obj = CoffObject(PATCHED / "Behavior.obj")
    fixing = behavior_obj.symbol("?FixingLaundryFire@CBehavior@@CAXAAVCVillager@@@Z")
    fixing_sec = behavior_obj.section(fixing.section)
    fixing_data = bytes(
        behavior_obj.buf[
            fixing_sec.raw_ptr + fixing.value :
            fixing_sec.raw_ptr + fixing_sec.raw_size
        ]
    )
    if fixing_data[0x10B : 0x111] != b"\x6A\x21\x8B\xCE\xE8\x00":
        raise RuntimeError("Native Dryer lint-fire repair no longer deactivates prop 0x21")
    if fixing_data[0x114 : 0x11B] != b"\x6A\x00\x6A\x3A\x8B\xCE\xE8":
        raise RuntimeError("Native Dryer lint-fire repair no longer advances Handyman 0x3A")

    manifest["native_dryer_lint_fire"] = {
        "status": "validated and preserved",
        "selection": "stock random-malfunction jump-table case",
        "dryer_object": "0x48",
        "malfunction_prop": "0x21",
        "permanent_fix_world_state_byte": "0xcc",
        "requires_dryer_in_house": True,
        "repair_behavior": "CBehavior::FixingLaundryFire",
        "repair_clears_prop": "0x21",
        "repair_advances_achievement": "0x3a",
        "achievement_name": "Handyman",
    }


def validate_base_game_payload_intact(manifest):
    """Every base-game file must survive the build.

    This is the guard for the regression that produced it: a build shipped 119
    of the 242 stock Assets, so furniture had no footprint maps -- villagers
    walked through walls and hotspots stopped registering. Nothing checked
    Assets contents before; the contract only asserted the directory existed.

    Presence is required for every indexed file. Content is required to be
    byte-identical for Assets EXCEPT where a patch legitimately replaces a
    stock footprint map (the mobile furniture behaviours do exactly that), and
    those replacements have to be declared by the build itself -- an
    undeclared difference is a corruption and fails.

    Images are presence-only: optional visual mods replace stock art by
    design, and which ones depends on the enabled patch set.
    """
    index = clean_base_game_index()
    declared = set()
    for key in (
        "mobile_furniture_behavior_assets",
        "behavior_assets",
    ):
        section = manifest.get(key)
        if not isinstance(section, dict):
            continue
        for subkey, entries in section.items():
            # "missing" lists files the build deliberately did NOT write, so
            # it declares nothing.
            if subkey == "missing" or not isinstance(entries, list):
                continue
            for item in entries:
                if isinstance(item, dict):
                    # Donor records name the file they wrote as "target";
                    # evidence records use "filename".
                    for field in ("target", "filename"):
                        value = item.get(field)
                        if isinstance(value, str) and value.endswith(".fmap"):
                            declared.add(value)
                elif isinstance(item, str) and item.endswith(".fmap"):
                    declared.add(item)

    missing = []
    altered = []
    for relative, meta in sorted(index.items()):
        path = OUT / relative
        if not path.is_file():
            missing.append(relative)
            continue
        if not relative.startswith("Assets/"):
            continue
        name = relative.split("/", 1)[1]
        if name in declared:
            continue
        if path.stat().st_size != meta["size"] or sha256_of(path) != meta["sha256"]:
            altered.append(relative)

    if missing or altered:
        lines = []
        if missing:
            lines.append(
                f"{len(missing)} base-game file(s) are missing from the build: "
                + ", ".join(missing[:12])
                + (" ..." if len(missing) > 12 else "")
            )
        if altered:
            lines.append(
                f"{len(altered)} base-game asset(s) differ from a clean install "
                "without the build declaring the replacement: "
                + ", ".join(altered[:12])
                + (" ..." if len(altered) > 12 else "")
            )
        raise RuntimeError("Base-game payload check failed:\n- " + "\n- ".join(lines))

    manifest["base_game_payload_intact"] = {
        "status": "validated",
        "checked": len(index),
        "assets_checked": sum(1 for k in index if k.startswith("Assets/")),
        "images_checked": sum(1 for k in index if k.startswith("Images/")),
        "declared_replacements": sorted(declared),
        "guards": (
            "every indexed base-game file must be present; stock Assets must "
            "be byte-identical unless the build declared replacing them"
        ),
    }


def validate_mod_assets_present(manifest):
    """Every asset a patch actually staged must still be in the payload.

    Mirror of validate_base_game_payload_intact: that guard restores and
    protects the stock files, this one makes sure repairing them can never
    quietly drop the mod-supplied maps layered on top.

    The records are read by shape rather than by scanning for ".fmap"
    anywhere, because two manifest sections list files that are deliberately
    ABSENT -- behavior_assets["missing"] and the evidence items whose source
    was missing from the supplied mobile OBB. Requiring those to exist would
    fail every build.
    """
    staged = set()

    behavior = manifest.get("behavior_assets")
    if isinstance(behavior, dict):
        for key, entries in behavior.items():
            if key == "missing" or not isinstance(entries, list):
                continue
            for entry in entries:
                target = entry.get("target") if isinstance(entry, dict) else None
                if isinstance(target, str) and target.endswith(".fmap"):
                    staged.add(target)

    for section_name in ("MobileFurnitureBehaviorEvidence", "MobileGroupHolidayPCFmaps"):
        section = manifest.get(section_name)
        if not isinstance(section, dict):
            continue
        for entries in section.values():
            if not isinstance(entries, list):
                continue
            for entry in entries:
                if not isinstance(entry, dict):
                    continue
                name = entry.get("filename")
                status = str(entry.get("source_status", ""))
                if not isinstance(name, str) or not name.endswith(".fmap"):
                    continue
                if status.startswith("missing"):
                    continue
                staged.add(name)

    assets = OUT / "Assets"
    missing = sorted(name for name in staged if not (assets / name).is_file())

    # Deliberately no rule about WHICH extra files may sit in Assets. An
    # earlier version of this guard required everything a clean install does
    # not have to be a .fmap, and that is simply wrong: patches legitimately
    # stage mobile sound .ogg files, .dat and PkgInfo into Assets, and a
    # release-seeded build carries 562 of them. Stock files are protected by
    # name and hash above, which is the property that actually matters.
    stock = set(clean_base_game_files_under("Assets"))

    errors = []
    if missing:
        errors.append(
            f"{len(missing)} patch-supplied asset(s) missing from the build: "
            + ", ".join(missing[:12])
            + (" ..." if len(missing) > 12 else "")
        )
    # A guard that inspected nothing is worse than no guard: it reports success
    # having checked zero files. If the behaviour stager ran, it staged maps.
    if isinstance(behavior, dict) and not staged:
        errors.append(
            "the mod-asset guard found no staged assets to check even though "
            "behavior_assets is present, so it would have passed vacuously"
        )
    if errors:
        raise RuntimeError("Patch-supplied asset check failed:\n- " + "\n- ".join(errors))

    manifest["mod_assets_present"] = {
        "status": "validated",
        "checked": len(staged),
        "patch_supplied_in_payload": sum(
            1 for path in assets.iterdir() if path.is_file() and path.name not in stock
        ),
        "guards": (
            "every staged .fmap is present; extra non-stock files in Assets "
            "are allowed, because patches legitimately stage mobile sounds "
            "and data files there"
        ),
    }


def validate_runtime_payload_contract(manifest):
    errors = []
    for filename in VANILLA_RUNTIME_REQUIRED_FILES:
        if not (OUT / filename).is_file():
            errors.append(f"missing required runtime file: {filename}")
    for dirname in OFFICIAL_B93_RELEASE_REQUIRED_DIRS:
        if not (OUT / dirname).is_dir():
            errors.append(f"missing required runtime directory: {dirname}")

    images_dir = OUT / "Images"
    sounds_dir = OUT / "Sounds"
    image_count = count_files(images_dir)
    sound_count = count_files(sounds_dir)
    if image_count < RUNTIME_MIN_IMAGE_FILE_COUNT:
        errors.append(f"Images payload is incomplete: {image_count} files, expected at least {RUNTIME_MIN_IMAGE_FILE_COUNT}")
    if sound_count < RUNTIME_MIN_SOUND_FILE_COUNT:
        errors.append(f"Sounds payload is incomplete: {sound_count} files, expected at least {RUNTIME_MIN_SOUND_FILE_COUNT}")

    for filename in RUNTIME_REQUIRED_IMAGE_FILES:
        if not (images_dir / filename).is_file():
            errors.append(f"missing required base image: Images/{filename}")
    for filename in DESKTOP_RUNTIME_DLL_NAMES:
        if not (OUT / filename).is_file():
            errors.append(f"missing required desktop runtime DLL: {filename}")

    for dirname in REMOVED_LEGACY_PACKAGE_DIRS:
        if (OUT / dirname).exists():
            errors.append(f"legacy package directory should not be present in official B93-shaped builds: {dirname}")

    if errors:
        raise RuntimeError("Runtime payload contract failed:\n- " + "\n- ".join(errors))

    validate_base_game_payload_intact(manifest)
    validate_mod_assets_present(manifest)

    manifest["runtime_payload_contract"] = {
        "status": "validated",
        "images_file_count": image_count,
        "sounds_file_count": sound_count,
        "required_root_files": list(VANILLA_RUNTIME_REQUIRED_FILES),
        "required_root_dirs": list(OFFICIAL_B93_RELEASE_REQUIRED_DIRS),
        "required_images": list(RUNTIME_REQUIRED_IMAGE_FILES),
        "required_dlls": list(DESKTOP_RUNTIME_DLL_NAMES),
        "official_b93_release_asset": OFFICIAL_B93_RELEASE_ASSET,
        "official_b93_release_sha256": OFFICIAL_B93_RELEASE_SHA256,
        "removed_legacy_dirs": list(REMOVED_LEGACY_PACKAGE_DIRS),
        "release_note": "The standalone B98-current ZIP is the package baseline. Future release folders must preserve its runtime/support folder shape, use a short VF2-B##-Release name, and replace only the packaged EXE with the newest build EXE.",
    }


def validate_custom_achievement_award_hook_objects(manifest):
    errors = []

    def function_data(obj, name):
        sym = obj.symbol(name)
        sec = obj.section(sym.section)
        return bytes(
            obj.buf[sec.raw_ptr + sym.value : sec.raw_ptr + sec.raw_size]
        ), sym, sec

    def relocation_targets(obj, sym, sec):
        return {
            vaddr - sym.value: (obj.symbol_by_index[symbol_index].name, rtype)
            for vaddr, symbol_index, rtype in (
                struct.unpack_from("<IIH", obj.buf, sec.reloc_ptr + index * 10)
                for index in range(sec.nreloc)
            )
            if sym.value <= vaddr < sec.raw_size
        }

    store_obj = CoffObject(PATCHED / "ScrollingStoreScene.obj")
    purchase_data, purchase_sym, purchase_sec = function_data(
        store_obj, "?HandlePurchaseItem@CScrollingStoreScene@@AAEXXZ"
    )
    # The leading compare is `cmp eax, <first id past the last item>`, which
    # the store patch rewrites whenever items are added. Pinning 0x328 here
    # made adding any item fail this contract as a "call window drifted",
    # which names the symptom and not the cause. Derive the bound the way the
    # patch does, so the check tracks real drift rather than the item count.
    store_item_bound = max(item_id_for(index) for index in range(len(ITEMS))) + 1
    expected_purchase_window = (
        b"\x3D" + struct.pack("<I", store_item_bound)
        + b"\x7D\x39\x50"
        + b"\xB9\x00\x00\x00\x00\xE8\x00\x00\x00\x00"
        + b"\xE8\x00\x00\x00\x00\x8B\xC8\xE8\x00\x00\x00\x00"
    )
    if purchase_data[0x2D0:0x2EE] != expected_purchase_window:
        errors.append("HandlePurchaseItem purchase-award call window drifted")
    if purchase_data[0x360:0x36C] != b"\xE8\x00\x00\x00\x00\x8B\xC8\xE8\x00\x00\x00\x00":
        errors.append("HandlePurchaseItem stock save call window drifted")
    purchase_targets = relocation_targets(store_obj, purchase_sym, purchase_sec)
    expected_purchase_targets = {
        0x2D9: ("?FurnitureManager@@3VCFurnitureManager@@A", 0x0006),
        0x2DE: (
            "?AddToStorageAndAward@CFurnitureManager@@QAE_NW4EInventoryItem@@@Z",
            IMAGE_REL_I386_REL32,
        ),
        0x2E3: ("?Get@theMainScene@@SAPAV1@XZ", IMAGE_REL_I386_REL32),
        0x2EA: ("?TurnDecorateModeOn@theMainScene@@QAEXXZ", IMAGE_REL_I386_REL32),
        0x361: ("?Get@theGameState@@SAPAV1@XZ", IMAGE_REL_I386_REL32),
        0x368: ("?SaveCurrentGame@theGameState@@QAE_NXZ", IMAGE_REL_I386_REL32),
    }
    for offset, expected in expected_purchase_targets.items():
        if purchase_targets.get(offset) != expected:
            errors.append(
                f"HandlePurchaseItem relocation {offset:#x} expected {expected}, "
                f"got {purchase_targets.get(offset)}"
            )

    special_helper = PATCHED / "vf2_special_upgrade_effects.cpp"
    helper_text = special_helper.read_text(encoding="ascii") if special_helper.is_file() else ""
    if helper_text.count("enum EInventoryItem") != 1:
        errors.append("special helper must define EInventoryItem exactly once")
    if helper_text.count("class CFurnitureManager") != 1:
        errors.append("special helper must define CFurnitureManager exactly once")
    wrapper_marker = "bool CFurnitureManager::AddToStorageAndAward(EInventoryItem item)"
    if wrapper_marker not in helper_text:
        errors.append("special helper is missing the same-thiscall purchase wrapper")
    else:
        wrapper = helper_text.split(wrapper_marker, 1)[1].split("struct sFurnitureInfo", 1)[0]
        required_order = (
            "bool stored = AddToStorage(item);",
            "if (stored)",
            "VF2DispatchSuccessfulFurniturePurchase(item);",
            "return stored;",
        )
        try:
            positions = [wrapper.index(token) for token in required_order]
            if positions != sorted(positions):
                errors.append("purchase wrapper does not call native first and return its exact bool")
        except ValueError:
            errors.append("purchase wrapper source contract is incomplete")

    behavior_contract = {
        "enabled": ENABLE_BEHAVIOR_PATCHES,
        "praise_hook": None,
        "scold_hook": None,
    }
    if ENABLE_BEHAVIOR_PATCHES:
        main_obj = CoffObject(PATCHED / "theMainScene.obj")
        stock_main = CoffObject(SRC_OBJS / "theMainScene.obj")
        for function_name, replacements in (
            (
                "?InvokeReward@theMainScene@@IAEXAAVCVillager@@@Z",
                {
                    0x36B: "_VF2PraiseCaptureAndForget@8",
                    0x3B7: "_VF2PraiseStartAndRestore@4",
                },
            ),
            (
                "?InvokeScolding@theMainScene@@IAEXAAVCVillager@@@Z",
                {0x118: "_VF2ScoldAwardAndForget@8"},
            ),
        ):
            patched_data, patched_sym, patched_sec = function_data(main_obj, function_name)
            stock_data, stock_sym, stock_sec = function_data(stock_main, function_name)
            if patched_data != stock_data:
                errors.append(f"{function_name} instruction bytes changed instead of relocation-only hooks")
            patched_targets = relocation_targets(main_obj, patched_sym, patched_sec)
            stock_targets = relocation_targets(stock_main, stock_sym, stock_sec)
            for offset, stock_target in stock_targets.items():
                expected_name = replacements.get(offset, stock_target[0])
                expected = (expected_name, stock_target[1])
                if patched_targets.get(offset) != expected:
                    errors.append(
                        f"{function_name} relocation {offset:#x} expected {expected}, "
                        f"got {patched_targets.get(offset)}"
                    )
        behavior_helper = PATCHED / "vf2_spontaneous_behaviors.cpp"
        behavior_text = behavior_helper.read_text(encoding="ascii") if behavior_helper.is_file() else ""
        for label, goal_id in CUSTOM_ACHIEVEMENT_PRAISE_LABEL_GOALS.items():
            if (
                f'VF2RawBehaviorLabelEquals(label, "{label}")' not in behavior_text
                or f"Achievement.SetComplete((EAchievement)0x{goal_id:X})" not in behavior_text
            ):
                errors.append(f"behavior helper missing exact praise award {label!r}")
        scold_marker = 'extern "C" void __stdcall VF2ScoldAwardAndForget'
        if scold_marker not in behavior_text:
            errors.append("behavior helper missing scold wrapper")
        else:
            scold_source = behavior_text.split(scold_marker, 1)[1].split("class CFurnitureManager", 1)[0]
            if scold_source.count("plans->ForgetPlans") != 1:
                errors.append("scold wrapper must call native ForgetPlans exactly once")
            if "VF2RestoreRawPraiseLabel" in scold_source:
                errors.append("scold wrapper must not restore the old label")
        behavior_contract = {
            "enabled": True,
            "praise_hook": "InvokeReward+0x36B",
            "praise_restore_hook": "InvokeReward+0x3B7",
            "scold_hook": "InvokeScolding+0x118",
            "relocation_only": True,
            "over_praise_paths_unchanged": True,
        }

    if errors:
        raise RuntimeError(
            "Custom achievement award-hook object contract failed:\n- "
            + "\n- ".join(errors)
        )
    manifest["custom_achievement_award_hook_contract"] = {
        "status": "validated",
        "purchase": {
            "hook": "HandlePurchaseItem+0x2DE",
            "wrapper": "CFurnitureManager::AddToStorageAndAward",
            "same_thiscall_abi": True,
            "native_result_preserved": True,
            "stock_save_relocation": "0x368",
        },
        "behavior": behavior_contract,
    }


def patch_maximum_resource_achievement_callsites(manifest):
    """Route native resource mutations through ABI-compatible goal observers."""
    wrappers = {
        "?Adjust@CMoney@@QAEXM_N@Z": "@VF2MoneyAdjustAndAward@16",
        "?Set@CMoney@@QAEXN@Z": "@VF2MoneySetAndAward@16",
        "?Adjust@CFoodStore@@QAEXH@Z": "@VF2FoodAdjustAndAward@12",
        "?LoadState@CMoney@@QAE?B_NABUSSaveState@1@@Z": (
            "@VF2MoneyLoadStateAndReconcile@12"
        ),
    }
    patched = {native: [] for native in wrappers}

    for path in sorted(PATCHED.glob("*.obj")):
        obj = CoffObject(path)
        matches = []
        for section in obj.sections:
            for index in range(section.nreloc):
                vaddr, symbol_index, relocation_type = struct.unpack_from(
                    "<IIH", obj.buf, section.reloc_ptr + index * 10
                )
                symbol = obj.symbol_by_index.get(symbol_index)
                if (
                    symbol is not None
                    and symbol.name in wrappers
                    and relocation_type == IMAGE_REL_I386_REL32
                ):
                    matches.append(
                        (section.index, vaddr, symbol.name, relocation_type)
                    )
        if not matches:
            continue

        wrapper_symbols = {
            native: obj.append_undefined_symbol(wrappers[native])
            for _section, _vaddr, native, _relocation_type in matches
        }
        for section, vaddr, native, relocation_type in matches:
            obj.retarget_relocation(
                section,
                vaddr,
                wrapper_symbols[native],
                relocation_type,
            )
            patched[native].append(
                {
                    "object": path.name,
                    "section": section,
                    "offset": hex(vaddr),
                    "wrapper": wrappers[native],
                }
            )
        obj.write(path)

    missing = [native for native, callsites in patched.items() if not callsites]
    if missing:
        raise RuntimeError(
            "Maximum-resource achievement observers found no native calls for: "
            + ", ".join(missing)
        )
    if len(patched["?LoadState@CMoney@@QAE?B_NABUSSaveState@1@@Z"]) != 1:
        raise RuntimeError(
            "Expected exactly one CMoney::LoadState reconciliation callsite"
        )

    manifest["maximum_resource_achievement_hooks"] = {
        "status": "patched",
        "money_goal": {
            "achievement_id": "0x83",
            "threshold": "4000000000.0",
        },
        "food_goal": {
            "achievement_id": "0x84",
            "threshold": "0x7fffffff",
        },
        "callsites": patched,
        "load_reconciliation": "CMoney::LoadState after FoodStore and achievements",
        "reset_semantics": (
            "event-driven; reset remains cleared until a resource mutation "
            "or successful load-state reconciliation"
        ),
    }


def main():
    OUT.mkdir(parents=True, exist_ok=True)
    copy_obj_tree()
    manifest = {
        "native_array_contract": build_native_array_contract(),
        "generation_lock_distribution": GENERATION_LOCK_ASSIGNMENT_SUMMARY,
        "items": [
            {
                "name": name,
                "item_id": hex(item_id_for(i)),
                "image_id": hex(image_id_for(i)),
                "donor_item": hex(donor),
                "list": list_name,
                "path": path,
                "mobile_data": MOBILE_DATA_BY_PATH[path],
            }
            for i, (name, donor, list_name, path) in enumerate(ITEMS)
        ]
    }
    patch_mobile_sound_routes(manifest)
    seed_from_previous_build(manifest)
    snapshot_seeded_inherited_art()
    validate_stock_image_ids()
    sync_vanilla_runtime_payload(manifest)
    patch_furniture_manager(manifest)
    patch_added_furniture_click_aliases(manifest)
    patch_visible_special_upgrades(manifest)
    patch_inventory_manager(manifest)
    patch_house_renovations(manifest)
    patch_scrolling_store_scene(manifest)
    patch_purchase_dialog(manifest)
    patch_options_dialog(manifest)
    write_outfit_store_helpers(manifest)
    # The tiny house is baked into main_BG_ws.png, so install the additive
    # coordinate overlay after the helper source exists and before later
    # main-scene edits can change its anchor.
    patch_main_scene_random_tip_click(manifest)
    patch_tool_tray_outfit_normalization(manifest)
    manifest["outfit_apply_body_resolver"] = {
        "status": "disabled for B97 stability; stock theMainScene GetOutfit callsites retained",
        "replacement": "CInventoryManager::GetOutfit hook now reads the selected synthetic ToolTray item directly",
        "reason": "B96 final-apply callsite replacement made generated Outfit-section items crash on apply.",
    }
    patch_string_manager(manifest)
    patch_special_upgrade_titles(manifest)
    # The achievement table/strings/save layout are identical in every
    # executable; optional settings only filter order and completion routes.
    patch_custom_achievements(manifest)
    patch_achiever_load_reconciliation(manifest)
    # Always link the dormant B152 hook. The offline patcher's exact-SHA
    # post-asset phase changes .vf2preg from 00 to 01 only when selected, so
    # this feature adds no executable-matrix dimension.
    patch_allow_older_pregnancies(manifest)
    patch_next_generation_age_gate(manifest)
    # Force Marriage Email is deliberately a normal queued proposal.  Do not
    # install the former cheat-only Reject reroll route; native Accept,
    # Reject, and close behavior must remain untouched.
    # Adoption Services is deliberately left ENTIRELY BASE-GAME.
    #
    # patch_vf3_style_child_adoption_chooser replaced the stock spawn route in
    # CScrollingStoreScene::HandleUpgrade (+0x57A) with a helper that put up a
    # "baby or older child" message box and spawned the adoptee itself.
    # Purchasing Adoption Services then crashed with an access violation
    # whose faulting module was "unknown" at address 0x1D7 -- execution had
    # left every loaded module, the signature of a call through a corrupted
    # return address or function pointer rather than a bad data read.
    #
    # The helper also did not reproduce the stock call: the native route is
    # SpawnSpecificPeep(age=1, gender=-1, body=0x3C) and the helper passed
    # body=-1 with an explicit gender, and it constructed a
    # theMessageBoxDlg in a 0x300-byte stack buffer standing in for a class
    # whose real size is not pinned anywhere.
    #
    # Rather than guess at which of those was fatal, the whole route is
    # reverted so HandleUpgrade's adoption path is byte-identical to stock.
    # patch_vf3_style_child_adoption_chooser(manifest)
    # Crash fix: ldwScene::SetActive dereferences a null field_4 for one
    # native scene slot once a family reaches six children (see the
    # function docstring for the confirmed root cause). Always installed;
    # it is a byte-identical no-op for every properly-bound scene.
    patch_ldwscene_setactive_null_guard(manifest)
    # Do not alter CDatingScene::HandleMessage. The proposal scene must keep
    # the base-game candidate, Accept, Reject, close, and state-write bytes.
    # Allow Reroll of Marriage Candidates: the dedicated .vf2rero-gated hook
    # in patch_marriage_candidate_reroll() was fully implemented and tested
    # in isolation but never called from here, so the purchasable row
    # persisted a toggle that gameplay never read - buying it did nothing.
    # Wire it in for real.
    patch_marriage_candidate_reroll(manifest)
    # Same-sex support is a default-off runtime byte.  Its only proposal edit
    # occurs after GetVillager returns the spawned candidate; parent storage,
    # selectors, and the native private-time target remain stock.  The
    # shared drop classifier also admits the separate Behavior-Patches
    # six-child opposite-sex rule.
    patch_same_sex_marriage(manifest)
    # Accept's own Matriarch/Patriarch finalization guard is the one part of
    # HandleMessage that does need a hook for same-sex marriages to actually
    # register -- see patch_marriage_finalization_for_same_sex()'s docstring.
    # Fixes "same-sex spouses aren't treated as spouses" at the root: both
    # native spouse accessors back-fill their missing half, which covers all
    # 66 call sites in one change instead of hooking 19 functions.
    # Same-sex couples: bypass only the same-gender refusal at +0xD1, so
    # they reach StartEmbrace's ordinary success path and get behaviour 358,
    # the stock baby-making behaviour. Nothing else in the function is
    # touched -- every refusal, the entry animation and the sound call are
    # base-game. The "private adult romantic time" wording is a label
    # variation on 358 itself, not a different sequence.
    patch_villager_same_sex_embrace(manifest)
    # Force Successful Pregnancy is a one-shot; don't let an unlucky random
    # roll spend it. Only 1846 and 1851 are skipped; every other refusal
    # reason stays base-game.
    patch_force_pregnancy_skips_refusals(manifest)
    # Dropping Anti-spam Software on a computer while it is already
    # installed removes it instead of re-installing it.
    patch_villager_manager_spouse_accessors(manifest)
    patch_marriage_finalization_for_same_sex(manifest)
    # A second, independent site with the identical Matriarch/Patriarch
    # gender-blind check: the villager details screen's "Married" status.
    patch_villager_details_same_sex_married_status(manifest)
    patch_force_successful_pregnancy_callsites(manifest)
    # The optional mortality curve is another exact-SHA dormant-byte hook.
    # Its zero .vf2mort default resumes the untouched stock mortality block.
    patch_older_villager_mortality(manifest)
    patch_longevity_achievement_load_reconciliation(manifest)
    patch_pet_achievement_callsites(manifest)
    patch_family_tree_appearance_achievement_callsites(manifest)
    patch_lifetime_generation_counter(manifest)
    patch_mobile_furniture_behavior_dispatch(manifest)
    if ENABLE_HOLIDAY_ORNAMENTS:
        patch_collectable_item_holiday_ornaments(manifest)
        patch_collectable_holiday_ornament_observers(manifest)
        patch_collection_scene_holiday_ornaments(manifest)
        patch_the_collector_holiday_ornaments(manifest)
    else:
        manifest["HolidayOrnamentsCollection"] = {
            "enabled": False,
            "status": "optional patch not selected",
            "reason": "The matching stock-collection executable intentionally retains the vanilla five-page Collections Chest.",
            "stock_collection_total": 60,
            "mobile_collection_total": 72,
            "collectable_range": f"{hex(HOLIDAY_ORNAMENT_COLLECTABLE_START)}-{hex(HOLIDAY_ORNAMENT_COLLECTABLE_END)}",
            "selection": "Enable Holiday Ornaments in the offline patcher to install the fully linked six-page executable and artwork.",
        }
    if ENABLE_BEHAVIOR_PATCHES:
        patch_invisible_hammock_drop_action(manifest)
        patch_spontaneous_behaviors(manifest)
        patch_bookshelf_reading_behavior(manifest)
        patch_radio_drop_behavior(manifest)
        patch_behavior_label_variants(manifest)
        patch_arcade_behavior_labels(manifest)
        # A couple at six children takes the ordinary romantic path instead
        # of refusing; the behaviour is relabelled rather than replaced.
        patch_six_child_private_time(manifest)
        # Same-sex partners take the two different halves of the sequence.
        patch_embrace_role_split(manifest)
        manifest["BehaviorPatchesGate"] = {
            "enabled": True,
            "environment": "VF2_ENABLE_BEHAVIOR_PATCHES",
            "offline_patcher_setting": "behavior_patches",
            "six_child_private_romantic_time": {
                "enabled": True,
                "condition": "exact current-generation opposite-sex adult spouse pair with child count >= 6; an active same-sex pair is covered at any child count by VF2IsSameSexMarriage()",
                "child_count_field": "CFamilyTree current record +0x1B4",
                "native_action": "HandleDropOnVillager +0x21A refusal replaced with a jump to +0x256, the target every native gate uses to let the drop proceed",
                "pregnancy": "0%; TryToMakeBaby returns before ChanceOfPregnancy/Impregnate",
                "argument": "the native six-child refusal is bypassed for a spouse pair at capacity",
            },
        }
    else:
        patch_mobile_furniture_autonomous_candidates(manifest)
        (PATCHED / "vf2_invisible_hammock.cpp").write_text(
            "// Behavior Patches disabled: stock hammock behavior retained.\n",
            encoding="ascii",
        )
        (PATCHED / "vf2_spontaneous_behaviors.cpp").write_text(
            "// Behavior Patches disabled: stock spontaneous and label behavior retained.\n",
            encoding="ascii",
        )
        manifest["BehaviorPatchesGate"] = {
            "enabled": False,
            "environment": "VF2_ENABLE_BEHAVIOR_PATCHES",
            "offline_patcher_setting": "behavior_patches",
            "status": "stock behavior objects preserved for the behavior-disabled core executable",
            "six_child_private_romantic_time": {
                "enabled": False,
                "status": "stock private-romantic-time and pregnancy routes preserved",
            },
        }
    patch_mobile_furniture_external_autonomous_selection(manifest)
    # This final pass intentionally runs after label wrappers so the mobile
    # dispatchers can preserve those wrappers as their build-specific fallback.
    patch_mobile_furniture_behavior_macros(manifest)
    patch_mobile_patio_prop_execution(manifest)
    patch_maximum_resource_achievement_callsites(manifest)
    validate_custom_achievement_award_hook_objects(manifest)
    if ENABLE_DEBUGGER_FEATURES:
        patch_debug_features(manifest)
    else:
        write_disabled_debug_features(manifest)
    patch_mobile_renovation_renderer(manifest)
    if ENABLE_ISLAND_EVENTS:
        patch_island_events(manifest)
        patch_power_failure_event(manifest)
    else:
        # The legacy linker response contains the event helper object even
        # while grafted mobile events are disabled for stability.
        (PATCHED / "vf2_island_events.cpp").write_text(
            'extern "C" void __cdecl VF2RegisterMobileIslandEvents(void **) {}\n',
            encoding="ascii",
        )
        manifest["IslandEvents"] = {
            "added": [],
            "status": (
                "disabled pending exact-build runtime crash certification; "
                "historical linked builds reported crashes"
            ),
            "evidence_classification": (
                "historical runtime reports plus prior static storage defect; "
                "no current exact-build WER or dump"
            ),
        }
        manifest["PowerFailure"] = {
            "status": "disabled with Island Events",
            "reason": "Power Failure lifecycle detours are held out with the ABI-sensitive Island Events overlay.",
        }
    apply_second_bathroom_leaks(manifest)
    if ENABLE_HOLIDAY_BODY_TYPES:
        sync_original_villager_sprite_sheets(manifest)
        sync_holiday_body_runtime_frames(manifest)
        sync_holiday_detail_body_frames(manifest)
    else:
        sync_original_villager_sprite_sheets(manifest)
        manifest["holiday_detail_body_frames"] = {
            "status": "disabled; stock highrez_bodies_final2.png rows 0-49 retained",
            "body_values": list(HOLIDAY_BODY_VALUES),
        }
    sync_desktop_runtime_dlls(manifest)
    # The reference sets glob the invisible sprites that exist, so the
    # sprites have to be generated first. With the collection running
    # ahead of them, a clean or seeded build produced OptionalVisualMods
    # folders that omitted every newly added invisible item, and the
    # transparent-graphics setting then had nothing to swap -- leaving the
    # base art visible on furniture that is meant to be invisible.
    sync_invisible_outdoor_sprites(manifest)
    sync_transparent_base_furniture_sprites(manifest)
    sync_invisible_furniture_reference_sets(manifest)
    sync_optional_visual_mod_sources(manifest)
    sync_mobile_renovation_art_sources(manifest)
    sync_ai_generated_bathroom2_assets(manifest)
    sync_mobile_sound_assets(manifest)
    sync_outfit_store_icon_art(manifest)
    sync_visible_special_upgrade_icon_art(manifest)
    if ENABLE_HOLIDAY_ORNAMENTS:
        sync_holiday_ornament_collection_art(manifest)
        validate_holiday_ornament_collectables_small_variants(manifest)
        validate_holiday_ornament_native_contract(manifest)
    else:
        remove_holiday_ornament_collection_art(manifest)
    patch_graphics_manager(manifest)
    patch_bathroom1_curtain_decal(manifest)
    patch_floating_anim_table(manifest)
    if ENABLE_HOLIDAY_BODY_TYPES:
        write_holiday_body_draw_helper(manifest)
        patch_holiday_body_draw_redirect(manifest)
        preserve_holiday_body_link_lookup_fallback(manifest)
    sync_generation_lock_art(manifest)
    sync_vf3_living_room_sprite_strips(manifest)
    sync_vf3_tv_sprite_strips(manifest)
    sync_vf3_tv_animation_sheets(manifest)
    if ENABLE_HOLIDAY_BODY_TYPES:
        sync_separated_villager_sheets(manifest)
        manifest["holiday_body_types"] = {
            "status": "folder-backed runtime renderer enabled",
            "body_values": list(HOLIDAY_BODY_VALUES),
            "source_sets": list(HOLIDAY_BODY_SET_IDS),
            "spritesheets": "not expanded; original sheets remain fallback",
        }
    else:
        manifest["holiday_body_types"] = {
            "status": "disabled; stock body rows 0-49 retained",
            "reason": "B54 restores base-game villager body behavior",
        }
        manifest["holiday_body_lookup"] = {
            "status": "not patched; stock animator body-row clamp retained",
        }
    seed_mobile_furniture_behavior_evidence(manifest)
    validate_mobile_chaise_pc_fmaps(manifest)
    validate_mobile_patio_umbrella_pc_fmap(manifest)
    validate_mobile_patio_table_pc_fmap(manifest)
    validate_mobile_picnic_table_pc_fmap(manifest)
    validate_mobile_birthday_cake_pc_fmap(manifest)
    validate_mobile_birthday_presents_pc_fmap(manifest)
    validate_mobile_birthday_balloons_pc_fmap(manifest)
    validate_mobile_birthday_banner_pc_fmap(manifest)
    validate_mobile_group_holiday_pc_fmaps(manifest)
    validate_mobile_xmas_stocking_pc_fmaps(manifest)
    validate_mobile_decorative_only_fmaps(manifest)
    validate_mobile_furniture_route_classification(manifest)
    validate_mobile_furniture_runtime_bindings(manifest)
    validate_store_scrollbar_runtime_contract(manifest)
    sync_behavior_assets(manifest)
    sync_vf3_tv_fmaps(manifest)
    restore_supplied_game_table_sprites(manifest)
    # Before the normaliser: it pads sheet widths to an exact multiple of
    # the frame count, and HomeGymSystemStd is 259px across two frames, so
    # installing afterwards would leave the two orientations sliced at the
    # wrong boundary.
    install_new_furniture_art(manifest)
    normalize_added_furniture_sheets(manifest)
    # Seeded and additive runtime assets may both contribute files; remove
    # development-source names only from known runtime asset directories
    # before writing the final manifest/readiness record.
    filter_desktop_runtime_source_files(manifest)
    write_internal_workings_summary(manifest)
    remove_package_development_artifacts(manifest)
    validate_vf3_tv_animation_contract(manifest)
    validate_vf3_tv_behavior_contract(manifest)
    validate_native_north_bathroom_malfunction_selection(manifest)
    validate_native_dryer_lint_fire_contract(manifest)
    validate_native_mobile_renovation_contract(manifest)
    validate_increase_child_limit_contract(manifest)
    validate_mobile_renovation_style_state_contract(manifest)
    validate_mobile_renovation_renderer_contract(manifest)
    if ENABLE_BEHAVIOR_PATCHES:
        validate_invisible_hammock_behavior_contract(manifest)
    else:
        manifest["invisible_hammock_behavior_contract"] = {
            "status": "disabled by Behavior Patches gate",
            "stock_drop_gate_preserved": True,
        }
    validate_invisible_kids_table_behavior_contract(manifest)
    # After every generator, so images rebuilt from tracked source art keep
    # whatever the generator produced and only genuine gaps are filled, and
    # before the payload/package validation that checks the finished tree.
    restore_preserved_inherited_art(manifest)
    remove_legacy_package_dirs(manifest)
    validate_runtime_payload_contract(manifest)
    validate_clean_package(manifest)
    (OUT / "patch-manifest.json").write_text(
        json.dumps(sanitize_manifest_paths(manifest), indent=2),
        encoding="utf-8",
    )
    print(json.dumps(manifest, indent=2))


if __name__ == "__main__":
    main()
